import type { MvBook } from '../molytvoslov';
const D: MvBook[] = [{"u":"Акафіст Пресвятій Богородиці перед іконою «Іверська»","e":"Akathist to the Theotokos before her icon “Iveron”","secs":[{"h":"Кондак 1","ps":["Взбра́нной Воєво́ді, Влади́чиці на́шей Богоро́диці, похва́льная пі́нія прино́сим Ті раби́ Твої́, я́ко прише́ствієм честна́го о́браза Твоєго́ стяжа́вшії щит крі́пкий, сті́ну необори́мую і стра́жа неуси́пна. Ти же, я́ко іму́щая держа́ву непобіди́мую, покри́й і защити́ нас, Влади́чице, от всіх враго́во ви́димих і неви́димих і ізба́ви от вся́каго вре́да, душе́внаго і тіле́снаго, да зове́м Ті:","Ра́дуйся, блага́я Врата́рнице, две́рі ра́йськія ві́рним отверза́ющая."]},{"h":"Ікос 1","ps":["А́нгел предста́тель по́слан бисть рещи́ Богоро́диці, єгда́ паде́ Єй жре́бій апо́стольськаго служе́нія в землі́ І́верстій: “«Не разлуча́йся Ієрусали́ма, жре́бій же, Тебі́ па́дший, просвіти́ться в послі́днія дні, Ти же і́маши потруди́тися в землі́, ю́же Тебі́ Бог ізво́лить.” Ті́мже зове́м Ті:","Ра́дуйся, Є́юже Єва́нгеліє благовісти́ться;","ра́дуйся, Є́юже і́дольськая пре́лесть упраздни́ться.","Ра́дуйся, Є́юже власть кня́зя тьми разруши́ться;","ра́дуйся, Є́юже Ца́рство Христо́во утверди́ться.","Ра́дуйся, па́дших во тьму ідолослуже́нія к сві́ту Єва́нгелія воззва́ніє;","ра́дуйся, от ра́бства дия́волу в свобо́ду сла́ви чад Бо́жиїх приведе́ніє.","Ра́дуйся, гото́вая служи́тельнице Си́на Своєго́ і Бо́га;","ра́дуйся, послуша́нієм преслуша́ніє Є́ви ісціля́ющая.","Ра́дуйся, висото́ доброді́телей;","ра́дуйся, глубино́ смиренному́дрія.","Ра́дуйся, Є́юже неві́рнії познаю́ть Творця́;","ра́дуйся, Є́юже ві́рнії усиновля́ються Отцю́.","Ра́дуйся, блага́я Врата́рнице, две́рі ра́йськія ві́рним отверза́ющая."]},{"h":"Кондак 2","ps":["Ви́дящи Свята́я Ді́ва ди́вноє і но́воє о Себі́ промишле́ніє Бо́жиє, я́ко раба́ Госпо́дня, при́сно гото́вая твори́ти во́лю Єго́, возопи́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум недоразуміва́ємий глаго́ла а́нгельськаго разу́мен Тебі́, Пречи́стая, творя́ Госпо́дь, упра́ви ше́ствіє Твоє́ ко горі́ Афо́нстій, іді́же пропові́дася Тобо́ю Єва́нгеліє, і та́ко яви́ся жре́бій Твой. Ми же ра́достно вопіє́м:","Ра́дуйся, освяти́вшая Афо́н Свої́м прише́ствієм;","ра́дуйся, низложи́вшая та́мо і́долов.","Ра́дуйся, насади́вшая та́мо ві́ру і́стинную;","ра́дуйся, неві́ріє отгна́вшая.","Ра́дуйся, в жре́бій Себе́ го́ру сію́ ізбра́вшая;","ра́дуйся, благода́ть сему́ мі́сту обіща́вшая.","Ра́дуйся, ві́рним, живу́щим в ней, Пода́тельнице земни́х благ;","ра́дуйся, Спору́чнице ві́чнаго їх спасе́нія.","Ра́дуйся, те́плая Хода́тайце о живу́щих в жре́бії Твоє́м;","ра́дуйся, всіх враго́в їх устраше́ніє.","Ра́дуйся, ми́лость Си́на Своєго́ до сконча́нія ві́ка мі́сту сему́ обіща́вшая;","ра́дуйся, благода́ть Єго́ неотсту́пною би́ти предре́кшая.","Ра́дуйся, блага́я Врата́рнице, две́рі ра́йськія ві́рним отверза́ющая."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго заступле́нієм Богома́тере осіни́ Святу́ю Го́ру і удо́лія і де́бри єя́ я́ко село́ простра́нноє показа́ всім в і́ночеськой жи́зні хотя́щим жа́ти спасе́ніє, внегда́ пі́ти си́це: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи промишле́ніє о жре́бії Своє́м, лю́діх І́верськия землі́, устро́їла єси́ в мі́сті, іді́же Сама́ к Афо́ну приста́ла єси́, оби́тель ро́ду їх, в ти́хоє приста́нище і́щущим спасе́нія, хотя́щи дарова́ти єй в щит і огражде́ніє іко́ну Свою́, да всі взива́ють:","Ра́дуйся, посла́вшая пропові́дницю Єва́нгелія в зе́млю І́верськую;","ра́дуйся, обрати́вшая сію́ страну́ от пре́лести і́дольськой к сві́ту Христо́ву.","Ра́дуйся, о́траслі неув'яда́ємия розго́, ди́вную лозу́ Ни́ні дарова́вшая;","ра́дуйся, от нея́ проізрасти́вшая гро́здіє чуде́с і благи́я ві́ри.","Ра́дуйся, сад духо́вний на Афо́ні насади́вшая;","ра́дуйся, струю́ із него́ просвіще́нія духо́внаго страні́ І́верстій істочи́вшая.","Ра́дуйся, Євфи́мія златослове́сная уста́;","ра́дуйся, Торни́кия непобіди́мая крі́посте.","Ра́дуйся, всіх благочести́вих укріпле́ніє;","ра́дуйся, і́ноков огражде́ніє.","Ра́дуйся, ти́хоє приста́нище і́щущих спасе́нія;","ра́дуйся, ві́чний поко́й їм уготовля́ющая.","Ра́дуйся, блага́я Врата́рнице, две́рі ра́йськія ві́рним отверза́ющая."]},{"h":"Кондак 4","ps":["Бу́рю внутр іму́щи помишле́ній сумни́тельних, честна́я вдови́ця, я́же в Нике́ї, см'яте́ся, зря́щи копіє́м во́їна іконобо́рця прободе́ну святу́ю і чти́мую іко́ну Богома́тере і а́біє істочи́вшу кров і, стра́хом обдержи́ма, да не пору́гана бу́деть свята́я іко́на, с моли́твою слезоточа́щи вве́рже ю в мо́ре. Уви́дівши же ю пря́мо верху́ води́ путь творя́щу і теку́щу к за́паду, возопи́ с весе́лієм: Аллилу́я."]},{"h":"Ікос 4","ps":["Ви́діша і́ноці Святи́я Гори́ я́вльшійся в мо́рі я́ко пла́мень, я́ко столп о́гнен, єго́же верх досяза́ше небесі́, я́ко со́лнце сія́ющеє, і в нощі́ притеко́ша ко кра́ю мо́ря і, ви́дівше святу́ю іко́ну Богома́тере, по мо́рю носи́мую си́лою сви́ше, возопи́ша Благода́тній:","Ра́дуйся, Купино́, Законополо́жником предзри́мая;","ра́дуйся, сто́лпе о́гненний, наставля́яй су́щия во тьмі.","Ра́дуйся, лі́ствице, досяза́ющая до Небе́с, є́юже сни́де Бог;","ра́дуйся, мо́сте, преводя́й су́щих от землі́ на Не́бо.","Ра́дуйся, заре́ та́їнственнаго дне;","ра́дуйся, Звіздо́, явля́ющая Со́лнце.","Ра́дуйся, Світ Неізрече́нний роди́вшая;","ра́дуйся, є́же ка́ко ні єди́наго же научи́вшая.","Ра́дуйся, облече́нная в со́лнце, сія́ющая благода́тію і сла́вою всей вселе́нній;","ра́дуйся, мо́лніє, ду́ші просвіща́ющая і ві́рних сми́сли озаря́ющая.","Ра́дуйся, сві́тлосте, во тьмі світя́щая;","ра́дуйся, я́ко многосві́тлоє возсіява́єши просвіще́ніє.","Ра́дуйся, блага́я Врата́рнице, две́рі ра́йськія ві́рним отверза́ющая."]},{"h":"Кондак 5","ps":["Боготе́чную іко́ну Свою́ да́ти хотя́щи І́верстій оби́телі, рекла́ єси́, Богома́ти, преподо́бному Гавриї́лу: іди́ с ли́ком і́ноков к бре́гу мо́ря, сни́ди в пучи́ну і прийми́ іко́ну Мою́.” Он же, ві́рою і любо́вію окриля́єм, по воді́, а́ки по су́ху ходя́, прия́т ю во об'я́тія своя́ і, дости́г сокро́вища, іни́м недостижи́маго, в достоя́ніє і́ноков ро́да своєго́ і́верськаго, веселя́ся поя́ше: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́діша і́ноці і́верстії мно́гажди іко́ну Богома́тере із хра́ма во верху́ врат монасти́рських на сті́ну гра́да незри́мою си́лою ізнесе́нную, ужаса́хуся і стоя́ху, зову́ще к ней такова́я:","Ра́дуйся, святу́ю іко́ну да́ти нам ізво́лившая;","ра́дуйся, покро́в ю би́ти нам обіща́вшая.","Ра́дуйся, любо́в Твою́ к оби́телі на́шей показа́вшая;","ра́дуйся, благо́є о ней промишле́ніє яви́вшая.","Ра́дуйся, по́мощ на́ша в чужде́й страні́;","ра́дуйся, в стра́нствії на́шем утіше́ніє.","Ра́дуйся, Бо́жиє к нам благоволе́ніє;","ра́дуйся, на́ше к Бо́гу дерзнове́ніє.","Ра́дуйся, слез на́ших ізбавле́ніє;","ра́дуйся, си́рих нас Защи́тнице.","Ра́дуйся, огражде́ніє на́ше;","ра́дуйся, єди́на Ра́досте на́ша.","Ра́дуйся, блага́я Врата́рнице, две́рі ра́йськія ві́рним отверза́ющая."]},{"h":"Кондак 6","ps":["Пропові́дника творя́щи Гавриї́ла во́лі Своєя́, рекла́ єси́ к нему́, Влади́чице: «не прийдо́х храни́ма би́ти от вас, но да бу́ду Аз храни́тельниця ва́ша не то́кмо в настоя́щем, но і в бу́дущем ві́ці. Се даю́ вам зна́меніє: до́ндеже зрі́те в монастирі́ іко́ну Мою́, не оскуді́єть вам благода́ть Си́на Моєго́ і ми́лость, да вопію́ть Єму́ всі: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ ра́дость ве́лія сли́шавшим Твоя́, Богома́ти, обітова́нія, і Тебі́, Небе́сній Врата́рнице, храм на враті́х оби́телі с весе́лієм і́ноці воздвиго́ша і возопи́ша та́ко:","Ра́дуйся, храни́тельнице на́ша в настоя́щем ві́ці;","ра́дуйся, предста́тельнице на́ша в бу́дущем.","Ра́дуйся, стра́ху Бо́жию нас науча́ющая;","ра́дуйся, на путь доброді́телі наставля́ющая.","Ра́дуйся, дерзнове́ніє на́ше і наде́ждо;","ра́дуйся, упова́ніє на́ше і покро́в.","Ра́дуйся, благоутро́біє Си́на Своєго́ к нам преклони́вшая;","ра́дуйся, благода́ть Єго́ неоску́дно пребива́ти с на́ми возвіща́ющая.","Ра́дуйся святу́ю іко́ну зало́гом ми́лости да́вшая;","ра́дуйся, дар чудоді́йствія єй дарова́вшая.","Ра́дуйся, прило́г вся́каго зла от оби́телі отража́ющая;","ра́дуйся, всему́ благо́му вход отверза́ющая.","Ра́дуйся, блага́я Врата́рнице, две́рі ра́йськія ві́рним отверза́ющая."]},{"h":"Кондак 7","ps":["Хотя́щу іногда́ злочести́вому Ами́рі оби́тель І́верськую разори́ти і ста́до і́ноков, та́мо собра́нноє, разсі́яти, ско́ро позна́ крі́пкоє оби́телі заступле́ніє от Богома́тере, уви́дів корабли́ своя́ в пучи́ні мо́ря погря́зшия і ра́тники ізги́бшия. І прише́д со смире́нієм, сребро́ і зла́то в оби́тель дая́ше, моли́тви прося́. І́ноці же, ви́дівше сія́, возопи́ша к Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вия і безчи́сленния чудеса́ показа́ Богома́тер, в оби́телі оскуді́ніє вина́, муки́ і єле́я восполня́ющи, бі́сния ісціля́ющи, хроми́м хожде́ніє да́рующи, сліпи́м прозрі́ніє і всяк неду́г врачу́ющи, да, ви́дяще чудеса́ сія́, воспіва́ють Тебі́:","Ра́дуйся, Взбра́нная Воєво́до, враги́ побіжда́ющая;","ра́дуйся, ско́рая на по́мощ призива́ющим Тя.","Ра́дуйся, не презира́ющая моле́нія на́шего;","ра́дуйся, обіща́нія Своєго́ не отступа́ющая.","Ра́дуйся, скорб оби́телі в ра́дость претворя́ющая;","ра́дуйся, оскуді́ніє оби́телі восполня́ющая.","Ра́дуйся, сліпи́х прозрі́ніє;","ра́дуйся, хроми́х хожде́ніє.","Ра́дуйся, всіх немощни́х Ціли́тельнице;","ра́дуйся, всіх ско́рбних Уті́шительнице.","Ра́дуйся, я́ко не престає́ши промишля́ющи і спаса́ющи нас;","ра́дуйся, я́ко от толи́ких бід ізбавля́єши нас.","Ра́дуйся, блага́я Врата́рнице, две́рі ра́йськія ві́рним отверза́ющая."]},{"h":"Кондак 8","ps":["Стра́нно покрива́ємую от іко́ни Богома́тере оби́тель І́верськую сли́шав патріа́рх Ни́кон, вожделі́ і Украї́нській страні́ благода́ті Єя́ стяжа́ти прича́стіє, сего́ ра́ди, созда́в оби́тель в честь сла́внаго о́браза, со тща́нієм іспроси́ ізображе́ніє чудотво́рнаго о́браза Богома́тере, да, покро́вом Єя́ защища́ємі, вопію́ть Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Вся су́щи во ви́шніх, но і ни́жніх не отступа́ющи, благоізво́лила єси́, Богома́ти, я́коже дре́вле преподо́бному Анто́нію дарова́ся благослове́ніє гори́ Афо́нськия на утвержде́ніє оби́телі Пече́рськия, дарова́ти і но́вой оби́телі в страні́ Украї́нській благода́ть Свою́, є́юже благослови́ла єси́ Афо́н, в подо́бії честна́го о́браза Твоєго́. Ті́мже взива́єм Ті:","Ра́дуйся, страни́ Украї́нськия покро́ве, ши́рший о́блака;","ра́дуйся, правосла́вния ві́ри в ней огражде́ніє і утвержде́ніє.","Ра́дуйся, Правосла́вния Це́ркве непоколеби́мий сто́лпе;","ра́дуйся, єресе́й і раско́лов обличе́ніє.","Ра́дуйся, сві́тлими луча́ми чудотво́рних іко́н всю страну́ озаря́ющая;","ра́дуйся, дари́ ісціле́ній і ми́лостей от них істоча́ющая.","Ра́дуйся, ски́птра царе́й на́ших утвержде́ніє;","ра́дуйся, враго́в устраше́ніє.","Ра́дуйся, святи́телей весе́ліє;","ра́дуйся, ієре́єв похвало́.","Ра́дуйся, і́ноков Наста́внице;","ра́дуйся, всего́ ро́да на́шего спасе́ніє.","Ра́дуйся, блага́я Врата́рнице, две́рі ра́йськія ві́рним отверза́ющая."]},{"h":"Кондак 9","ps":["Вся́ко тща́ніє іму́ще о написа́нії честна́го о́браза ми́лостивия Врата́рници, сонм по́стников і́верських моле́бная пі́нія соверша́єть, водо́ю от чу́дния іко́ни омива́єть дську, на не́йже і́мать ізобрази́тися честни́й о́браз, і преподо́бнаго Іамвли́ха освяща́єть, і́же подвиза́вся в пості́, моли́тві і бді́нії со все́ю бра́тією, списа́ ва́пи, свято́ю водо́ю і моща́ми освяще́нними, честно́є ізображе́ніє Богома́тере, ви́ну моля́ся і вопія́ Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́я многовіща́нния, я́ко ри́би безгла́сния, ви́дим о Тебі́, Богоро́дице: недоумі́ють бо, ка́ко по досто́їнству похвали́ти вся чудеса́ Твоя́, явле́нная ро́ду на́шему от святи́я Твоєя́ іко́ни: єще́ бо на путі́ в Украї́нськую страну́ сія́ чудоді́йствоваше, благочести́вому Ману́їлу повеліва́я ви́куп да́ти неві́рним, возбраня́ющим ше́ствіє святи́я іко́ни в страну́ Ру́ськую, і сугу́бо єму́ по́сліжде отда́вши. Ми же, див'я́щеся, ві́рно вопіє́м Ті:","Ра́дуйся, істо́чниче чуде́с неісчерпа́ємий;","ра́дуйся, вся́кия ми́лости Пода́тельнице.","Ра́дуйся, всегда́ те́плая о нас Хода́тайце к Бо́гу;","ра́дуйся, промишле́нія Єго́ о нас сокро́вище.","Ра́дуйся, су́щим в біда́х прибі́жище;","ра́дуйся, скорб'я́щих утіше́ніє.","Ра́дуйся, больни́х ісціле́ніє;","ра́дуйся, немощни́х укріпле́ніє.","Ра́дуйся, вдов заступле́ніє;","ра́дуйся, сиро́тствующих милосе́рдая Ма́ти.","Ра́дуйся, заблужда́ющих на путь і́стини обраще́ніє;","ра́дуйся, грі́шников к покая́нію воззва́ніє.","Ра́дуйся, блага́я Врата́рнице, две́рі ра́йськія ві́рним отверза́ющая."]},{"h":"Кондак 10","ps":["Спасти́ хотя́щи мно́гия лю́ди от бід і скорбе́й, істоча́єши, Богома́ти, неоску́дний істо́чник ми́лости от Своєя́ іко́ни ро́ду на́шему: се бо і в сто́льном гра́де Москві́, блага́я Врата́рниця, явля́єшися всім покланя́ющимся Тебі́, ско́роє вспоможе́ніє подава́ющи, і в но́вой оби́телі І́верстій благода́ті струї́ от іко́ни Твоєя́ іспуща́єши, і во іни́х граді́х, оби́теліх і ве́сіх чту́щим Тя поле́зноє проше́ніє ісполня́ющи. Ті́мже, прославля́я Бо́га, да́вшаго нам благода́ть такову́ю, вопіє́м Єму́: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ і́ночеському чи́ну, Богоро́дице, і всім, к Тебі́ прибега́ющим, і́бо небесе́ і землі́ Творе́ць, все́лься в ді́вственній утро́бі Твоє́й, научи́ всіх чистоти́ і цілому́дрія ревни́телей возглаша́ти Тебі́:","Ра́дуйся, ді́вства сосу́де ізбра́нний;","ра́дуйся, чисті́йший о́бразе цілому́дрія.","Ра́дуйся, черто́же безсі́меннаго уневі́щенія;","ра́дуйся, Неві́сто Неневі́стная.","Ра́дуйся, Сі́ятеля чистоти́ ро́ждшая;","ра́дуйся, ві́рних Го́сподеві сочета́вшая.","Ра́дуйся, в бу́рі іскуше́ній ско́рая Помо́щнице;","ра́дуйся, прило́ги врага́ отража́ющая.","Ра́дуйся, мглу душевре́дних страсте́й отгоня́ющая;","ра́дуйся, по́мисли очища́ющая.","Ра́дуйся, земни́я сла́сти презира́ти науча́ющая;","ра́дуйся, ко го́рнему уми́ і сердця́ направля́ющая.","Ра́дуйся, блага́я Врата́рнице, две́рі ра́йськія ві́рним отверза́ющая."]},{"h":"Кондак 11","ps":["Пі́ніє вся́коє побіжда́ється, спростре́тися тща́щеєся ко мно́жеству мно́гих щедро́т Твої́х: равночи́сленния бо піска́ пі́сні а́ще прино́сим Ті, Влади́чице на́ша Богоро́дице, нічто́же соверша́єм досто́йно, я́же подава́єши нам, о Тебі́ вопію́щим: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоприє́мную свіщу́, су́щим во тьмі бід я́вльшуюся, зрим святу́ю іко́ну Богома́тере: невеще́ственний бо огнь благода́ті приє́млющи, луча́ми чуде́с всіх озаря́єть, науча́ющи си́це взива́ти Благослове́нній:","Ра́дуйся, во вся́ких ну́ждах ско́роє вспоможе́ніє;","ра́дуйся, в печа́ліх би́строє усли́шаніє.","Ра́дуйся, от огня́, меча́ і наше́ствія іноплеме́нних нас ізбавля́ющая;","ра́дуйся, от гла́да і напра́сния сме́рти нас свобожда́ющая.","Ра́дуйся, от я́зви і всегуби́тельства сме́ртнаго нас соблюда́ющая;","ра́дуйся, бе́дствующим в путі́, на су́ші і на вода́х внеза́пноє вспоможе́ніє.","Ра́дуйся, язв душе́вних і тіле́сних врачева́ніє;","ра́дуйся, оста́вленних врача́ми в Свої́ ру́ки приє́млющая.","Ра́дуйся, милосе́рдая Уті́шительнице всіх скорб'я́щих і обремене́нних;","ра́дуйся, не отверга́ющая всіх презрі́нних і отве́рженних.","Ра́дуйся, са́мих отча́янних із ро́ва поги́белі ісхища́ющая;","ра́дуйся, і мене́, обнаже́ннаго до́брих діл, не оставля́ющая Свої́м покро́вом і заступле́нієм.","Ра́дуйся, блага́я Врата́рнице, две́рі ра́йськія ві́рним отверза́ющая."]},{"h":"Кондак 12","ps":["Благода́ть да́ти восхоті́в, долго́в дре́вніх, всіх долго́в Ріши́тель челові́ком, при́йде Собо́ю ко отше́дшим Того́ благода́ті і, раздра́в рукописа́ніє, дарова́ нам крі́пкоє Богоблагода́тния хода́тайство, да вопіє́м всі моли́твами Єя́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Твоя́ чудеса́, явля́ємая нам в жи́зні сей, хва́лим Тя, Богоро́дице, я́ко ми́лости істо́чник неісчерпа́ємий. Но, припа́дающи к Тебі́ пред чудотво́рною іко́ною Твоє́ю, мо́лим Тя смире́нно, бу́ди нам покро́в і защище́ніє і в день кончи́ни на́шея, і єгда́ і́мами предста́ти на Суд стра́шному Престо́лу Си́на Твоєго́, да вопіє́м Ті:","Ра́дуйся, во сла́ві присідя́щая Престо́лу Си́на Твоєго́ і та́мо нас воспомина́ющая;","ра́дуйся, с Си́ном Твої́м і Бо́гом ві́чно ца́рствующая і о нас хода́тайствующая.","Ра́дуйся, упова́ющим на Тя коне́ць живота́ непости́ден да́рующая;","ра́дуйся, безболі́зненную і ми́рную кончи́ну устроя́ющая.","Ра́дуйся, мита́рств го́рких ізбавле́ніє;","ра́дуйся, от вла́сті кня́зя возду́шнаго освобожде́ніє.","Ра́дуйся, гріхо́в на́ших непоминове́ніє;","ра́дуйся, по Го́споді упова́ніє нам блаже́нния жи́зні.","Ра́дуйся, упова́ющим на Тя, одесну́ю Си́на Твоєго́ стоя́ніє устроя́ющая;","ра́дуйся, блаже́ннаго гла́са О́наго, Небе́снаго Ца́рствія наслі́діє обіща́ющаго, сли́шати сподобля́ющая.","Ра́дуйся, блага́я Ма́ти, всіх чту́щих Тя жи́ти с Собо́ю вселя́ющая;","ра́дуйся, крі́пкая наде́ждо ві́чнаго спасе́нія всім христия́ном.","Ра́дуйся, блага́я Врата́рнице, две́рі ра́йськія ві́рним отверза́ющая."]},{"h":"Кондак 13","ps":["О, Всепі́тая Ма́ти, Пресвята́я Госпоже́ Ді́во Богоро́дице! При́зри на нас, принося́щих смире́нно со слеза́ми ма́лия сія́ моли́тви пред пречи́стим Твої́м о́бразом і все упова́ніє і наде́жду возложи́вших на Тя, і ізба́ви нас всіх бід і напа́стей в животі́ сем і бу́дущия ізми́ му́ки, да спаса́ємії Тобо́ю, вопіє́м ви́ну: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел предста́тель по́слан бисть рещи́ Богоро́диці, єгда́ паде́ Єй жре́бій апо́стольськаго служе́нія в землі́ І́верстій: «”Не разлуча́йся Ієрусали́ма, жре́бій же, Тебі́ па́дший, просвіти́ться в послі́днія дні, Ти же і́маши потруди́тися в землі́, ю́же Тебі́ Бог ізво́лить.” Ті́мже зове́м Ті:","Ра́дуйся, Є́юже Єва́нгеліє благовісти́ться;","ра́дуйся, Є́юже і́дольськая пре́лесть упраздни́ться.","Ра́дуйся, Є́юже власть кня́зя тьми разруши́ться;","ра́дуйся, Є́юже Ца́рство Христо́во утверди́ться.","Ра́дуйся, па́дших во тьму ідолослуже́нія к сві́ту Єва́нгелія воззва́ніє;","ра́дуйся, от ра́бства дия́волу в свобо́ду сла́ви чад Бо́жиїх приведе́ніє.","Ра́дуйся, гото́вая служи́тельнице Си́на Своєго́ і Бо́га;","ра́дуйся, послуша́нієм преслуша́ніє Є́ви ісціля́ющая.","Ра́дуйся, висото́ доброді́телей;","ра́дуйся, глубино́ смиренному́дрія.","Ра́дуйся, Є́юже неві́рнії познаю́ть Творця́;","ра́дуйся, Є́юже ві́рнії усиновля́ються Отцю́.","Ра́дуйся, блага́я Врата́рнице, две́рі ра́йськія ві́рним отверза́ющая."]},{"h":"Кондак 1","ps":["Взбра́нной Воєво́ді, Влади́чиці на́шей Богоро́диці, похва́льная пі́нія прино́сим Ті раби́ Твої́, я́ко прише́ствієм честна́го о́браза Твоєго́ стяжа́вшії щит крі́пкий, сті́ну необори́мую і стра́жа неуси́пна. Ти же, я́ко іму́щая держа́ву непобіди́мую, покри́й і защити́ нас, Влади́чице, от всіх враго́во ви́димих і неви́димих і ізба́ви от вся́каго вре́да, душе́внаго і тіле́снаго, да зове́м Ті:","Ра́дуйся, блага́я Врата́рнице, две́рі ра́йськія ві́рним отверза́ющая."]},{"h":"Молитва до Пресвятої Богородиці","ps":["О Пресвята́я Ді́во, Ма́ти Го́спода, Цари́це Небесе́ і землі́! Воньми́ многоболі́зненному воздиха́нію душ на́ших, при́зри с висоти́ святи́я Твоєя́ на нас, с ві́рою і любо́вію покланя́ющихся пречи́стому о́бразу Твоєму́. Се бо, гріхми́ погружа́ємії і скорбми́ обурева́ємії, взира́ющи на Твой о́браз, я́ко живі́й Ті су́щей с на́ми, прино́сим смире́нная моле́нія на́ша. Не і́мами бо ні іни́я по́мощі, ні іна́го предста́тельства, ні утіше́нія, то́кмо Тебі́, о Ма́ти всіх скорб'я́щих і обремене́нних! Помози́ нам, немощни́м, утоли́ скорб на́шу, наста́ви на путь пра́вий нас, заблужда́ющих, уврачу́й і спаси́ безнаде́жних, да́руй нам про́чеє вре́м'я живота́ на́шего в ми́рі і тишині́ проводи́ти, пода́ждь христия́нськую кончи́ну і на Стра́шнім Суді́ Си́на Твоєго́ яви́ся нам милосе́рдая Засту́пниця, да всегда́ поє́м, велича́єм і сла́вим Тя, я́ко благу́ю Засту́пницю ро́да христия́нськаго, со всі́ми угоди́вшими Бо́гу. Амі́нь.","О Пресвята́я Ді́во, всеблага́го Си́на Ма́ти Всеблага́я, всім су́щим во грісі́х, ско́рбіх, біда́х і болі́зніх ві́рная Предста́тельнице і Засту́пнице. Не пре́зри моле́ній нас недосто́йних рабо́в Твої́х і умоли́ Си́на Твоєго́ і Бо́га на́шего, да всім нам, с ві́рою і умиле́нієм покланя́ющимся пред чудотво́рним о́бразом Твої́м, да́руєть по коєго́ждо потре́бі ра́дость: су́щим в ско́рбіх і печа́ліх - утіше́ніє, бе́дствующим - милосе́рдіє, су́щим во многонеду́жії - неча́ємоє ісціле́ніє і укріпле́ніє. О Госпожі́ Пресвята́я, умилосе́рдися ко всім чту́щим всечестно́є і́м'я Твоє́ і всім яви́ всемо́щний Твой покро́в і заступле́ніє. Вся́кому ді́лу Си́ну Твоєму́ уго́дному споспі́шествуй, вся́коє ді́ло зло́є - разруши́. В недоумі́нії, тру́дних і опа́сних обстоя́ніях обріта́ющимся - ниспосли́ с небесе́ незри́мую по́мощ і вразумле́ніє і от враго́во ви́димих і неви́димих защити́ і сохрани́. Супру́жества в любві́ і єдиноми́слії соблюди́, ста́рці поддержи́, младе́нці воспита́й, ю́ния уцілому́дри і отве́рзи їм ум к восприя́тію поле́зних уче́ній, єдинокро́вния от дома́шнія бра́ні і вражди́ ми́ром і любо́вію огради́ і всім нам пода́ждь друг ко дру́гу любо́в, мир, благоче́стіє, здра́віє і долгоде́нствіє. Преста́вльшимся от житія́ сего́ во ві́рі і покая́нії со а́нгели і всі́ми святи́ми жи́ти сотвори́, да всі на Небесі́ і на землі́ ві́дять Тя я́ко тве́рдую і непости́дную Предста́тельницю ро́да христия́нськаго і ві́дяще сла́в'ять Тя і Тобо́ю Си́на Твоєго́ со безнача́льним Єго́ Отце́м, і Пресвяти́м, Благи́м і Животворя́щим Єго́ Ду́хом, ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва до Пресвятої Богородиці перед Її іконою Іверською","ps":["О Пресвята́я Богоро́дице, Пречи́стая Ма́ти Ді́во! К Тебі́ прибіга́ю, к Твої́м ма́тернім об'я́тіям припа́даю, заступле́нія і по́мощі Твоєя́ прошу́. Се бо іспо́лнихся ско́рби; бі́ди обурева́ють м'я; іскуше́нія і гріси́ одержа́ть бі́дную ду́шу мою́; весь недоумі́нієм іспо́лнен єсьм; слеза́ми омоча́ю лице́ своє́. І гді обря́щу спасе́ніє? Ко кому́ притеку́, недосто́йний? А́ще во́ззрю на Си́на Твоєго́, стра́хом погружа́юся, я́ко Спаси́тель єсть ми́лостивий, оба́че же і Судія́ Пра́ведний; аз же всегда́ попира́ю заві́ти Єго́, і я́ко ми́тар не смі́ю возвісти́ на Пречи́стий Лик грі́шних оче́с мої́х. А́ще ко святи́м обращу́ся, і па́ки ті́сно мі єсть; тії́ бо бі́ша небе́снії житіє́м, аз же весь земле́н єсьм; сего́ ра́ди стижу́ся моли́ти їх, я́ко дале́че от них отстоя́й дія́ньми мої́ми. Но а́ще і Ти Святи́х Святі́йша єси́, і Херуви́м честні́йша; оба́че к Тебі́ прибіга́ю с наде́ждою. Не вім, отку́ду сицево́ дерзнове́ніє і́мам; ві́рую, я́ко Ма́ти всіх Су́щи, Сама́ да́руєши такову́ю благода́ть ча́дом Твої́м. Сего́ ра́ди уми́льно, я́ко І́стинную і Благу́ю Ма́тер свою́, прошу́ і молю́: не отри́ни мене́ непотре́бнаго і ско́рбнаго; усли́ши та́йная воздиха́нія душі́ моєя́ опеча́ленния; во́ззри ми́лостивим о́ком на раба́ Твоєго́ огорче́ннаго; простри́ ма́тернія ру́ки Твої́ к бі́дній главі́ моє́й, іно́го прибі́жища не імі́ющей. І помози́ мні, я́ко Сама́ ві́си і во́лиши. Уті́ши се́рдце моє́, печа́льми боле́знующеє; просвіти́ ум мой, суєто́ю омраче́нний; укріпи́ во́лю, гріхми́ разсла́бленную; іспроси́ благода́ть Свята́го Ду́ха Уті́шителя; і даждь вся, я́же к жи́зні і спасе́нію потре́бная; найпа́че же введи́ м'я во вре́м'я своє́ в оби́телі Си́на Твоєго́ і Бо́га моєго́. Ві́рую бо і вім несумні́нно, я́ко всяк, призива́яй Тя от се́рдця, ніка́коже поги́бнеть, но поми́лованія от Го́спода сподо́биться; Твої́ бо є́сьми ча́да, і на хода́тайство Твоє́ непрело́жноє упова́ніє і́мами, я́ко Ма́тер єси́ Спа́са на́шего Христа́ Бо́га, Єму́ же сла́ва со Отце́м і Святи́м Ду́хом во ві́ки. Амі́нь."]},{"h":"Тропар, глас 1","ps":["От святи́я іко́ни Твоєя́, / о Влади́чице Богоро́дице, / ісціле́нія і цільби́ подаю́ться оби́льно, / с ві́рою і любо́вію приходя́щим к ней. / Та́ко і мою́ не́мощ посіти́, / і ду́шу мою́ поми́луй, Блага́я, // і ті́ло ісціли́ благода́тію Твоє́ю, Пречи́стая."]},{"h":"Інший тропар, глас 1","ps":["Де́рзость ненави́дящих о́браз Госпо́день, / і держа́ва нечести́вих безбо́жно в Ніке́ю при́йде, / і по́сланнії безчелові́чно вдови́цю, / благоче́стно чту́щую іко́ну Богома́тере, істязу́ють, / но та́я но́щію с си́ном іко́ну в мо́ре пусти́, вопію́щи: / сла́ва Тебі́, Чи́стая, / я́ко непроходи́моє мо́ре плещи́ своя́ подаде́, // сла́ва правоше́ствію Твоєму́, Єди́на Нетлі́нная."]},{"h":"Кондак, глас 8","ps":["А́ще і в мо́ре вве́ржена бисть свята́я іко́на Твоя́, Богоро́дице, / от вдови́ці, не могу́щия спасти́ сію́ от враго́в, / но яви́лася єсть Храни́тельниця Афо́на / і Врата́рниця оби́телі І́верськия, враги́ устраша́ющая / і в Правосла́вній Украї́нській страні́ // чту́щия Тя от всіх бід і напа́стей ізбавля́ющая."]},{"h":"Інший кондак, глас 4","ps":["Совозсія́ днесь Сві́ту Воскресе́нія світ чи́стия іко́ни Твоєя́, / обоя́ ве́село торжеству́юще вопіє́м: // сохрани́ раб Твої́х благода́тію, Влади́чице."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, і чтим о́браз Твой святи́й, і́мже болі́зні на́ша врачу́єши і душі́ на́ша к Бо́гу возво́диши."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Державна»","e":"Akathist to the Theotokos before her icon “Derzhavnaya”","secs":[{"h":"Кондак 1","ps":["Ізбра́нній от всіх родо́в Засту́пнице ро́да христия́нськаго, покро́вом Своєя́ бла́гости покрива́ющей страну́ на́шу правосла́вную, благода́рственная пі́нія прино́сим Ті, Влади́чице, о явле́нії нам чу́дния іко́ни Твоєя́ Держа́вния. Ти же, я́ко Всеми́лостивая Засту́пниця всіх с ві́рою к Тебі́ притека́ющих, от вся́ких нас бід свободи́, да зове́м Ті:","Ра́дуйся, Ма́ти Бо́жия Держа́вная, Засту́пнице усе́рдная ро́да христия́нськаго."]},{"h":"Ікос 1","ps":["А́нгелом ра́дость приі́мшая, благоволи́ла єси́, Влади́чице, возвісти́ти ста́рице благочести́вій ра́дость о явле́нії іко́ни Твоєя́ честни́я Держа́вния, ю́же і обрі́тше по указа́нію Твоєму́, я́ко зна́меніє ми́лости Бо́жієй к нам, грі́шним, благода́рственно вопіє́м Ті си́це:","Ра́дуйся, во́лі Госпо́дней та́йни нам открива́ющая;","ра́дуйся, гнів Єго́ пра́ведний, на ни дви́жимий, ум'ягча́ющая.","Ра́дуйся, нечести́вих злові́рія обличе́ніє;","ра́дуйся, горди́ні їх низложе́ніє.","Ра́дуйся, ві́ри христия́нськия утвержде́ніє;","ра́дуйся, почита́нія святи́х іко́н освяще́ніє.","Ра́дуйся, ти́хоє приста́нище спасе́нія душ на́ших;","ра́дуйся, Всеми́лостивая Засту́пнице на́ша у престо́ла Святи́я Тро́йці.","Ра́дуйся, от бід і скорбе́й на́ше ізбавле́ніє;","ра́дуйся, Це́ркве Правосла́вния утвержде́ніє.","Ра́дуйся, звіздо́ невече́рняго сві́та, нас озаря́ющая;","ра́дуйся, Ма́ти Сві́та, всіх просвіща́ющая.","Ра́дуйся, Ма́ти Бо́жия Держа́вная, Засту́пнице усе́рдная ро́да христия́нськаго."]},{"h":"Кондак 2","ps":["Ви́дящи, Всенепоро́чная, с висоти́ небе́снаго жили́ща Своєго́, іді́же с Си́ном Твої́м во сла́ві пребива́єши, скорб ві́рних рабо́в Твої́х, я́ко гні́внаго ра́ди Бо́жия посіще́нія ві́ра Христо́ва поруга́єма бива́єть нечести́вим злові́рієм, благоволи́ла єси́ яви́ти нам іко́ну Твою́ Держа́вную, да всі христолюби́вії лю́діє усе́рдно мо́ляться пред не́ю, ві́рно вопію́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зуму на́шему просвіще́ніє сви́ше ісхода́тайствуй, Пресвята́я Богоро́дице, да позна́єм, что єсть во́ля Бо́жия блага́я, уго́дная і соверше́нная, і се́рдце напра́ви, є́же со усе́рдієм твори́ти ю, Тебі́ же, Всеми́лостивая Засту́пнице, непреста́нними гла́си восхваля́ти:","Ра́дуйся, явле́нієм честни́я іко́ни Твоєя́ тьму лю́тих обстоя́ній от нас отгоня́ющая;","ра́дуйся, луча́ми чуде́с всіх просвіща́ющая.","Ра́дуйся, душе́вними і тіле́сними очеси́ осле́пших прозрі́ніє;","ра́дуйся, омраче́нних сми́слов просвіще́ніє.","Ра́дуйся, всіх упова́ющих на Тя непости́дная наде́ждо;","ра́дуйся, вдов і сиро́т наде́жний покро́ве.","Ра́дуйся, а́лчущих пита́тельнице;","ра́дуйся, духо́вних сокро́вищ пода́тельнице.","Ра́дуйся, богому́дрих прему́драя добро́то;","ра́дуйся, пресві́тлая, Боже́ственная красото́.","Ра́дуйся, цві́те нетлі́нія;","ра́дуйся, обоня́ніє Христо́ва благоуха́нія.","Ра́дуйся, Ма́ти Бо́жия Держа́вная, Засту́пнице усе́рдная ро́да христия́нськаго."]},{"h":"Кондак 3","ps":["Си́лу Боже́ственния благода́ті да́руй нам, Пресвята́я Богоро́дице, во є́же неукло́нно і непреткнове́нно ходи́ти нам спаси́тельним путе́м Христо́вих за́повідей, се́рдцем же і усти́ непреста́нно воспіва́ти Всемогу́щему Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще Тя, Богоізбра́нная Засту́пнице ро́да христия́нськаго, я́ко зарю́ сві́тлую, просвіща́ющую душ на́ших темноту́ і разгоня́ющую мрак серде́чнаго неві́дінія на́шего, припа́даєм к честні́й іко́ні Твоє́й Держа́вній і с умиле́нієм вопіє́м Ті си́це:","Ра́дуйся, сохраня́ти і спаса́ти всіх призива́ющих Тя обіща́вшая;","ра́дуйся, прославля́ющих Тя прославля́ющая.","Ра́дуйся, к Си́ну Твоєму́ і Бо́гу на́шему моли́тви ві́рних принося́щая;","ра́дуйся, благода́ть Твою́ іко́нам Твої́м честни́м дарова́вшая.","Ра́дуйся, всю вселе́нную луча́ми Твоєя́ благода́ті озари́вшая;","ра́дуйся, прему́дрости Бо́жия прия́телище.","Ра́дуйся, Боже́ственния благода́ті Пода́тельнице;","ра́дуйся, я́ко Тобо́ю от ві́чния сме́рти свобожда́ємся.","Ра́дуйся, я́ко Тобо́ю безконе́чния жи́зні сподобля́ємся;","ра́дуйся, честні́йшая херуви́м і сла́внійшая серафи́м.","Ра́дуйся, Ма́ти Сві́та і Цари́це Небе́сная;","ра́дуйся, Влади́чице, Всеми́лостивая за нас пред Бо́гом Засту́пнице.","Ра́дуйся, Ма́ти Бо́жия Держа́вная, Засту́пнице усе́рдная ро́да христия́нськаго."]},{"h":"Кондак 4","ps":["Бу́ря жите́йськаго мо́ря сокруша́єть духо́вний кора́бль наш волна́ми жите́йських попече́ній, і мир убо́гих душ на́ших м'яте́ться. І гді обря́щем ти́хоє приста́нище спасе́нія? То́кмо на Тя возлага́єм наде́жду, Влади́чице; іму́щи бо держа́ву непобіди́мую, от вся́ких бід, гла́да, скорбе́й і болі́зней ізба́ви нас, ві́рно вопію́щих Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше правосла́внії лю́діє повелі́ніє Твоє́, Влади́чице, моли́тися пред о́бразом Твої́м Держа́вним, со умиле́нієм серде́чним прибіга́ють к Твоєму́ всеси́льному заступле́нію у престо́ла Всемогу́щаго Бо́га і благогові́йно вопію́ть Ті си́це:","Ра́дуйся, го́рняго ми́ра украше́ніє;","ра́дуйся, до́льняго ми́ра заступле́ніє.","Ра́дуйся, Дщи благослове́нная Отця́ Небе́снаго;","ра́дуйся, Роди́тельнице неіскусому́жная Си́на Предві́чнаго.","Ра́дуйся, де́монськия полки́ побіжда́ющая;","ра́дуйся, враги́ спасе́нія челові́чеськаго посрамля́ющая.","Ра́дуйся, я́ко во́лею Твоє́ю сокруша́ються єрети́чеськия глави́;","ра́дуйся, я́ко ві́рнії Тобо́ю сподобля́ються сла́ви.","Ра́дуйся, тіле́с на́ших безме́здная Ціли́тельнице;","ра́дуйся, душ на́ших к Ца́рствію го́рнему Путеводи́тельнице.","Ра́дуйся, я́ко сотвори́ Тебі́ вели́чіє Си́льний;","ра́дуйся, я́ко призрі́ на смире́ніє Твоє́ Госпо́дь.","Ра́дуйся, Ма́ти Бо́жия Держа́вная, Засту́пнице усе́рдная ро́да христия́нськаго."]},{"h":"Кондак 5","ps":["Богото́чная звізда́ яви́ся нам, Влади́чице, честна́я Твоя́ іко́на Держа́вная, страну́ Украї́нськую всю обтека́ющая і луча́ми чуде́с Твої́х осіява́ющая всіх блужда́ющих по мо́рю стра́стнаго житія́, мрак печа́лей і мглу вся́чеських неду́г і скорбе́й прогоня́ющая і наставля́ющая на путь спасе́нія с ві́рою к Тебі́ притека́ющих і вопію́щих Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Во дні лю́тих скорбе́й і злих обстоя́ній яви́ла єси́ нам, Влади́чице, ве́лію ми́лость обрі́тенієм честни́я іко́ни Твоєя́ Держа́вния, да всі с ві́рою моля́щіїся пред не́ю при́ймуть здра́віє і душ спасе́ніє. Сего́ ра́ди і ми, прославля́юще Твоє́ милосе́рдіє неізрече́нноє, усе́рдно вопіє́м Ті си́це:","Ра́дуйся, світи́ло незаходи́моє, сві́том і́стиннаго богопозна́нія нас просвіща́ющеє;","ра́дуйся, Врата́рнице, две́рі ра́йськія ві́рним отверза́ющая.","Ра́дуйся, многотеку́щая ріко́ Боже́ственния благода́ті;","ра́дуйся, неістощи́мий істо́чниче святи́ні.","Ра́дуйся, ко благоче́стію на́ша наста́внице;","ра́дуйся, душ на́ших освяще́ніє.","Ра́дуйся, ка́ющихся грі́шников с Бо́гом примире́ніє;","ра́дуйся, до́брия обі́ти приє́млющая.","Ра́дуйся, благи́м намі́ренієм спосо́бствующая;","ра́дуйся, зли́я начина́нія разруша́ющая.","Ра́дуйся, вра́жия ко́зні расторга́ющая;","ра́дуйся, ско́рая челові́ком помо́щнице.","Ра́дуйся, Ма́ти Бо́жия Держа́вная, Засту́пнице усе́рдная ро́да христия́нськаго."]},{"h":"Кондак 6","ps":["Воспіва́єм Твоє́ милосе́рдіє досточу́дноє і мно́гоє к нам снисхожде́ніє, Пресвята́я Богоро́дице, не престає́ши бо моли́тися о нас, грі́шних, Си́ну Твоєму́ і Бо́гу на́шему, є́же отврати́ти гнів Єго́ пра́ведний, на ни дви́жимий, і поми́ловати всіх, ві́рно вопію́щих Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсіява́єть в душа́х на́ших, омраче́нних ско́рбію і уни́нієм от мно́жества согріше́ній, світ благода́тнаго утіше́нія, і се́рдце на́ше ісполня́ється весе́лія і ра́дости, єгда́ непреста́нними Твої́ми, Влади́чице, вразумле́ньми возбужда́єши нас вопи́ти к ще́дрому Бо́гу, да ми́лостив бу́деть і прости́ть нам прегріше́нія на́ша. Не премолчи́ у́бо, Влади́чице, наставля́ющи і вразумля́ющи нас, зову́щих Ті си́це:","Ра́дуйся, в ско́рбіх і болі́зніх долготерпі́нію нас науча́ющая;","ра́дуйся, вся помишле́нія на́ша к расп'я́тому за гріхи́ ми́ра Спаси́телю устремля́ющая.","Ра́дуйся, страда́нія Єго́ і кре́стную смерть в па́м'яті на́шей обновля́ющая;","ра́дуйся, правосу́дієм Бо́жиїм к ожесточе́нним і нераска́янним нас устраша́ющая.","Ра́дуйся, ожида́нієм бу́дущих небе́сних благ нас услажда́ющая;","ра́дуйся, к насле́дству нетлі́нному і ві́чному нас приводя́щая.","Ра́дуйся, наслі́дниками Ца́рствія Бо́жия нас сотворя́ющая;","ра́дуйся, трапе́зо свята́я, хлі́бом жи́зні нас пита́ющая.","Ра́дуйся, ма́слино благопло́дная, єле́єм ми́лости сердца́ ум'ягча́ющая;","ра́дуйся, я́ко моли́твою пред іко́ною Твоє́ю приє́млем духо́вноє утіше́ніє.","Ра́дуйся, я́ко сердця́м на́шим да́руєши благода́тноє сокруше́ніє;","ра́дуйся, я́ко благости́нею Своє́ю угаша́єши в нас огнь нече́стія.","Ра́дуйся, Ма́ти Бо́жия Держа́вная, Засту́пнице усе́рдная ро́да христия́нськаго."]},{"h":"Кондак 7","ps":["Хотя́й всім челові́ком спасти́ся і в ра́зум позна́нія і́стини прийти́, премилосе́рдий Госпо́дь і Созда́тель наш посла́ во дні гні́внаго посіще́нія Своєго́ а́нгела пресві́тла в новоявле́ннем о́бразі Твоє́м Держа́внем, да всі с ві́рою моля́щіїся пред ним, при́ймуть по́мощ і заступле́ніє Твоє́ всеси́льноє і ра́достно вопію́ть Всемогу́щему Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вую показа́ ми́лость всіх Творе́ць і Влади́ка наш Госпо́дь, єгда́ положи́ во гні́ві Своє́м наказа́ти род челові́чеський огне́м, мече́м, гла́дом і болі́зньми; сотвори́ сіє́ наказа́ніє мно́гим челові́ком ко вразумле́нію і ісправле́нію во спасе́ніє душ. Сего́ ра́ди і ми, Влади́чице, припа́дающе к Пречи́стому о́бразу Твоєму́ Держа́вному, усе́рдно мо́лим Тя: не даждь нам поги́бнути до конця́, но милосе́рдія две́рі отве́рзи нам, вопію́щим Ті си́це:","Ра́дуйся, непристу́пнаго Божества́ селе́ніє;","ра́дуйся, а́нгельськоє непрестаю́щеє удивле́ніє.","Ра́дуйся, рабо́в Бо́жиїх та́йноє вразумле́ніє;","ра́дуйся, Засту́пнице всіх су́щих в ско́рбіх і болі́зніх.","Ра́дуйся, благода́тноє безстра́стіє і́щущим єго́ подаю́щая;","ра́дуйся, всіх в чистоті́ цілому́дрія живу́щих зіло́ лю́б'ящая.","Ра́дуйся, приста́нище небу́рноє подви́жников благоче́стія;","ра́дуйся, гні́вом Бо́жиїм вразумля́ющая сино́в нече́стія.","Ра́дуйся, безмо́лвствующих сла́дкая собесі́днице;","ра́дуйся, отше́льников Христа́ ра́ди крі́пкоє упова́ніє.","Ра́дуйся, по́стников боже́ственноє ра́дованіє;","ра́дуйся, пустинножи́телей ти́хоє весе́ліє.","Ра́дуйся, Ма́ти Бо́жия Держа́вная, Засту́пнице усе́рдная ро́да христия́нськаго."]},{"h":"Кондак 8","ps":["Стра́нни і прише́льці єсьми́ на землі́: житіє́ бо на́ше су́єтно і маловре́менно єсть. Ми же сме́рті безві́стноє во ум нікогда́же приє́млем, ні помишля́єм о Стра́шнім суди́щі Христо́ві, в не́мже і́мами пра́ведному Судії́ предста́ти і да́ти отві́т о вся́ком же ді́лі і словесі́. Ті́мже мо́лим Тя, Влади́чице: возбуди́ нас ско́ро от сна гріхо́внаго, да не пости́гнеть нас час сме́рти неіспра́вленних і да сподо́бимся Твої́м хода́тайством получи́ти беззако́нієм на́шим проще́ніє і во гла́сі ра́дованія воспіва́ти Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Вся би́вши горі́, к небе́сним взята́ єси́ і земни́х не оставля́єши, Пресвята́я Богоро́дице, свяще́нним Твої́м предста́тельством: і́маши бо дерзнове́ніє к Си́ну Твоєму́ і Бо́гу на́шему. Ті́мже утверди́, Влади́чице, в ми́рі глубо́ці страну́ на́шу правосла́вную і вся поле́зная да́руй рабо́м Твої́м, да велича́юще воспіва́єм Ті та́ко:","Ра́дуйся, у́мним очесе́м на́шим го́ркий і стра́шний час сме́ртний представля́ющая;","ра́дуйся, на ки́йждо день, а́ки уже́ на послі́дній житія́ на́шего, взира́ти нас поуча́ющая.","Ра́дуйся, люби́ти мир і я́же в ми́рі нам воспреща́ющая;","ра́дуйся, пристра́стіє к тлі́нному бога́тству із се́рдця на́шего іскореня́ющая.","Ра́дуйся, вся бла́га земна́я би́ти привре́менна і скоропреходя́ща нам показу́ющая;","ра́дуйся, сла́ви челові́чі, а́ки ті́ни преходя́щия, іска́ти нам возбраня́ющая.","Ра́дуйся, я́ко сладча́йшеє і́м'я Го́спода Ісу́са Христа́ усти́ непреста́нно проізноси́ти і во умі́ держа́ти нас побужда́єши;","ра́дуйся, я́ко от праздносло́вія, многоглаго́ланія, па́че же от кощу́нства нас удержава́єши.","Ра́дуйся, я́ко воздержа́нію в пи́щі і питії́ приобучи́ти нас пече́шися;","ра́дуйся, я́ко Твоє́ за нас хода́тайство си́льно єсть пред Бо́гом, є́же не вве́рженним нам би́ти во тьму кромі́шнюю.","Ра́дуйся, я́ко при́сно внуша́єши нам омива́ти гріхи́ своя́ слеза́ми покая́нія, да ізба́вимся геє́нни а́дськия;","ра́дуйся, я́ко побужда́єши нас день і нощ моли́тися, да не по́слани бу́дем со де́мони му́читися.","Ра́дуйся, Ма́ти Бо́жия Держа́вная, Засту́пнице усе́рдная ро́да христия́нськаго."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ а́нгельськоє удиви́ся ді́лу Твоєго́ милосе́рдія, Го́споди, я́ко дарова́л єси́ нам толи́ко тве́рдую і те́плую Засту́пницю ро́ду христия́нському во дні гні́внаго Твоєго́ посіще́нія, нам неви́димо сопребива́ющу, сли́шащу же Тебе́ пою́щих: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії многовіща́ннії, непросвіще́ннії сві́том і́стиннаго богопозна́нія, поклони́шася злато́му тельцю́. По сло́ву же апо́стола, всяк любостяжа́тель ідолослужи́тель єсть. Сего́ ра́ди Бо́жиє гні́вноє посіще́ніє всему́ ми́ру зря́ще, і ми, грі́шнії, смире́нно мо́лим Тя, Влади́чице: уми́лостиви Созда́теля, да потщи́ться гнів Свой пра́ведний преложи́ти на ми́лость і поми́ловати нас, вопію́щих Ті си́це:","Ра́дуйся, я́ко Твоєя́ по́мощі і заступле́нія нікогда́же нас лиша́єши;","ра́дуйся, я́ко ум наш, омраче́нний небреже́нієм, сві́тлим Твої́м покро́вом озаря́єши.","Ра́дуйся, я́ко Тобо́ю от страсте́й тіле́сних ізбавля́ємся;","ра́дуйся, я́ко Тобо́ю сла́достей духо́вних ісполня́ємся.","Ра́дуйся, колесни́це Со́лнця у́мнаго, ра́дуйся, тве́рдоє Правосла́вія укріпле́ніє;","ра́дуйся, честно́є Спа́са на́шего носи́ло і похвале́ніє.","Ра́дуйся, і во вре́менній жи́зні поле́зная нам подаю́щая;","ра́дуйся, душе́вния ра́ни на́ша єле́єм спаси́тельним умаща́ющая.","Ра́дуйся, я́ко із ро́ва беззако́ній на́ших руко́ю Твоєя́ по́мощі нас ісхища́єши;","ра́дуйся, я́ко гріхо́вний сон душевре́дния на́шея лі́ності отряса́єши.","Ра́дуйся, душе́вноє умиле́ніє і серде́чноє сокруше́ніє в нас ражда́ющая;","ра́дуйся, я́ко твори́ши всім спасти́ся, в держа́вний покро́в Твой прибега́ющим.","Ра́дуйся, Ма́ти Бо́жия Держа́вная, Засту́пнице усе́рдная ро́да христия́нськаго."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ мно́гия лю́ди от обдержа́щих їх скорбе́й і болі́зней і ві́ру їх утверди́ти во всеси́льноє заступле́ніє Твоє́, Влади́чице, дарова́ла єси́ нам ізображе́ніє честни́я іко́ни Твоєя́ Держа́вния, да всі, ви́дяще явля́ємую Тобо́ю ми́лость, вопію́ть со умиле́нієм Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ яви́лася єси́, Богоро́дице Ді́во, Украї́нській страні́ честни́ми Твої́ми іко́нами, ізлива́ющи чудеса́ во бранеіх і осіня́я благода́тною по́мощію Твоє́ю христолюби́вих во́їнов. Под держа́вним бо покро́вом Твоєя́ бла́гости Украї́нськая страна́ созида́шеся, і врата́ а́дова не одолі́ша Правосла́вния Це́ркве Христо́ви. Сего́ ра́ди припа́дающе к честні́й іко́ні Твоє́й Держа́вній, ра́достно вопіє́м Ті си́це:","Ра́дуйся, Украї́нськия страни́ покро́ве і утвержде́ніє;","ра́дуйся, от наше́ствія іноплеме́нних ізбавле́ніє.","Ра́дуйся, су́щих в пліне́нії освобожде́ніє;","ра́дуйся, от гла́да і болі́зней на́ше спасе́ніє.","Ра́дуйся, са́де землі́ обітова́нія;","ра́дуйся, цві́те боже́ственнаго сажде́нія.","Ра́дуйся, лозо́ доброді́тельная виногра́да Христо́ва;","ра́дуйся, дре́во чудото́чноє рая́ Ісу́сова.","Ра́дуйся, жили́ще і дом Христа́ Бо́га на́шего;","ра́дуйся, вмісти́лище неізрече́нния Єго́ сла́ви.","Ра́дуйся, Влади́чице, Всеми́лостивая Пода́тельнице щедро́т;","ра́дуйся, я́ко мно́го мо́жеть моли́тва Твоя́ пред Си́ном Твої́м і Бо́гом на́шим.","Ра́дуйся, Ма́ти Бо́жия Держа́вная, Засту́пнице усе́рдная ро́да христия́нськаго."]},{"h":"Кондак 11","ps":["Пі́ніє хвале́бноє і благода́рственноє прино́сим Ті, Влади́чице, под держа́вним бо покро́вом Твоєя́ бла́гости пребива́єм в непости́дній наде́жде всеси́льнаго заступле́нія Твоєго́ за нас, грі́шних, і все упова́ніє на́ше на Тя возложи́вше, ра́достно вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світи́льници на́ші угасо́ша, єле́я же благи́х діл не і́мами, во є́же возжещи́ благода́ть Ду́ха Свята́го. І гді обря́щемся, окая́ннії, сном гріхо́вним отягче́ннії, єгда́ пости́гнеть нас внеза́пу в полу́нощі час кончи́ни на́шея? Но да не усли́шим і ми, я́коже юро́дивия ді́ви, гро́знаго гла́са Жениха́: не вім вас! Помози́ нам, Влади́чице, напо́лнити сосу́ди душ на́ших єле́єм благи́х діл, па́че же милосе́рдія і смире́нія, да благода́рственно воспоє́м Ті си́це:","Ра́дуйся, я́ко воспомина́нієм гряду́щаго гро́знаго суда́ Бо́жия от гріхо́в нас отріва́єши;","ра́дуйся, я́ко ду́ші на́ша, а́ки неві́сту, ко срі́тенію прекра́снаго Жениха́ Христа́ предуготовля́ти нас поуча́єши.","Ра́дуйся, я́ко возбужда́єши нас на всяк день же і час приноси́ти Христу́ Бо́гу моли́тви, проше́нія і благодаре́нія;","ра́дуйся, я́ко с му́дрими ді́вами — душа́ми пра́ведних, вни́ти в бра́чний черто́г Си́на Твоєго́ і Бо́га на́шего помога́єши.","Ра́дуйся, я́ко в ри́зу непоро́чности і чистоти́ облещи́ся нам спосо́бствуєши;","ра́дуйся, я́ко ста́ти нам на Стра́шнім суді́ Христо́ві одесну́ю Єго́ хода́тайствуєши.","Ра́дуйся, я́ко благоутро́біє Бо́жиє о прича́стії нас к ли́ку ізбра́нних умоля́єши;","ра́дуйся, я́ко ум наш, омраче́нний небреже́нієм, сві́том Свої́м озаря́єши.","Ра́дуйся, я́ко голуби́ну простоту́ і а́гнчу кро́тость стяжа́ти нам приі́скренні жела́єши;","ра́дуйся, я́ко самоотверже́нію і отрече́нію от зли́я на́шея во́лі приобучи́ти нас тщи́шися.","Ра́дуйся, я́ко младе́нчеськоє незло́біє дарова́ти нам спосо́бствуєши;","ра́дуйся, я́ко хла́дноє се́рдце на́ше моли́твами воспламеня́ти нам помога́єши.","Ра́дуйся, Ма́ти Бо́жия Держа́вная, Засту́пнице усе́рдная ро́да христия́нськаго."]},{"h":"Кондак 12","ps":["Благода́ть прия́ла єси́, Влади́чице, от Всемогу́щаго Го́спода Бо́га ми́ловати благочести́вия ча́да Це́ркве Христо́ви і вразумля́ти нечести́вих сино́в єя́. Сего́ ра́ди, притека́юще под держа́вний покро́в Твоєя́ бла́гости, усе́рдно мо́лим Тя, Влади́чице: ізба́ви нас от ухищре́ній духо́в зло́би, разслабля́ющих на́ші ду́шу і ті́ло лі́ностію і нераді́нієм, і возбуди́ нас от сна гріхо́внаго, да благода́рственно вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Твоя́ чудеса́, би́вшая в дре́вняя і настоя́щая времена́, хва́лим Тя, Влади́чице, я́ко живоно́сний істо́чник благода́ті і неістощи́мую чуде́с реку́, бе́здну бо ми́лості і щедро́т дарова́ла єси́ ро́ду христия́нському явле́нієм честни́х іко́н Твої́х. Сего́ ра́ди і ми, припа́дающе к честні́й іко́ні Твоє́й Держа́вній, со умиле́нієм вопіє́м Ті си́це:","Ра́дуйся, Це́ркве Небе́сния і земни́я украше́ніє;","ра́дуйся, ді́вства честни́й покро́ве і огражде́ніє.","Ра́дуйся, честна́я похвало́ ієре́єв благогові́йних;","ра́дуйся, сві́тлоє проро́чеськоє сбитіє́.","Ра́дуйся, всехва́льних апо́столов восхвале́ніє;","ра́дуйся, мо́лніє, неві́рних устраша́ющая.","Ра́дуйся, сла́вою чуде́с Твої́х ві́рних ми́слі озаря́ющая;","ра́дуйся, печа́ль і скорб на́шу в ра́дость претворя́ющая.","Ра́дуйся, я́ко мо́лиши Си́на Твоєго́ і Бо́га на́шего всім нам спасти́ся;","ра́дуйся, я́ко твори́ши ми́лости всім в держа́вний Твой покро́в притека́ющим.","Ра́дуйся, Засту́пнице всіх су́щих в ско́рбіх і болі́зніх;","ра́дуйся, всім с ві́рою Тебі́ моля́щимся поле́зная да́рующая.","Ра́дуйся, Ма́ти Бо́жия Держа́вная, Засту́пнице усе́рдная ро́да христия́нськаго."]},{"h":"Кондак 13","ps":["О, всепі́тая Ма́ти, держа́вная Влади́чице! Прийми́ ни́ні сіє́ ма́лоє моле́ніє на́ше, і вели́чія ра́ди бла́гости Твоєя́ і неізрече́нних щедро́т Твої́х, не пом'яни́ мно́жества гріхо́в на́ших, но іспо́лни во благи́х проше́нія на́ша: да́руй нам вся потре́бная к животу́ і благоче́стію, ізба́ви нас от гла́да, болі́зней і печа́лі, і Ца́рствія небе́снаго наслі́дники всіх сотвори́, ві́рно вопію́щих Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелом ра́дость приі́мшая, благоволи́ла єси́, Влади́чице, возвісти́ти ста́рице благочести́вій ра́дость о явле́нії іко́ни Твоєя́ честни́я Держа́вния, ю́же і обрі́тше по указа́нію Твоєму́, я́ко зна́меніє ми́лости Бо́жієй к нам, грі́шним, благода́рственно вопіє́м Ті си́це:","Ра́дуйся, во́лі Госпо́дней та́йни нам открива́ющая;","ра́дуйся, гнів Єго́ пра́ведний, на ни дви́жимий, ум'ягча́ющая.","Ра́дуйся, нечести́вих злові́рія обличе́ніє;","ра́дуйся, горди́ні їх низложе́ніє.","Ра́дуйся, ві́ри христия́нськия утвержде́ніє;","ра́дуйся, почита́нія святи́х іко́н освяще́ніє.","Ра́дуйся, ти́хоє приста́нище спасе́нія душ на́ших;","ра́дуйся, Всеми́лостивая Засту́пнице на́ша у престо́ла Святи́я Тро́йці.","Ра́дуйся, от бід і скорбе́й на́ше ізбавле́ніє;","ра́дуйся, Це́ркве Правосла́вния утвержде́ніє.","Ра́дуйся, звіздо́ невече́рняго сві́та, нас озаря́ющая;","ра́дуйся, Ма́ти Сві́та, всіх просвіща́ющая.","Ра́дуйся, Ма́ти Бо́жия Держа́вная, Засту́пнице усе́рдная ро́да христия́нськаго."]},{"h":"Кондак 1","ps":["Ізбра́нній от всіх родо́в Засту́пнице ро́да христия́нськаго, покро́вом Своєя́ бла́гости покрива́ющей страну́ на́шу правосла́вную, благода́рственная пі́нія прино́сим Ті, Влади́чице, о явле́нії нам чу́дния іко́ни Твоєя́ Держа́вния. Ти же, я́ко Всеми́лостивая Засту́пниця всіх с ві́рою к Тебі́ притека́ющих, от вся́ких нас бід свободи́, да зове́м Ті:","Ра́дуйся, Ма́ти Бо́жия Держа́вная, Засту́пнице усе́рдная ро́да христия́нськаго."]},{"h":"Молитва","ps":["О, ми́ра Засту́пнице, Ма́ти Всепі́тая! Со стра́хом, ві́рою і любо́вію припа́дающе пред честно́ю іко́ною Твоє́ю Держа́вною, усе́рдно мо́лим Тя: не отврати́ лиця́ Твоєго́ от прибіга́ющих к Тебі́. Умоли́, милосе́рдая Ма́ти Сві́та, Си́на Твоєго́ і Бо́га на́шего, Сладча́йшаго Го́спода Ісу́са Христа́, да сохрани́ть в ми́рі страну́ на́шу, да утверди́ть держа́ву на́шу в благоде́нствії, і ізба́вить нас от междоусо́бния бра́ні, да укріпи́ть Святу́ю Це́рков на́шу Правосла́вную, і непози́блему соблюде́ть ю от неві́рія, раско́ла і єресе́й. Не і́мами бо іни́я по́мощі, ра́зві Тебе́, Пречи́стая Ді́во: Ти єси́ всеси́льная христия́н Засту́пниця пред Бо́гом, пра́ведний гнів Єго́ ум'ягча́ющая. Ізба́ви всіх, с ві́рою Тебі́ моля́щихся, от паде́ній гріхо́вних, от наві́та злих челові́к, от гла́да, скорбе́й і болі́зней. Да́руй нам дух сокруше́нія, смире́ніє се́рдця, чистоту́ помишле́ній, ісправле́ніє гріхо́вния жи́зні і оставле́ніє согріше́ній на́ших; да всі, благода́рні воспіва́юще вели́чія Твоя́, сподо́бимся Небе́снаго Ца́рствія і та́мо со всі́ми святи́ми просла́вим пречестно́є і великолі́поє і́м'я в Тро́йці сла́вимаго Бо́га: Отця́, Си́на і Свята́го Ду́ха. Амі́нь."]},{"h":"Молитва друга","ps":["О, Держа́вная Влади́чице Пресвята́я Богоро́дице, на об'я́тіїх Свої́х держа́щая Содержа́щаго всю вселе́нную Царя́ Небе́снаго! Благодари́м Тя за неізрече́нноє милосе́рдіє Твоє́, я́ко благоволи́ла єси́ яви́ти нам, грі́шним і недосто́йним, сію́ святу́ю і чудотво́рную іко́ну Твою́ во дні сія́ лука́вия і лю́тия, я́ко вихр, я́ко бу́ря ві́тренняя наше́дшая на страну́ на́шу, во дні унічиже́нія на́шего і укоре́нія, во дні разоре́нія і поруга́нія святи́нь на́ших от люде́й безу́мних, і́же не то́чію в се́рдці, но і устна́ми де́рзостно глаго́лють: ність Бог; і в ді́ліх сіє́ безбо́жіє показу́ють. Благодари́м Тя, Засту́пнице, я́ко призрі́ла єси́ с висоти́ святи́я Своєя́ на ско́рби на́ша і го́ре чад правосла́вних, і я́ко со́лнце сві́тлоє, увеселя́єши ізнемо́гшия от печа́лі очеса́ на́ша пресла́достним зрі́нієм Держа́внаго о́браза Твоєго́. О, Преблагослове́нная Ма́ти Бо́жия, Держа́вная Помо́щнице, крі́пкая Засту́пнице! Благодаря́ще Тя со стра́хом і тре́петом, я́ко раби́ непотре́бнії, припа́даєм Ті со умиле́нієм, с сокруше́нієм серде́чним і со слеза́ми, і мо́лим Тя, і стеня́ще вопіє́м Ті: спаси́ нас, спаси́! Помози́ нам, помози́! Потщи́ся, погиба́єм! Се живо́т наш а́ду прибли́жися; се обише́дше обидо́ша нас гріси́ мно́зі, біди́ мно́зі, вразі́ мно́зі. О, небе́сная Цари́це! Ски́петром вла́сті Твоєя́ Боже́ственния разсі́й, я́ко прах, я́ко дим, нечести́вия ко́зні враго́в на́ших ви́димих і неви́димих, сокруши́ велері́чивия помишле́нія їх і запрети́ їм, і я́ко Ма́ти всіх, на путь пра́вий і богоуго́дний наста́ви їх. Вкорени́ в сердця́ всіх нас пра́вду, мир і ра́дость о Ду́сі Свя́те; водвори́ в страні́ на́шей тишину́, благоде́нствіє, безм'яте́жіє, любо́в друг ко дру́гу нелицемі́рную. Держа́вою Твоє́ю всеси́льною удержи́, Пречи́стая, пото́ки беззако́нія, хотя́щия потопи́ти зе́млю Ру́ськую в стра́шній пучи́ні своє́й. Поддержи́ нас сла́бих, малоду́шних, немощни́х і уни́лих, укріпи́, возста́ви і спаси́. Я́ко да под держа́вою Твоє́ю всегда́ храни́мі, поє́м і велича́єм пречестно́є і великолі́поє і́м'я Твоє́, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Гра́да Сіо́нська взиску́юще, / под Твой покро́в, Ді́ва Чи́стая, днесь притека́єм, / і нікто́же возмо́жеть на ни, / я́ко ність град си́лен, а́ще не Су́щаго Бо́га, // і ність і́на крі́пость, а́ще не ми́лость Влади́чиці Ді́ви."]},{"h":"Інший тропар, глас 4","ps":["А́нгелов ли́ци благогові́йно Тебі́ слу́жать, / і вся Небе́сния си́ли немо́лчними гла́си Тя ублажа́ють, / Богоро́дице Ді́во; / усе́рдно мо́лим Тя, Влади́чице, / да пребу́деть Боже́ственная благода́ть / на честні́й іко́ні Твоє́й Держа́вній, / і світоза́рний луч сла́ви чуде́с Твої́х да нисхо́дить от нея́ / на всіх с ві́рою Тебі́ моля́щихся // і вопію́щих Бо́гу: Аллилу́я."]},{"h":"Кондак, глас 8","ps":["Взбра́нной Воєво́ді победи́тельния пі́сні прино́сим, / я́ко дарова́ся нам Держа́ва Твоя́, і нічесо́же устраші́мся, / не от ми́ра бо спасе́ніє на́ше, / но Превознесе́нния Влади́чиці милосе́рдієм огражда́ємся / і тому́ днесь ра́дуємся, // я́ко приї́де Засту́пниця на стра́жу землі́ Своєя́."]},{"h":"Інший кондак, глас 8","ps":["Взбра́нней Воєво́ді, Засту́пниці на́шей Держа́вній, / пі́сні благода́рственния прино́сим о дарова́нії нам іко́ни Єя́ святи́я, / є́юже огражда́єми, нічесо́же устраші́мся, / не от челові́к бо спасе́ніє на́ше, / но Преблагослове́нния Влади́чиці милосе́рдієм. / Ті́мже днесь ра́дуємся і пра́зднуєм сві́тло, // я́ко приї́де Держа́вная на стра́жу землі́ Своєя́."]},{"h":"Інший кондак, глас 8","ps":["Ізбра́нній от всіх родо́в Засту́пнице ро́да христия́нського, / покро́вом Своєя́ бла́гости покрива́ющей страну́ на́шу правосла́вную, / благода́рственная пі́нія прино́сим Ті, Влади́чице, / о явле́нії нам чу́дния іко́ни Твоєя́ Держа́вния. / Ти же, я́ко Всеми́лостивая Засту́пниця всіх, с ві́рою к Тебі́ притека́ющих, / от вся́ких нас бід свободи́, да зове́м Ті: / ра́дуйся, Ма́тер Бо́жия Держа́вная, // Засту́пнице Усе́рдная ро́да христия́нського."]},{"h":"Величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / Богоізбра́нная Отрокови́це, / і чтим Держа́вний о́браз святи́ні Твоєя́, / і́мже подає́ши ве́лію ми́лость // всім, с ві́рою к нему́ притека́ющим."]},{"h":"Інше величання","ps":["Досто́йно єсть / велича́ти Тя, / Богоро́дице, / землі́ Ру́ськия Цари́цю Небе́сную / і люде́й правосла́вних / Влади́чицю Держа́вную."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Живоносне Джерело»","e":"Akathist to the Theotokos before her icon “The Life-giving Spring”","secs":[{"h":"Кондак 1","ps":["Ізбра́нній от всіх родо́во Влади́чице Богоро́дице, благода́тную по́мощ нам явля́ющей, похва́льная воспису́єм Ті раби́ Твої́, Богоро́дице. Ти же, я́ко Преблага́я Ма́ти Бо́жия, ізле́й на нас вели́кия і бога́тия ми́лості Твоя́, неду́ги на́ша ісціли́ і ско́рби утоли́, да благода́рственно зове́м Тебі́:","Ра́дуйся, Влади́чице, Живоно́сний Істо́чниче ми́лости неоскудева́ющия."]},{"h":"Ікос 1","ps":["Арха́нгел і А́нгел мно́жество недоуміва́ють Тебе́, Ма́тер Бо́га Сло́ва, на вода́х зе́млю утверди́вшаго, разу́мно хвали́ти по достоя́нію. Ми же, честні́йшая Херуви́м, і сла́внійшая без сравне́нія Серафи́м, во умиле́нії о Твої́х благодія́ніїх, на нас би́вших, дерза́єм зва́ти Тебі́:","Ра́дуйся, Влади́чице, Бо́гом Отце́м ізбра́нная;","ра́дуйся, Ду́хом Святи́м осія́нная.","Ра́дуйся, рождество́м Си́на Бо́жия превознесе́нная;","ра́дуйся, в жена́х благослове́нная.","Ра́дуйся, Богоро́дицею велича́ємая;","ра́дуйся, от всіх родо́в ублажа́ємая.","Ра́дуйся, Влади́чице, Живоно́сний Істо́чниче ми́лости неоскудева́ющия."]},{"h":"Кондак 2","ps":["Ви́дящи, премилосе́рдная Ма́ти, сліпця́, в пусти́ні блужда́ющаго і от жа́жди стра́ждущаго, істо́чник води́ живи́я цели́тельния показа́ла єси́; он же, ісціле́ніє улучи́в, благода́рственно возопи́: Аллилу́я."]},{"h":"Ікос 2","ps":["Разумі́во воєво́да глас Твой Боже́ственний, ісціле́нія ра́ди сліпця́ істо́чник води́ указу́ющий, позна́ єго́ я́ко купі́ль Силоа́мськую, і́же не то́кмо жа́ждущаго напоя́єть, но і от сліпоти́ того́ свобожда́єть. Ми же ми́лости Твоєя́, Ді́во Богоро́дице, і́щуще, взива́єм Тебі́ си́це:","Ра́дуйся, Влади́чице, купі́ль спасе́нія живопису́ющая;","ра́дуйся, сліпоту́ душе́вную і тіле́сную ісціля́ющая.","Ра́дуйся, разсла́бленних утвержде́ніє;","ра́дуйся, хроми́х хожде́ніє.","Ра́дуйся, Ма́ти Сві́та, сліпи́м о́чі отверза́ющая;","ра́дуйся, сві́том і́стини во тьмі сідя́щия озаря́ющая.","Ра́дуйся, Влади́чице, Живоно́сний Істо́чниче ми́лости неоскудева́ющия."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго осіня́єть всіх, с ві́рою і благогові́нієм притека́ющих к Живоно́сному Істо́чнику Твоєму́, Пречи́стая Госпоже́ Влади́чице. Сего́ ра́ди си́лою благода́ті єго́ осіни́ і нас, Богома́ти, смире́нно к Тебі́ припа́дающия і моле́бно о Тебі́ вопію́щия: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи бога́тство милосе́рдія неізрече́нноє, Влади́чице, всім боля́щим ру́ку по́мощі Твоєя́, неду́ги врачу́ющую, стра́сті ісціля́ющую, в Живоно́снім Істо́чниці Твоє́м простира́єши; сего́ ра́ди вопіє́м Тебі́ си́це:","Ра́дуйся, істо́чниче непрестаю́щия ра́дости;","ра́дуйся, ча́ше неізрече́нния бла́гости.","Ра́дуйся, сокро́вище благода́ті неоскудіва́ємоє;","ра́дуйся, ми́лости у Тебе́ прося́щим ско́ро сію́ подаю́щая.","Ра́дуйся, неду́гов разли́чних ісціле́ніє;","ра́дуйся, печа́лей на́ших утоле́ніє.","Ра́дуйся, Влади́чице, Живоно́сний Істо́чниче ми́лости неоскудева́ющия."]},{"h":"Кондак 4","ps":["Бу́рею недоумі́нія сліпе́ць смуща́шеся, води́ іща́ жа́жду утоли́ти. І се, я́коже дре́вле, си́лою Бо́жиєю із ка́мене вода́ істочи́ся; та́ко і ни́ні в пусти́ні безво́дній істо́чник яви́ся. Та́мо Мойсе́й, істочи́тель води́; зді же Ти Сама́, о Богома́ти, Служи́тельниця чудесе́. Ті́мже мо́лимся: жа́ждущия ду́ші на́ша благоче́стія напо́й вода́ми, да зове́м о Тебі́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́ша воєво́да ди́вний глас Твой, Ма́ти милосе́рдія, істо́чник води́ указу́ющий, во є́же жа́ждущаго напоі́ти і сліпоту́ єго́ ісціли́ти, і сбитіє́ слове́с Твої́х зря, возопи́ си́це:","Ра́дуйся, Влади́чице, страда́льцев утіша́ющая;","ра́дуйся, боля́щих возставля́ющая.","Ра́дуйся, німи́м уста́ разріша́ющая;","ра́дуйся, всіх немощни́х врачу́ющая.","Ра́дуйся, бе́дствующим поможе́ніє;","ра́дуйся, унива́ющих утіше́ніє.","Ра́дуйся, Влади́чице, Живоно́сний Істо́чниче ми́лости неоскудева́ющия."]},{"h":"Кондак 5","ps":["Боже́ственную во́ду от Живоно́снаго Істо́чника Твоєго́, то́ки благода́ті ізлива́ющаго, почерпа́юще во ісціле́ніє неду́гов душе́вних і тіле́сних, Ді́во Богороди́тельнице, благода́рственно вопіє́м о Тебі́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́діша лю́діє сліпця́, водо́ю Живоно́снаго Істо́чника Твоєго́ прозрі́вшаго, Богома́ти, потща́шася пі́сньми я́ко дара́ми послужи́ти Тебі́ си́це:","Ра́дуйся, Влади́чице, милосе́рдія две́рі ві́рним отверза́ющая;","ра́дуйся, наді́ющихся на Тебі́ не посрамля́ющая.","Ра́дуйся, бі́дствующих утіша́ющая;","ра́дуйся, от напа́стей свобожда́ющая.","Ра́дуйся, ізнемога́ющих укріпля́ющая;","ра́дуйся, неду́гующих врачу́ющая.","Ра́дуйся, Влади́чице, Живоно́сний Істо́чниче ми́лости неоскудева́ющия."]},{"h":"Кондак 6","ps":["Пропові́дник чу́да Твоєго́, Ма́ти Бо́жия, бисть воєво́да, я́ко ди́вно сліпе́ць водо́ю от Живоно́снаго Істо́чника Твоєго́ прозрі́, си́це і нам те́мния зі́ниці душе́вния просвіти́, да благода́рственно пропові́дуєм ми́лості Твоя́, зову́ще: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ нам Живоно́сний Істо́чник Твой, премилосе́рдная Ма́ти, многоразли́чную благода́ть Си́на Твоєго́ і Бо́га на́шего, Христа́ Жизнода́вця, істоча́яй. Сего́ ра́ди прино́сим Ті пі́нія сицева́я:","Ра́дуйся, Влади́чице, усе́рдная на́ша Засту́пнице;","ра́дуйся, хра́мов Бо́жиїх Храни́тельнице.","Ра́дуйся, святи́х оби́телей пресла́вная Ігу́меніє;","ра́дуйся, в і́ночестві подвиза́ющихся вразумле́ніє.","Ра́дуйся, мона́шествующих в послуша́нії укріпле́ніє;","ра́дуйся, всіх христия́н покро́в і защище́ніє.","Ра́дуйся, Влади́чице, Живоно́сний Істо́чниче ми́лости неоскудева́ющия."]},{"h":"Кондак 7","ps":["Хотя́ благочести́вий Лев воєво́да, єму́же ца́рство предрекла́ єси́, благода́рственная принести́ Тебі́, храм на мі́сті явле́нія Твоєго́ чудесе́ устро́ї, Живоно́сний Істо́чник найменова́в о́ний, да всі по́мощі Твоєя́ і́щущії зді обріта́ють ю, вопію́ще о Тебі́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вая купі́ль Силоа́мськая, па́че о́ния дре́внія, яви́ся, Пречи́стая Влади́чице, храм Твой, в не́мже поклоня́ємся іко́ні Живоно́снаго Істо́чника, і́бо не єди́ною в лі́то і то́кмо пе́рвіє входя́щим здра́віє ті́ла подає́ши, но ви́ну вся́кий неду́г душе́вний і тіле́сний врачу́єши. Сего́ ра́ди вопіє́м Тебі́:","Ра́дуйся, купе́ле, ско́рби на́ша погружа́ющая;","ра́дуйся, ча́ше ра́дованія, в печа́лі утіше́ніє подаю́щая.","Ра́дуйся, ка́меню, жа́ждущия жи́зні напоя́яй;","ра́дуйся, дре́во, го́ркия во́ди мо́ря жите́йськаго услажда́ющеє.","Ра́дуйся, істо́чниче животво́рния води́ неістощи́мий;","ра́дуйся, ба́не, гріхо́вную скве́рну со́вісти на́шея омива́ющая.","Ра́дуйся, Влади́чице, Живоно́сний Істо́чниче ми́лости неоскудева́ющия."]},{"h":"Кондак 8","ps":["Стра́нноє і пресла́вноє чу́до яви́ся храм Живоно́снаго Істо́чника Твоєго́, Богоро́дице, в не́мже жа́жда духо́вная і тіле́сная утоля́ється, і болі́зньми одержи́мії ісціля́ються. Ми же, благода́ть такову́ю прославля́юще, вопіє́м Ті: Аллилу́я."]},{"h":"Ікос 8","ps":["Всім с ві́рою приходя́щим на Живоно́сний Істо́чник Твой вся потре́бная подає́ши, преми́лостивая Госпоже́ Богоро́дице. Ті́мже благода́рственно вопіє́м Тебі́ си́це:","Ра́дуйся, Влади́чице, я́ко Тобо́ю Безпло́тний воплоти́ся;","ра́дуйся, Ді́во, я́ко чистоті́ Твоє́й А́нгели удиви́шася.","Ра́дуйся, стра́ждущих ма́терей утіше́ніє;","ра́дуйся, чад безма́терніх охране́ніє.","Ра́дуйся, младе́нцев воспита́ніє;","ра́дуйся, ю́них Наста́внице.","Ра́дуйся, Влади́чице, Живоно́сний Істо́чниче ми́лости неоскудева́ющия."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ А́нгельськоє і челові́чеськоє диви́ться милосе́рдію Твоєму́, Пресвята́я Ді́во, я́ко всегда́ і всім явля́єшися Помо́щниця і Засту́пниця, пою́щим о Тебі́: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії многовіща́ннії не мо́гуть воспі́ти досто́йно Живоно́сний Істо́чник неістощи́мия благода́ті Твоєя́, ніже́ із'ясни́ти си́лу чуде́с Твої́х, во ісціле́ніє неду́жних і на вся́кую по́льзу душе́вную і тіле́сную челові́ком явля́ємую. Ми же похва́льная воспису́єм Тебі́ си́це:","Ра́дуйся, хра́мі Бо́га Жива́го;","ра́дуйся, жили́ще Ду́ха Свята́го.","Ра́дуйся, А́нгелов сла́во;","ра́дуйся, вселе́нния держа́во.","Ра́дуйся, ми́ра спасе́ніє;","ра́дуйся, ві́рних упова́ніє.","Ра́дуйся, Влади́чице, Живоно́сний Істо́чниче ми́лости неоскудева́ющия."]},{"h":"Кондак 10","ps":["Спасти́ хотя́щи вся стра́ждущия, істо́чник жи́зні яви́ла єси́ ми́рові, Пресвята́я Богоро́дице, во вода́х благода́ті, да всі, в ско́рбіх і печа́ліх ісціле́ніє і утіше́ніє приє́млюще, благода́рно зове́м о Тебі́: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ і покро́во в біда́х і ну́ждах по́мощі Твоєя́ прося́щим су́щи, Влади́чице ми́ра, Живоно́сний Істо́чник всім яви́ла єси́, да бу́деть от вся́ких болі́зней огражде́ніє, в напа́стіх і печа́ліх утіше́ніє, вопію́щим Ті такова́я:","Ра́дуйся, Влади́чице, го́рдих і стропти́вих челові́к усмире́ніє;","ра́дуйся, лука́вих і злих наме́реній пресіче́ніє.","Ра́дуйся, оби́димих заступле́ніє;","ра́дуйся, неви́нних оправда́ніє.","Ра́дуйся, во́їнов во бранеіх огражде́ніє;","ра́дуйся, пліне́нних от злих свобожде́ніє.","Ра́дуйся, Влади́чице, Живоно́сний Істо́чниче ми́лости неоскудева́ющия."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє пред Живоно́сним Істо́чником Твої́м па́ки і па́ки прино́сим Тебі́, Богоро́дице, в покая́нії зову́ще із глубини́ душі́: Влади́чице, прийми́ моли́тви раб Твої́х і ізба́ви нас от вся́кия ско́рби і болі́зні, ну́жди і печа́лі, да вопіє́м о Тебі́ Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рною свіще́ю сія́єть в ми́рі луча́ми благода́ті Боже́ственний Істо́чник Твой, Пресвята́я Богоро́дице, чудеси́ явле́нними уми́ і сердця́ просвіща́яй і наставля́яй зва́ти Тебі́:","Ра́дуйся, Влади́чице, помисло́в просвіще́ніє;","ра́дуйся, серде́ць на́ших очище́ніє.","Ра́дуйся, ду́ха обновле́ніє;","ра́дуйся, душ освяще́ніє.","Ра́дуйся, здра́вія укріпле́ніє;","ра́дуйся, цілому́дрія соблюде́ніє.","Ра́дуйся, Влади́чице, Живоно́сний Істо́чниче ми́лости неоскудева́ющия."]},{"h":"Кондак 12","ps":["Благода́ті Твоєя́ Живоно́сний Істо́чник іму́ще, Пресвята́я Ді́во, к Тебі́ прибіга́єм, я́ко к неруши́мій стіні́ і предста́тельству: при́зри благосе́рдієм, Пресвята́я Богоро́дице, на лю́тоє на́ше озлобле́ніє і ісціли́ душ і тіле́с на́ших ско́рби і болі́зні, да зове́м о Тебі́ Бо́гові: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Твоя́ чудеса́, хва́лим і сла́вим Живоно́сний Істо́чник Твой, Пресвята́я Ді́во, от него́же почерпа́юще то́ки многоразли́чния благода́ті, велича́єм Тя похвали́ сицеви́ми:","Ра́дуйся, Отрокови́це Богоізбра́нная;","ра́дуйся, Неві́сто Боговінча́нная.","Ра́дуйся, в жена́х благослове́нная;","ра́дуйся, па́че Го́рніх превознесе́нная.","Ра́дуйся, Престо́лу Госпо́дню ви́ну предстоя́щая;","ра́дуйся, Засту́пнице на́ша, за мир всегда́ моля́щаяся.","Ра́дуйся, Влади́чице, Живоно́сний Істо́чниче ми́лости неоскудева́ющия."]},{"h":"Кондак 13","ps":["О всепі́тая Ма́ти, Живоно́сний Істо́чник Твой ми́ру да́вшая, от него́же ізлива́єши нам вели́кия і бога́тия ми́лости, прийми́ благода́рственноє сіє́ моле́ніє на́ше, напо́й нас от істо́чника ми́лости Твоєя́ во ві́ці ни́нішнем і гряду́щем: да ви́ну зове́м о Тебі́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Арха́нгел і А́нгел мно́жество недоуміва́ють Тебе́, Ма́тер Бо́га Сло́ва, на вода́х зе́млю утверди́вшаго, разу́мно хвали́ти по достоя́нію. Ми же, честні́йшая Херуви́м, і сла́внійшая без сравне́нія Серафи́м, во умиле́нії о Твої́х благодія́ніїх, на нас би́вших, дерза́єм зва́ти Тебі́:","Ра́дуйся, Влади́чице, Бо́гом Отце́м ізбра́нная;","ра́дуйся, Ду́хом Святи́м осія́нная.","Ра́дуйся, рождество́м Си́на Бо́жия превознесе́нная;","ра́дуйся, в жена́х благослове́нная.","Ра́дуйся, Богоро́дицею велича́ємая;","ра́дуйся, от всіх родо́в ублажа́ємая.","Ра́дуйся, Влади́чице, Живоно́сний Істо́чниче ми́лости неоскудева́ющия."]},{"h":"Кондак 1","ps":["Ізбра́нній от всіх родо́во Влади́чице Богоро́дице, благода́тную по́мощ нам явля́ющей, похва́льная воспису́єм Ті раби́ Твої́, Богоро́дице. Ти же, я́ко Преблага́я Ма́ти Бо́жия, ізле́й на нас вели́кия і бога́тия ми́лості Твоя́, неду́ги на́ша ісціли́ і ско́рби утоли́, да благода́рственно зове́м Тебі́:","Ра́дуйся, Влади́чице, Живоно́сний Істо́чниче ми́лости неоскудева́ющия."]},{"h":"Молитва","ps":["О Пресвята́я Ді́во, всеми́лостивая Госпоже́ Влади́чице Богоро́дице, Живоно́сний Істо́чник Твой, ціле́бния да́ри на здра́віє душ і тіле́с на́ших і на спасе́ніє ми́ру точа́щий, подала́ єси́ нам, ті́мже благода́рні су́ще усе́рдно мо́лим Тя, Цари́це Пресвята́я, моли́ Си́на Твоєго́ і Бо́га на́шего да́ти нам оставле́ніє прегріше́ній і вся́кой душі́ скорбя́щей і озло́бленній ми́лость і утіше́ніє, і от бід, скорбе́й і болі́зней свобожде́ніє. Пода́ждь, Госпоже́, хра́му сему́ і сим лю́дем покрове́ніє (і святі́й оби́телі сей соблюде́ніє), гра́ду сему́ (іли́: ве́сі сей) сохране́ніє, страні́ на́шей от напа́стей ізбавле́ніє і огражде́ніє, да ми́рноє зді поживе́м житіє́, і в бу́дущем ві́ці сподо́бимся ви́діти Тебе́, Засту́пницю на́шу, во сла́ві Ца́рствія Си́на Твоєго́ і Бо́га на́шего, Єму́же сла́ва і держа́ва со Отце́м і Пресвяти́м Ду́хом во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Днесь притеце́м ві́рнії к Боже́ственному і цільбоно́сному о́бразу Пресвяти́я Богоро́диці, ізлія́вшия ка́плі свої́х ізлія́ній, і лю́дем ві́рним чуде́с показа́вшия, я́же ми ви́дяще і сли́шаще, духо́вно пра́зднуєм і любе́зно вопіє́м ісціли́ти на́ші неду́ги і стра́сті, я́коже і карки́нськия і тьмочи́сленния стра́сті ісціли́ла єси́. Ті́мже мо́лим Тя, Ді́во Пречи́стая, моли́ воплоще́ннаго із Тебе́ Христа́ Бо́га на́шего спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 8","ps":["От неістощи́мия / Ти, Істо́чниче Богоблагода́тний, подає́ши мі, точа́щи, во́ди / Твоєя́ благода́ті, / приснотеку́щий па́че сло́ва, / я́ко бо Сло́во ро́ждшая па́че сми́сла, / молю́тися, ороси́ м'я благода́тію, да зову́ Ті: // ра́дуйся, Водо́ спаси́тельная."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Богоізбра́нная Отрокови́це, і чтим о́браз Твой святи́й, і́мже то́чиши ісціле́нія всім с ві́рою притекающим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Володимирська»","e":"Akathist to the Theotokos before her icon “Vladimir”","secs":[{"h":"Кондак 1","ps":["Взбра́нной Воєво́ді, Засту́пниці на́шей, взира́юще на первопи́санний о́браз Твой, хвале́бноє пі́ніє воспіва́єм Ті раби́ Твої́, Богома́ти. Ти же, я́ко іму́щая держа́ву непобіди́мую, сохрани́ і спаси́ благода́рні Тебі́ вопію́щия:","Ра́дуйся, Пречи́стая, от іко́ни Твоєя́ ми́лости нам істоча́ющая."]},{"h":"Ікос 1","ps":["А́нгельськія Си́ли на Небесі́ немо́лчно воспіва́ють Тя, Пречи́стая, зря́ще Сла́ву Пребоже́ственную, є́юже Син Твой просла́ви Тя; но і нас, земни́х, не оста́вила єси́, я́ко ні́кую лучу́, низпосла́вши нам іко́ну Твою́, святи́м Луко́ю первопи́санную. О ней бо ні́когда ізрекла́ єси́: «С сим о́бразом благода́ть Моя́ і си́ла да пребу́дуть». Ті́мже ві́рнії раби́ Твої́, по вся дні і на вся́ком мі́сті сбитіє́ слове́с Твої́х зря́ще, ко о́бразу Твоєму́ цільбоно́сному притека́єм і, я́коже Само́й Ті, с на́ми су́щей, вопіє́м:","Ра́дуйся, А́нгелов Цари́це;","ра́дуйся, всего́ ми́ра Влади́чице.","Ра́дуйся, на Небесі́ при́сно сла́вимая;","ра́дуйся, і на землі́ велича́ємая.","Ра́дуйся, благода́ть Твою́ іко́ні Твоє́й сей дарова́вшая;","ра́дуйся, на спасе́ніє челові́ков ту́ю поста́вившая.","Ра́дуйся, Бо́жия бла́гости ско́рая Пода́тельнице;","ра́дуйся, моле́ній на́ших усе́рдная послу́шнице.","Ра́дуйся, Пречи́стая, от іко́ни Твоєя́ ми́лости нам істоча́ющая."]},{"h":"Кондак 2","ps":["Ви́дя чуде́с мно́жество, от принесе́нния во Ви́шград святи́я іко́ни Твоєя́ бива́ємоє, благові́рний князь Андре́й возгорі́ся ду́хом і умоля́ше Тя, да ска́жеши святу́ю во́лю Твою́ і да благослови́ши єго́ в преді́ли Росто́вськия отити́. Ті́мже улучи́в жела́ємоє і іко́ну Твою́ взем, ідя́ше в путь свой, ра́дуяся і поя́ Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Разумі́ша всі лю́діє ди́вноє ше́ствіє Твоє́, Цари́це Небе́сная, от Ки́єва в зе́млю Росто́вськую, боля́щії бо ісціля́хуся і і́на зна́менія і чудеса́ бива́ху всім с ві́рою притека́ющим ко о́бразу Твоєму́. Сего́ ра́ди воспі́ша Тебі́:","Ра́дуйся, чудеси́ ше́ствіє іко́ни Твоєя́ зна́менавшая;","ра́дуйся, мно́гі немощни́я ісціли́вшая.","Ра́дуйся, воздиха́нія на́ша не отверга́ющая;","ра́дуйся, недосто́йния моли́тви на́ша приє́млющая.","Ра́дуйся, Ма́тернія щедро́ти Твоя́ на нас ізлива́ющая;","ра́дуйся, іко́ною Твоє́ю нам благоде́ющая.","Ра́дуйся, во обстоя́нії су́щим ско́рую по́мощ да́рующая;","ра́дуйся, отча́янним наде́жду возвраща́ющая.","Ра́дуйся, Пречи́стая, от іко́ни Твоєя́ ми́лости нам істоча́ющая."]},{"h":"Кондак 3","ps":["Си́лою Твоє́ю огражда́єм, благові́рний князь Андре́й преді́л Влади́мирських дости́же і зді благу́ю во́лю твою́, Влади́чице, позна́. В нощно́м бо виді́нії тому́ я́вльшися, повелі́ла єси́ от мі́ста сего́ не отходи́ти і чудотво́рную іко́ну Твою́ зді, во гра́ді Влади́мире, поста́вити, да бу́деть сі́верній страні́ на́шей в благослове́ніє і лю́дем Твої́м в покро́в, вопію́щим Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я в себі́ благода́тноє сокро́вище, іко́ну Твою́ Влади́мирськую, преуспева́ше от си́ли в си́лу Оте́чество на́ше. Во дні бо обстоя́ній і напа́стей не оста́вила єси́ род наш, Влади́чице, і во благовре́менії близ била́ єси́, всеси́льним предста́тельством Твої́м ві́рния лю́ди Твоя́ заступа́ющи, пою́щия Ті:","Ра́дуйся, гнів Бо́жий, пра́ведно на ни дви́жимий, утоля́ющая;","ра́дуйся, на ми́лость к нам, грі́шним, Го́спода преклоня́ющая.","Ра́дуйся, я́ко смире́нним мольба́м рабо́в Твої́х вне́млеши;","ра́дуйся, я́ко утіше́ніє Твоє́ нам пода́ти поспеша́єши.","Ра́дуйся, я́ко іко́ною Твоє́ю от вся́ких нас бід огражда́єши;","ра́дуйся, я́ко то́ю ко́зні вра́жия разруша́єши.","Ра́дуйся, в час ско́рби лю́ди Твоя́ укріпля́ющая;","ра́дуйся, ти́хоє і безм'яте́жноє житіє́ тім да́рующая.","Ра́дуйся, Пречи́стая, от іко́ни Твоєя́ ми́лости нам істоча́ющая."]},{"h":"Кондак 4","ps":["Бу́рю помишле́ній сумни́тельних про́йде благові́рний князь Андре́й, от мно́жества враго́в ні́когда обстої́м; Ти же, Всепі́тая, ди́вним от іко́ни Твоєя́ зна́менієм сла́вную побі́ду тому́ предвозвести́ла єси́. Ті́мже ві́рою обнови́ся і о і́мені Твоє́м дерза́я, воспі́ Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше м'яте́жници убіє́ніє благові́рнаго кня́зя Андре́я, град Влади́мир расхи́тити устреми́шася, но іко́ну Твою́ чудотво́рную, на сто́гни гра́да ізнесе́нную, внеза́пу узрі́вше, умили́шася се́рдцем і, на колі́на па́дше, во грісі́ своє́м пока́яшася. Благочести́вії же лю́діє, таково́му от іко́ни Твоєя́ благода́тному явле́нію ра́дующеся, піснь благода́рственную воспі́ша Тебі́:","Ра́дуйся, междоусо́бних бра́ней утоле́ніє;","ра́дуйся, ожесте́вших серде́ць ум'ягче́ніє.","Ра́дуйся, я́ко заблу́ждшия на путь пра́вий возвраща́єши;","ра́дуйся, я́ко от собла́знов су́єтних нас огражда́єши.","Ра́дуйся, па́губи вседуше́вния низлага́ющая;","ра́дуйся, душевре́дная науче́нія облича́ющая.","Ра́дуйся, к Ца́рствію Небе́сному путь невозбра́нний нам указу́ющая;","ра́дуйся, мир ві́чний і ра́дость нам подаю́щая.","Ра́дуйся, Пречи́стая, от іко́ни Твоєя́ ми́лости нам істоча́ющая."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́ отце́м на́шим бисть іко́на Твоя́, Влади́чице, єя́же сві́том ведо́ми, мно́гажди побіжда́ху ца́рствія, возмога́ху от не́мощі, обраща́ху в бі́гство полки́ чужди́х і путь к земно́му преуспі́янію і небе́сному спасе́нію обріта́ху. Сего́ ра́ди по до́лгу сла́вить Тя земля́ Украї́нськая, пою́щи Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше ні́когда лю́діє влади́мирстії в чу́днім виді́нії град свой на возду́сі вознесе́н, і іко́ну Твою́ верху́ єго́, я́коже со́лнце, сія́ющу, со умиле́нієм разумі́ша, Влади́чице, неотсту́пний покро́в Твой гра́ду їх і, Твоє́ ми́лостивоє промишле́ніє о них сла́в'яще, воспі́ша Ті:","Ра́дуйся, Ма́ти милосе́рдія;","ра́дуйся, істо́чниче чуде́с.","Ра́дуйся, бо́драя на́ша Храни́тельнице;","ра́дуйся, гра́ду на́шему Покро́ве.","Ра́дуйся, горі́ к Небе́снім сокро́вищем ум наш возводя́щая;","ра́дуйся, любо́в к Бо́гу в сердця́х ві́рних насажда́ющая.","Ра́дуйся, малові́рния вразумля́ющая;","ра́дуйся, неві́рних сми́сли просвіща́ющая.","Ра́дуйся, Пречи́стая, от іко́ни Твоєя́ ми́лости нам істоча́ющая."]},{"h":"Кондак 6","ps":["Пропові́дник неізрече́нних чуде́с Твої́х, Влади́чице, яви́ся собо́рний храм Твой во гра́ді Влади́мире, свято́ю іко́ною Твоє́ю украше́нний. Попуще́нієм бо Бо́жиїм все благолі́піє єго́ ні́когда во огні́ поги́бе, іко́на же свята́я Твоя́, я́коже купина́ неопали́ма преби́сть, да і ви́дівше і осяза́вше прису́тствіє Твоє́, ві́рнії воспою́ть: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ па́ки світ іко́ни Твоєя́, Богоро́дице, во дні лю́таго наше́ствія Бати́єва. А́ще бо нечести́вії ага́ряне і пожго́ша огне́м собо́рний храм Твой, і святи́теля Влади́мирськаго і лю́ди, моля́щіяся в це́ркві, умертви́ша, і вся коне́чному істребле́нію преда́ша, оба́че іко́на Твоя́ і па́ки неврежде́на обрі́теся, подвиза́ющи пі́ти Тебі́:","Ра́дуйся, Купино́ Неопали́мая;","ра́дуйся, Сокро́вище неіждива́ємоє.","Ра́дуйся, Стіно́ несокруши́мая;","ра́дуйся, прибі́жище всім упова́ющим на Тя.","Ра́дуйся, іко́ну Твою́ і во пла́мені ці́лу сохрани́вшая;","ра́дуйся, нам во утіше́ніє і спасе́ніє ту́ю оста́вившая.","Ра́дуйся, Ти бо єси́ на́ше защище́ніє;","ра́дуйся, Ти бо єси́ всіх благочести́вих непреста́нноє ра́дованіє.","Ра́дуйся, Пречи́стая, от іко́ни Твоєя́ ми́лости нам істоча́ющая."]},{"h":"Кондак 7","ps":["Хотя́ вели́кий князь Васи́лій защище́ніє стяжа́ти сто́льному гра́ду своєму́, повелі́ Влади́мирськую іко́ну Твою́ в Москву́ пренести́. І во срі́теніє єя́ усе́рдно ізше́дше князь і святи́тель моско́вський Киприя́н со освяще́нним собо́ром і всім мно́жеством люде́й, до землі́ пред не́ю поклони́шася, я́коже бо Са́мую Тя, Пречи́стая, к ним приходя́щую, сріта́ху, зову́ще Тебі́: «О Ма́ти Бо́жия, спаси́ зе́млю Ру́ськую», вку́пі же і пою́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє зна́меніє сотвори́ла єси́, Пренепоро́чная, в день пра́зднованія срі́тенія іко́ни Твоєя́ Влади́мирськия в Москві́: в гро́зном бо виді́нії, я́ко всемогу́щая Цари́ця, мно́жеством во́їнств Небе́сних обстої́ма, со святи́телі Моско́вськими яви́лася єси́ нечести́вому ага́рянському ха́ну і от преді́л землі́ Ру́ськия отити́ повелі́ла єси́. Тогда́ ві́рнії лю́діє Твої́, врага́ ви́дівше посра́млена і біжа́вша, с весе́лієм поя́ху Тебі́:","Ра́дуйся, Побі́до непобіди́мая;","ра́дуйся, Цари́це Небе́сних Сил.","Ра́дуйся, врага́ гро́зноє посрамле́ніє;","ра́дуйся, рабо́в Твої́х Ра́досте неча́янная.","Ра́дуйся, Наде́ждо всіх лише́нних наде́жди;","ра́дуйся, спасе́ніє во дно а́дово низше́дших.","Ра́дуйся, прише́ствієм іко́ни Твоєя́ Москву́ возвесели́вшая;","ра́дуйся, заступле́нієм Твої́м і град Влади́мир не оста́вившая.","Ра́дуйся, Пречи́стая, от іко́ни Твоєя́ ми́лости нам істоча́ющая."]},{"h":"Кондак 8","ps":["Стра́нную побі́ду всеси́льною по́мощію Твоє́ю, Влади́чице, без бра́ні соверши́вшуюся, і до ни́ні Це́рков Правосла́вная сві́тло прославля́єть, срі́теніє іко́ни Твоєя́ Влади́мирськия пра́зднующи і вся ві́рная ча́да Своя́ созива́ющи ми́лості Твоя́ благода́рні іспові́дати, Си́ну же Твоєму́ і Бо́гу пі́ти: Аллилу́я."]},{"h":"Ікос 8","ps":["Всю Тя Бог освяти́, Пренепоро́чная, і, я́ко Ма́тер Свою́, в гото́воє прибі́жище і те́плий покро́во всім нам дарова́. Ті́мже от ме́ньших землі́ і незна́ємих возвели́чися благослове́нний Тобо́ю град Москва́, благоче́стно іко́ну Твою́ почита́яй; вся бо племена́ ру́ськая воєди́но собра́ і о́бласть свою́ над окре́стними язи́ки от мо́ря і до мо́ря і да́же до коне́ць землі́ распростре́, всім ві́ру Христо́ву возвіща́яй, Тебі́ же вопія́:","Ра́дуйся, землі́ на́шея забра́ло;","ра́дуйся, Це́ркве утвержде́ніє.","Ра́дуйся, моли́твенников на́ших похвало́;","ра́дуйся, люде́й Твої́х спасе́ніє.","Ра́дуйся, враги́ на́ша устраша́ющая;","ра́дуйся, полки́ чужди́х дале́че отгоня́ющая.","Ра́дуйся, я́ко Тобо́ю Русь правосла́вная содержи́ться;","ра́дуйся, я́ко Тобо́ю род христия́нський хва́литься.","Ра́дуйся, Пречи́стая, от іко́ни Твоєя́ ми́лости нам істоча́ющая."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ а́нгельськоє восхваля́єть Тя, Богороди́тельнице, у престо́ла Си́на Твоєго́ предстоя́щую і за страну́ на́шу і вся христия́ни моля́щуюся. Ми же, лю́діє Твої́, моли́тв Твої́х ді́йство разуміва́юще, к чудотво́рній іко́ні Твоє́й с любо́вію притека́єм і Бо́гу прилі́жно вопіє́м: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́й земни́х худо́жество не довлі́єть по достоя́нію благохвали́ти Тя, Пресвята́я Всенепоро́чная, і іко́ни Твоєя́ чудеса́ ісчи́слити, і́миже Це́рков Правосла́вная велича́ється, гра́ди на́ші утвержда́ються і всі христия́не Боже́ственне веселя́ться. Ті́мже, за премно́гую любо́в Твою́ к нам і вся ми́лості Твоя́, прийми́ от нас сіє́ хвале́бноє пі́ніє:","Ра́дуйся, собо́ром святи́х, в страні́ на́шей просія́вших, окружа́ємая і сла́вимая;","ра́дуйся, предста́телей на́ших, чудотво́рцев украї́нських, моле́нія приє́млющая.","Ра́дуйся, хода́тайством Твої́м о нас Бо́га умилостивля́ющая;","ра́дуйся, честни́м покро́вом Твої́м нас при́сно осіня́ющая.","Ра́дуйся, страни́ на́шея пресла́вная Защи́тнице;","ра́дуйся, призива́ющим Тя ско́рая Помо́щнице.","Ра́дуйся, тружда́ющихся благода́тноє укріпле́ніє;","ра́дуйся, ка́ющихся грі́шников несумні́нноє спасе́ніє.","Ра́дуйся, Пречи́стая, от іко́ни Твоєя́ ми́лости нам істоча́ющая."]},{"h":"Кондак 10","ps":["Спасе́нія і́щуще, к Тебі́ прибіга́єм, Милосе́рдная Ма́ти, і, чудотво́рную Твою́ іко́ну ни́ні обстоя́ще, вся ми́лості Твоя́, то́ю отце́м на́шим явле́нния, с любо́вію воспомина́єм. Да не тще́тна бу́деть, Влади́чице, і на́ша наде́жда на Тя, на не́мощ на́шу умилосе́рдися і спаси́ вопію́щия Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ і заступле́ніє всім с ві́рою прибега́ющим к Тебі́, Всеблаже́нная Отрокови́це; всегда́ бо ми́лості Твоя́ ро́ду христия́нському явля́ла єси́ і отце́м на́шим многоча́стні і многообра́зні благоді́яла єси́, от наше́ствія іноплеме́нник і от вся́кия біди́ і ну́жди тіх ізбавля́ющи. Не оскуді́й і ни́ні, Влади́чице, утоля́ющи лю́тия на ни возста́нія гріхо́вния, і о́блак іскуше́ній отжени́, Тебі́ бо навико́хом пі́ти:","Ра́дуйся, Ма́ти Бо́жия, Ма́тернюю любо́в к нам, грі́шним, простира́ющая;","ра́дуйся, си́лою Твоє́ю на́шу не́мощ восполня́ющая.","Ра́дуйся, милосе́рдіє Бо́жиє разумі́ти нас науча́ющая;","ра́дуйся, к діло́м милосе́рдія і нас возбужда́ющая.","Ра́дуйся, страх Бо́жий в сердця́ ві́рних влага́ющая;","ра́дуйся, грі́шники к покая́нію призива́ющая.","Ра́дуйся, невнима́нію на́шему долготерп'я́щая;","ра́дуйся, от сна лі́ности нас возставля́ющая.","Ра́дуйся, Пречи́стая, от іко́ни Твоєя́ ми́лости нам істоча́ющая."]},{"h":"Кондак 11","ps":["Пі́ніє похва́льноє воспі́ша моско́встії лю́діє, спасе́ніє Твоє́ ні́когда улучи́вше; верху́ бо я́вльшися, світоза́рною оде́ждою оді́яна, храм Твой і град Москву́ от запале́нія о́гненнаго ри́зою Твоє́ю защити́ла єси́. Неотсту́пна пребу́ди, Всемо́щная, от мі́ста сего́ і ни́ні, і нам ізбавле́ніє Твоє́ ви́діти да́руй, да веселя́щеся воспоє́м: Аллилу́я."]},{"h":"Ікос 11","ps":["Світ ра́дости возсія́ла єси́, Влади́чице, і во дні ти́я, єгда́ смотре́нієм Бо́жиїм дре́вняя красота́ церко́вная к нам па́ки возврати́ся і свяще́нний собо́р гра́ду Москві́ Патріа́рха, всей же страні́ на́шей єди́наго па́стиря і моли́твенника утверди́. Ти же, Пречи́стая, от іко́ни Твоєя́ Влади́мирськия жре́бій первосвяти́тельства сего́ ізбра́ннику Твоєму́ дарова́ла єси́, да расточе́нния о́вці слове́снаго ста́да Це́ркве Украї́нськия па́ки воєди́но собере́ть. Сего́ ра́ди вопіє́м Тебі́:","Ра́дуйся, скорб'я́щих ра́досте;","ра́дуйся, обурева́ємих приста́нище.","Ра́дуйся, в напа́стіх нас не оста́вившая;","ра́дуйся, во уничиже́нії на́шем світ наде́жди нам возсія́вшая.","Ра́дуйся, на смире́нния призре́вшая;","ра́дуйся, низше́дшия возвели́чившая.","Ра́дуйся, Це́ркве на́шея Похвало́;","ра́дуйся, люде́й Твої́х весе́ліє.","Ра́дуйся, Пречи́стая, от іко́ни Твоєя́ ми́лости нам істоча́ющая."]},{"h":"Кондак 12","ps":["Благода́ть Твою́ не отими́ от нас, ми́лости Істо́чниче, я́коже во дні лихолі́тія святи́телей на́ших І́ова і Єрмоге́на усли́шала єси́ і зе́млю Ру́ськую от коне́чнаго расхище́нія, правосла́вную же ві́ру в ней от істребле́нія спасла́ єси́, да ізба́вленнії Тобо́ю Бо́гу воспоє́м: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще неісче́тния ми́лості Твоя́, от літ дре́вніх ро́ду на́шему явле́нния і дони́ні не оскудева́ющия, хва́лим Тя, Пречи́стая, я́ко неуси́пную Храни́тельницю на́шу і заступле́ніє, і, Ма́тернюю любо́в Твою́ к ста́ду Си́на Твоєго́ ві́дуще, со дерзнове́нієм, а́ще і раби́ неключи́ми єсьми́, вопіє́м Тебі́:","Ра́дуйся, Русь Правосла́вную возлюби́вшая;","ра́дуйся, ві́ру і́стинную в ней утверди́вшая.","Ра́дуйся, отці́ на́ша во благоче́стії сохрани́вшая;","ра́дуйся, і на́ше неможе́ніє не отри́нувшая.","Ра́дуйся, утвержде́ніє на́ше нези́блемоє;","ра́дуйся, Наде́ждо на́ша непости́дная.","Ра́дуйся, Моли́твеннице на́ша те́плая;","ра́дуйся, Засту́пнице усе́рдная.","Ра́дуйся, Пречи́стая, от іко́ни Твоєя́ ми́лости нам істоча́ющая."]},{"h":"Кондак 13","ps":["О Всепі́тая Ма́ти, Засту́пнице Всеми́лостивая, Ді́во Богоро́дице, оби́чним Твої́м милосе́рдієм ма́лоє моле́ніє сіє́ на́ше приє́млющи, я́коже дре́вле, та́ко і ни́ні поми́луй зе́млю на́шу Ру́ськую і от вся́ких бід раби́ Твоя́ ізба́ви, о Тебі́ вопію́щия: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельськія Си́ли на Небесі́ немо́лчно воспіва́ють Тя, Пречи́стая, зря́ще Сла́ву Пребоже́ственную, є́юже Син Твой просла́ви Тя; но і нас, земни́х, не оста́вила єси́, я́ко ні́кую лучу́, низпосла́вши нам іко́ну Твою́, святи́м Луко́ю первопи́санную. О ней бо ні́когда ізрекла́ єси́: «С сим о́бразом благода́ть Моя́ і си́ла да пребу́дуть». Ті́мже ві́рнії раби́ Твої́, по вся дні і на вся́ком мі́сті сбитіє́ слове́с Твої́х зря́ще, ко о́бразу Твоєму́ цільбоно́сному притека́єм і, я́коже Само́й Ті, с на́ми су́щей, вопіє́м:","Ра́дуйся, А́нгелов Цари́це;","ра́дуйся, всего́ ми́ра Влади́чице.","Ра́дуйся, на Небесі́ при́сно сла́вимая;","ра́дуйся, і на землі́ велича́ємая.","Ра́дуйся, благода́ть Твою́ іко́ні Твоє́й сей дарова́вшая;","ра́дуйся, на спасе́ніє челові́ков ту́ю поста́вившая.","Ра́дуйся, Бо́жия бла́гости ско́рая Пода́тельнице;","ра́дуйся, моле́ній на́ших усе́рдная послу́шнице.","Ра́дуйся, Пречи́стая, от іко́ни Твоєя́ ми́лости нам істоча́ющая."]},{"h":"Кондак 1","ps":["Взбра́нной Воєво́ді, Засту́пниці на́шей, взира́юще на первопи́санний о́браз Твой, хвале́бноє пі́ніє воспіва́єм Ті раби́ Твої́, Богома́ти. Ти же, я́ко іму́щая держа́ву непобіди́мую, сохрани́ і спаси́ благода́рні Тебі́ вопію́щия:","Ра́дуйся, Пречи́стая, от іко́ни Твоєя́ ми́лости нам істоча́ющая."]},{"h":"Молитва","ps":["О Всеми́лостивая Госпоже́ Богоро́дице, Небе́сная Цари́це, Всемо́щная Засту́пнице, непости́дноє на́ше Упова́ніє! Благодаря́ще Тя о всіх вели́ких благодія́ніях, в ро́ди родо́в лю́дем украї́нським от Тебе́ би́вших, пред пречи́стим о́бразом Твої́м мо́лим Тя: сохрани́ град сей (іли́: весь сію́, іли́: святу́ю оби́тель сію́) і предстоя́щия раби́ Твоя́ і всю Зе́млю Ру́ськую от гла́да, губи́тельства, землі́ трясе́нія, пото́па, огня́, меча́, наше́ствія іноплеме́нних і междоусо́бния бра́ні. Сохрани́ і спаси́, Госпоже́, Вели́каго Господи́на і Отця́ на́шего (і́м'я рек), Святі́йшаго Патріа́рха Моско́вськаго і всея́ Руси́, і Господи́на на́шего (і́м'я рек), Преосвяще́ннійшаго єпи́скопа (іли́: архієпи́скопа, іли́: митрополи́та) (ти́тул), і вся Преосвяще́нния митрополи́ти, архієпи́скопи і єпи́скопи правосла́вния. Даждь їм Це́рков Украї́нськую до́брі упра́вити, ві́рния о́вці Христо́ви неги́блеми соблюсти́. Пом'яни́, Влади́чице, і весь свяще́нничеський і мона́шеський чин, согрі́й сердця́ їх ре́вностію о Бо́зі і досто́йно зва́нія своєго́ ходи́ти коєго́ждо укріпи́. Спаси́, Госпоже́, і поми́луй і вся раби́ Твоя́ і да́руй нам путь земна́го по́прища без поро́ка прейти́. Утверди́ нас во ві́рі Христо́вой і во усе́рдії ко Правосла́вній Це́ркві, вложи́ в сердця́ на́ша дух стра́ха Бо́жия, дух благоче́стія, дух смире́нія, в напа́стіх терпі́ніє нам пода́ждь, во благоде́нствії — воздержа́ніє, к бли́жнім любо́в, ко враго́м всепроще́ніє, в до́брих ді́ліх преуспі́яніє. Ізба́ви нас от вся́каго іскуше́нія і от окамене́ннаго нечу́вствія, в стра́шний же день Суда́ сподо́би нас хода́тайством Твої́м ста́ти одесну́ю Си́на Твоєго́, Христа́ Бо́га на́шего, Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє со Отце́м і Святи́м Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Днесь сві́тло красу́ється сла́внійший град Москва́, / я́ко зарю́ со́лнечную восприє́мши, Влади́чице, / чудотво́рную Твою́ іко́ну, / к не́йже ни́ні ми притека́юще і моля́щеся Тебі́, взива́єм си́це: / о, пречу́дная Влади́чице Богоро́дице! / Моли́ся із Тебе́ воплоще́нному Христу́ Бо́гу на́шему, / да ізба́вить град сей і вся гра́ди і страни́ христия́нськия / невреди́ми от всіх наві́т вра́жиїх, // і спасе́ть ду́ші на́ша, я́ко Милосе́рд."]},{"h":"Кондак, глас 8","ps":["Взбра́нной Воєво́ді побіди́тельная, / я́ко ізба́вльшеся от злих / прише́ствієм Твоєго́ честна́го о́браза, Влади́чице Богоро́дице, / сві́тло сотворя́єм пра́зднество срі́тенія Твоєго́ і оби́чно зове́м Ті: // ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Богоізбра́нная Отрокови́це, і чтим о́браз Твой святи́й, і́мже то́чиши ісціле́нія всім с ві́рою притекающим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Тихвінська»","e":"Akathist to the Theotokos before her icon “Tikhvin”","secs":[{"h":"Кондак 1","ps":["Взбра́нной Воєво́ді, Влади́чиці на́шей Богоро́диці благода́рственная пі́нія воспису́єм о явле́нії чу́дния Єя́ іко́ни, к не́йже притека́ющії при́сно ізбавля́ються от враг ви́димих і неви́димих. Ти же, Госпоже́ не́ба і землі́, я́ко милосе́рдая Ма́ти, прийми́ ни́ні ма́лоє сіє́ моле́ніє на́ше і неотсту́пну нікогда́же сотвори́ ми́лость Твою́ от нас і заступле́ніє, охраня́ющи от всіх бід і напа́стей нас, зову́щих Ті:","Ра́дуйся, Влади́чице, ми́лостивая о нас пред Бо́гом Засту́пнице."]},{"h":"Ікос 1","ps":["А́нгелов ли́ци ликовству́юще слу́жать Тебе́, Влади́чице, і почита́юще Тя, на руку́ Твоє́ю носи́вшую Творця́ ви́димия і неви́димия тва́рі, іко́ну Твою́ с мі́ста на мі́сто прено́сять. Ми же, земноро́днії, див'я́щеся чу́дному явле́нію іко́ни Твоєя́, А́нгели носи́мия, вопіє́м Ті си́це:","Ра́дуйся, всіх Небе́сних Сил ви́сшая;","ра́дуйся, вся а́нгельськия чи́ни превосходя́щая.","Ра́дуйся, честні́йшая Херуви́м;","ра́дуйся, сла́внійшая без сравне́нія Серафи́м.","Ра́дуйся, ра́дованіє А́нгелов;","ра́дуйся, похвале́ніє лико́в небе́сних.","Ра́дуйся, от А́нгелов воспіва́ємая;","ра́дуйся, от Серафи́мов прославля́ємая.","Ра́дуйся, от Арха́нгел покланя́ємая;","ра́дуйся, от во́їнств небе́сних почита́ємая.","Ра́дуйся, в іко́ні Твоє́й от А́нгел чти́мая;","ра́дуйся, во ви́димом о́бразі Твоє́м от неви́димих сил носи́мая.","Ра́дуйся, Влади́чице, ми́лостивая о нас пред Бо́гом Засту́пнице."]},{"h":"Кондак 2","ps":["Ви́дяще ри́баріє над пучи́ною вод носи́мую неви́димою си́лою і сві́том подо́бно со́лнцю сія́ющую Твою́, Богома́ти, іко́ну с Предві́чним Младе́нцем, ри́барей призва́вшим на уловле́ніє ми́ра в сі́ті спасе́нія, возопи́ша: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум недоразумі́нний ди́внаго явле́нія іко́ни Твоєя́ разумі́ти лю́діє і́щуще, уві́діша, я́ко чти́мая в Царегра́ді пречестна́я іко́на в наслі́діє Украї́нському ро́ду дарова́ся. Ті́мже ми, благодаря́ще за ми́лость Твою́ к ро́ду на́шему, вопіє́м Ті:","Ра́дуйся, Ма́ти і́стинния Жи́зні;","ра́дуйся, послуша́нієм Твої́м преслуша́ніє Є́ви ісціли́вшая.","Ра́дуйся, затворе́нний Єде́м отве́рзшая;","ра́дуйся, ми́ру яви́вшая Сокруши́теля глави́ змі́євой.","Ра́дуйся, ковче́же, Умири́теля ми́ра носи́вший;","ра́дуйся, мир спа́сшая от потопле́нія гріхо́внаго.","Ра́дуйся, лі́ствице, Є́юже сни́де Бог;","ра́дуйся, земни́х возводя́щая на не́бо.","Ра́дуйся, мо́ре, фарао́на ми́сленнаго потопи́вшеє;","ра́дуйся, купино́, неопали́вшаяся все́льшимся в Тя огне́м Божества́.","Ра́дуйся, скрижа́ле Богопи́санная;","ра́дуйся, ка́меню, во́ду жи́зні істочи́вший жа́ждущим.","Ра́дуйся, Влади́чице, ми́лостивая о нас пред Бо́гом Засту́пнице."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго осіня́ше страну́ Ти́хвинськую, єгда́ іко́на Пречи́стия Богома́тере, многоча́стні явля́ющися і вре́менним пребива́нієм освяща́ющи зе́млю, к воздвиза́нію хра́мов святи́х возбужда́ше, да сла́виться і́м'я Влади́чиці во сла́ву Триіпоста́снаго Бо́га, Єму́же вопіє́м: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще благоутро́бноє ізволе́ніє, да лю́діє страни́ Ти́хвинськия вожделі́ють пребива́нія Твоєго́ с ни́ми да па́м'ятують ви́ну покро́в Твой, іко́ну Твою́ явля́ла єси́ многоча́стні, до́ндеже указа́ла єси́ богоізбра́нноє мі́сто вселе́нія єя́. Ті́мже чудя́щеся вопіє́м Ті:","Ра́дуйся, ски́ніє, в Не́йже всели́ся Божество́ тіле́сні;","ра́дуйся, свята́я святи́х, в Ню́же єди́ною вни́де ві́чний Архієре́й.","Ра́дуйся, киво́те позлаще́нний Ду́хом, Законода́теля носи́вший;","ра́дуйся, світи́льниче, огне́м Боже́ственним возжже́нний.","Ра́дуйся, ста́мно, носи́вшая ма́нну жи́зні Христа́;","ра́дуйся, трапе́зо, Хліб живо́тний вмісти́вшая.","Ра́дуйся, кади́льнице угль Божества́ іму́щая, мир весь облагоуха́вшая;","ра́дуйся, же́зле, Цвіт прозя́бший Христа́.","Ра́дуйся, сто́лпе, к ві́чному наслі́дію руководя́й;","ра́дуйся, о́блаче, от враг ви́димих і неви́димих покрива́яй.","Ра́дуйся, земле́ обітова́нія;","ра́дуйся, руно́, на Не́же Христо́с, я́ко дождь сни́де с небесе́.","Ра́дуйся, Влади́чице, ми́лостивая о нас пред Бо́гом Засту́пнице."]},{"h":"Кондак 4","ps":["Бу́рю смуще́нія і ско́рби утоли́ти тща́щеся, благові́рнії лю́діє взива́ша ко Го́споду: яви́ нам боже́ственний дар, єго́же человіколю́бно страні́ Украї́нській посла́л єси́, не скрий сокро́вища, і́мже душе́вную нищету́ на́шу обогати́ти наді́яхомся, претвори́ печа́ль на́шу в ра́дость, отри́ сле́зи і рида́нія. І улучи́вше жела́ємоє, возопи́ша: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав па́стир па́стви своєя́ ра́достноє обрі́теніє і Ма́тер Пастиренача́льника, упа́сшуюся в страна́х Ти́хвинських, устроя́єть храм в честь новоявле́нния іко́ни Єя́, і пресві́тери учрежда́єть, да ви́ну прославля́я Богома́тер, вопію́ть Єй:","Ра́дуйся, Дщи, у́хо приклони́вшая ко гла́су Отця́ Небе́снаго;","ра́дуйся, я́ко прама́тернєє сі́тованіє разруши́ся рождество́м Твої́м.","Ра́дуйся, Неві́сто, Єя́же добро́ти вожделі́ Цар Небе́сний;","ра́дуйся, Цари́це, одесну́ю Царя́ предста́вшая.","Ра́дуйся, ря́сни злати́ми украше́нная і всю сла́ву внутр іму́щая;","ра́дуйся, вводя́щая мно́гих в черто́г Ца́рства Небе́снаго.","Ра́дуйся, я́блоко, єго́же благово́ніє обоня́єть весь мир;","ра́дуйся, кри́не чистоти́, блиста́нієм світя́щийся.","Ра́дуйся, ми́ро благово́нноє, всему́ ми́ру ізлія́нноє;","ра́дуйся, ца́рськую порфи́ру, плоть Творця́ всіх, із ді́вственних крове́й Твої́х істка́вшая.","Ра́дуйся, живи́й запечатле́нний істо́чниче, істочи́вший Во́ду жи́зні;","ра́дуйся, ми́сленний виногра́де, Гроздь Боже́ственний возрасти́вший.","Ра́дуйся, Влади́чице, ми́лостивая о нас пред Бо́гом Засту́пнице."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́ яви́ся іко́на Твоя́, Богома́ти, всю страну́ Ти́хвинськую обтека́ющи і су́щих во тьмі неві́жествія сві́том богові́дінія озаря́ющи, скорб'я́щих ра́достію осіява́ющи, заблужда́ющих же на путь ді́ланія за́повідей Си́на Твоєго́ і Бо́га наставля́ющи, Єму́ же благода́рственні вопіє́м: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дів Гео́ргій на кла́ді дре́ва сідя́щу Жену́, жезл червле́ний в рука́х іму́щу і сві́том неізрече́нним сія́ющу, Є́йже, предстоя́, бесі́доваше ди́вний Святи́тель, позна́ чрез благоуха́ніє благода́ті Тя, Богоро́дицю, чу́вственний зрак приі́мшую і Святи́теля Никола́я предстоя́ща Тебі́, і возопи́ со тре́петом:","Ра́дуйся, до́ме, єго́же созда́ Себі́ для вселе́нія Прему́дрость Бо́жия;","ра́дуйся, Ді́во, Емману́їла роди́вшая.","Ра́дуйся, же́зле Ієссе́ов, от него́же прозябе́ Цвіт Христо́с Бог;","ра́дуйся, Неневі́стная Неві́сто, осіне́нієм Ду́ха заче́ншая Си́на.","Ра́дуйся, сви́тче, в не́мже пе́рстом О́тчим написа́ся Сло́во;","ра́дуйся, кни́го ді́вства запечатле́нная, Іо́сифу на хране́ніє вруче́нная.","Ра́дуйся, клеще́ та́їнственная, угль Божества́ во чре́ві приі́мшая;","ра́дуйся, престо́ле превознесе́нний, на не́мже пло́тію возсі́де Христо́с.","Ра́дуйся, о́блаче ле́гкий, на не́мже приї́де Госпо́дь сла́ви;","ра́дуйся, врата́ затворе́нная, і́миже єди́н Христо́с про́йде.","Ра́дуйся, горо́ несіко́мая, от нея́же краєуго́льний ка́мень отсіче́ся, Христо́с;","ра́дуйся, огнеро́сная пе́ще, неопа́льно приі́мшая огнь Божества́.","Ра́дуйся, Влади́чице, ми́лостивая о нас пред Бо́гом Засту́пнице."]},{"h":"Кондак 6","ps":["Пропові́дник бив ви́димаго Твоєго́ пребива́нія в страні́ Ти́хвинстей і ди́внаго промишле́нія о ней, благочести́вий Гео́ргій явле́ніє Твоє́ і во́лю Твою́ лю́дем возвісти́, є́йже неповину́ющіїся чудеси́ вразумля́ються сла́вити Тя, Влади́чице, і пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ти сві́ту Богопозна́нія явле́нієм іко́ни Твоєя́ ізво́лившая, і світ і́ночеськия жи́зні возжещи́ благоволи́ла єси́, Богома́ти, на мі́сті явле́нія Твоєя́ іко́ни, да і́ноков ли́ци вопію́ть Ті непреста́нно:","Ра́дуйся, непло́днаго ко́рене благопло́дноє прозябе́ніє;","ра́дуйся, от младе́нства Бо́гу посвяще́нная.","Ра́дуйся, во святі́м хра́мі воспита́вшаяся;","ра́дуйся, Бо́гу уневі́стившаяся.","Ра́дуйся, всі́ми доброді́тельми преукраше́нная;","ра́дуйся, світоно́сная пала́то, Влади́ці угото́ванная.","Ра́дуйся, благода́тію Бо́жиєю предочище́нная;","ра́дуйся, от нача́ла віко́во во глави́зну на́шего спасе́нія предизбра́нная.","Ра́дуйся, Неві́сто Архите́ктона небе́снаго, земно́му те́ктону на хране́ніє вруче́нная;","ра́дуйся, ма́лий Назаре́т Свої́м пребива́нієм возвели́чившая.","Ра́дуйся, го́рніх сил похвало́;","ра́дуйся, всіх земноро́дних сла́ва.","Ра́дуйся, Влади́чице, ми́лостивая о нас пред Бо́гом Засту́пнице."]},{"h":"Кондак 7","ps":["Хотя́щим преподо́бним Марти́рію і Кири́ллу во уєдине́нії подвиза́тися і труди́ і по́двиги і́ночеськими Бо́гу угожда́ти, путь в мі́сто вожделіва́ємаго по́двига в столпі́ о́гненнім і гла́се указа́ла єси́. Они́ же позна́вше Тя, я́ко Одиги́трію благу́ю, спутьше́ствующую їм, возопи́ша Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вий істо́чник чуде́с в страні́ сі́верній яви́ся іко́на Твоя́ Ти́хвинськая, Пресвята́я Влади́чице, незави́стно точа́щий ісціле́нія всім притека́ющим с ві́рою: сліпі́ї бо прозира́ють, німі́ї благоглаго́ливи бива́ють, глусі́ї сли́шать, разсла́бленнії возстаю́ть, разли́чними неду́ги одержи́мії здра́ві бива́ють, біснова́тії от уз де́монських свобожда́ються. Ті́мже сла́в'яще Тя, вопіє́м:","Ра́дуйся, я́ко на Тебі́ почи́ благоволе́ніє О́тчеє;","ра́дуйся, Ду́хом Святи́м осіне́нная.","Ра́дуйся, я́ко в Тебі́ воплоти́ся Син Бо́жий, Спас ми́ру;","ра́дуйся, сові́та неізрече́ннаго Таї́ннице.","Ра́дуйся, от А́нгела благові́стіє приі́мшая;","ра́дуйся, а́нгельським, є́же ра́дуйся, весь мир обра́довавшая.","Ра́дуйся, я́ко Госпо́дь с Тобо́ю;","ра́дуйся, я́ко Тобо́ю всі земноро́днії Бо́гу прибли́жишася.","Ра́дуйся, Благослове́нная в жена́х;","ра́дуйся, всім жена́м благослове́ніє дарова́вшая.","Ра́дуйся, Ма́ти, до рождества́ і по рождестві́ преби́вшая Ді́вою;","ра́дуйся, нача́ток че́сти і сла́ви ді́вства.","Ра́дуйся, Влади́чице, ми́лостивая о нас пред Бо́гом Засту́пнице."]},{"h":"Кондак 8","ps":["Стра́нно чу́до явле́нія о́браза Твоєго́, Влади́чице, і несказа́нно, удивля́єть преми́рная і ужаса́єть земна́я, вку́пі же і просвіща́єть благода́тію ро́ждшагося от Тебе́ Христа́ Бо́га на́шего. Стра́нно і заступле́ніє оби́телі от враго́в, хвали́вшихся разори́ти достоя́ніє Твоє́. Сего́ ра́ди вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Вся єси́ во ви́шніх, Влади́чице, но і ни́жніх не оставля́єши, защища́ющи, а́ки стіно́ю і забра́лом, честно́ю іко́ною Твоє́ю оби́тель Твою́. Рекла́ бо єси́, єгда́ бисть наше́ствіє вра́жиє, да во́зьмуть лю́діє іко́ну Твою́ і оби́дуть по стіна́м о́крест, і у́зрять ми́лость Бо́жию. Ті́мже ізба́вленнії Тобо́ю от враг возопи́ша Тебі́:","Ра́дуйся, Ма́ти Творця́ і Го́спода Своєго́;","ра́дуйся, Єя́же ра́ди младе́нець Іоа́нн взигра́ся во чре́ві Єлисаве́ти.","Ра́дуйся, смире́нієм возви́шенная;","ра́дуйся, от всіх родо́в ублажа́ємая.","Ра́дуйся, небе́сним ра́дованіє і земни́м мир рожде́нієм Твої́м дарова́вшая;","ра́дуйся, от А́нгелов славосло́віє, от па́стирей велича́ніє, от волхво́в поклоне́ніє о рожде́нії Твоє́м приі́мшая.","Ра́дуйся, млеко́м пита́вшая го́рняя і до́льняя благода́тію Своє́ю Пита́ющаго;","ра́дуйся, пелена́ми пови́вшая Одіва́ющагося сві́том, я́ко ри́зою.","Ра́дуйся, носи́вшая на руку́ Твоє́ю Нося́щаго весь мир дла́нію;","ра́дуйся, во храм прине́сшая Свяще́ніє хра́ма.","Ра́дуйся, Симео́ном благослове́нная;","ра́дуйся, А́нною проро́чицею возвели́ченная.","Ра́дуйся, Влади́чице, ми́лостивая о нас пред Бо́гом Засту́пнице."]},{"h":"Кондак 9","ps":["Вся́каго єстества́ а́нгельськаго чисті́йши су́щи, Влади́чице, оби́тель, ра́ди прише́ствія Твоєя́ іко́ни созда́нную, от нечистоти́ гріхо́вной близ поги́белі би́вшую, но покая́нієм очи́стившуюся, я́ко о́бщая Моле́бниця о ро́ді христия́нстім, ізба́вила єси́ от враго́в, по подо́бію нечи́стих живо́тних подкопа́ти ю труди́вшихся. Ті́мже вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́я многовіща́нния недоумі́ють воспі́ти по достоя́нію мно́жество чуде́с Твої́х, Влади́чице, і та́йни Твоєго́ строє́нія спасе́нія челові́ков: о́во бо бла́гостію, о́во же посіще́нієм наказа́ній руково́диши люде́й на путь спасе́нія. Зане́ необори́му оби́тель сохрани́вши от враго́во ви́димих, о́гненним очище́нієм благоволи́ла єси́ очи́стити от уязвле́ній врага́ неви́димаго, вразумля́я, я́ко чистота́, воздержа́ніє і моли́тви серде́чния уго́дніє Тебі́ па́че хвали́ єди́них то́чію уст. Ті́мже вопіє́м Ті:","Ра́дуйся, Єги́пет освяти́вшая прише́ствієм Твої́м;","ра́дуйся, Галиле́йськую страну́ просла́вившая пребива́нієм Твої́м.","Ра́дуйся, по всему́ Ієрусали́му іска́вшая Отроча́ Твоє́, Єго́же возлюби́ душа́ Твоя́;","ра́дуйся, в дому́ Отця́ Єго́ обрі́тшая Єго́.","Ра́дуйся, вся глаго́ли о Си́ні Твоє́м слага́вшая в се́рдці Своє́м;","ра́дуйся, в Си́ні Твоє́м пре́жде всіх позна́вшая Бо́га.","Ра́дуйся, Си́ну Твоєму́ послужи́вшая в земні́м житії́ Єго́;","ра́дуйся, страда́нієм Єго́ спострада́вшая.","Ра́дуйся, при Кресті́ Си́на Твоєго́ усиновле́ніє Іоа́нна апо́стола і всіх ві́рующих приі́мшая;","ра́дуйся, Матери́нськи возлюби́вшая іскупле́нних кро́вію Єго́.","Ра́дуйся, пе́рвіє всіх уразумі́вшая та́йну воскресе́нія Си́на Твоєго́;","ра́дуйся, премно́гия ра́дости наслади́вшаяся во вознесе́нії Си́на Твоєго́ на небеса́.","Ра́дуйся, Влади́чице, ми́лостивая о нас пред Бо́гом Засту́пнице."]},{"h":"Кондак 10","ps":["Спасти́ хотя́щи мно́гия лю́ди от обдержа́щих їх скорбе́й і болі́зней і ві́ру їх утверди́ти во всеси́льноє заступле́ніє Твоє́, Влади́чице, во мно́гих граді́х, оби́теліх, ве́сіх правосла́вния страни́ си́лу чудотворе́нія дарова́ла єси́ ізображе́нієм честни́я іко́ни Твоєя́, да ви́дяще явля́ємую Тобо́ю ми́лость, вопію́ть со умиле́нієм Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ і щит била́ єси́, Влади́чице, правосла́вному во́їнству, под зна́менем Твоєя́ іко́ни проти́ву два́десяти язи́к во́їнствовавшему, сохраня́я єго́ от стріл вра́жиїх. Ті́мже бу́ди стіна́ і покро́в от всіх враго́во ви́димих і неви́димих і нам, ко пречестні́й іко́ні Твоє́й с ві́рою і любо́вію припа́дающим і вопію́щим Тебі́:","Ра́дуйся, утіше́ніє ві́рним по вознесе́нії Си́на Твоєго́;","ра́дуйся, учи́тельнице і споспі́шнице Апо́столом.","Ра́дуйся, ізвіще́нієм Твоєго́ к Бо́гу отше́ствія обра́дованная;","ра́дуйся, лик учени́ческий о́блаком к погребе́нію Ті совоку́пльшая.","Ра́дуйся, от землі́ дла́ньми Си́на Твоєго́ восприє́млемая;","ра́дуйся, от всіх а́нгельських чинонача́лій провожда́ємая.","Ра́дуйся, земно́є не́бо ко го́рнему селе́нію возвише́нноє;","ра́дуйся, престо́ле Госпо́день, от землі́ вознесе́нний в Ца́рствіє Небе́сноє.","Ра́дуйся, возду́х освяти́вшая восхожде́нієм Твої́м;","ра́дуйся, чрез Фому́ уві́рившая Твоє́ на не́бо с пло́тію преселе́ніє.","Ра́дуйся, учени́ческому ли́ку обіща́ніє храни́ти єго́ іспо́лньшая;","ра́дуйся, присіще́нієм Твої́м от Си́на Твоєго́ і Бо́га мир тому́ пода́вшая.","Ра́дуйся, Влади́чице, ми́лостивая о нас пред Бо́гом Засту́пнице."]},{"h":"Кондак 11","ps":["Пі́ніє вся́коє побіжда́ється, спростре́тися тща́щеєся ко мно́жеству чуде́с, приснобива́ємих от святи́я Твоєя́ і чудотво́рния іко́ни. Я́коже бо ско́рая Помо́щниця неду́ги ісціля́єши, от бід ізбавля́єши, от муче́нія де́монов свобожда́єши, на вся́ком мі́сті с ві́рою Тя призива́ющих і вопію́щих Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоприє́мную свіщу́ зрим святу́ю іко́ну Твою́, Богома́ти, во страна́х Ти́хвинських благода́тію Твоє́ю возже́нную, всю страну́ просвіща́ющую і мно́гих ко сві́ту своєму́ привлека́ющую на спасе́ніє душ. Ті́мже вопіє́м Ті:","Ра́дуйся, сохраня́ти і спаса́ти всіх призива́ющих Тя обіща́вшая;","ра́дуйся, прославля́ющих Тя прославля́ющая.","Ра́дуйся, к Си́ну Твоєму́ і Бо́гу моли́тви ві́рних принося́щая;","ра́дуйся, і Сама́ непреста́нно у престо́ла Си́на Твоєго́ і Бо́га моля́щаяся о всіх.","Ра́дуйся, благода́ть Твою́ іко́нам Твої́м честни́м дарова́вшая;","ра́дуйся, всю вселе́нную луча́ми Твоєя́ благода́ті озари́вшая.","Ра́дуйся, честні́йшая Херуви́м і сла́внійшая Серафи́м;","ра́дуйся, всея́ тва́рі ви́сшая.","Ра́дуйся, Цари́це Не́ба і землі́;","ра́дуйся, я́ко мно́го мо́жеть моли́тва Твоя́ пред Си́ном Твої́м.","Ра́дуйся, всего́ ро́да христия́нськаго ско́роє заступле́ніє;","ра́дуйся, всіх ві́рних тве́рдоє упова́ніє.","Ра́дуйся, Влади́чице, ми́лостивая о нас пред Бо́гом Засту́пнице."]},{"h":"Кондак 12","ps":["Благода́ті Твоєя́ но́воє зна́меніє да́ти восхоті́в, Петро́ву гра́ду істо́чник чуде́с отве́рзла єси́, Богома́ти, в іко́ні Твоє́й, да ві́рующії вразумля́ються, тружда́ющіїся і скорб'я́щії обріта́ють гото́воє прибі́жище і заступле́ніє і, прославля́ющи Бо́га дарова́вшаго такова́я, вопію́ть Єму́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще чудеса́ Твоя́ і ми́лости ро́ду на́шему явле́нния, уми́льно припа́даєм к пречи́стому о́бразу Твоєму́, Влади́чице, і лобиза́юще, со стра́хом і любо́вію мо́лим Тя: наста́ви нас на путь спасе́нія, да досто́йні бу́дем ви́ну Твоєго́ ми́лостиваго заступле́нія, бу́ди при́сно Засту́пниця і Хода́тайця о нас, вопію́щих Ті:","Ра́дуйся, ві́рних утвержде́ніє і защище́ніє;","ра́дуйся, неві́рних вразумле́ніє і просвіще́ніє.","Ра́дуйся, отча́янних наде́ждо;","ра́дуйся, грі́шних спасе́ніє.","Ра́дуйся, печа́льних утіше́ніє;","ра́дуйся, больни́х ісціле́ніє.","Ра́дуйся, вдов і сиро́т покро́ве;","ра́дуйся, оби́димих прибі́жище.","Ра́дуйся, царе́й укріпле́ніє;","ра́дуйся, святи́телей удобре́ніє.","Ра́дуйся, ді́вствующих похвало́;","ра́дуйся, всіх благочести́вих весе́ліє.","Ра́дуйся, Влади́чице, ми́лостивая о нас пред Бо́гом Засту́пнице."]},{"h":"Кондак 13","ps":["О Всепі́тая Ма́ти, ро́ждшая всіх святи́х Святі́йшеє Сло́во, бу́ди нам покро́в і защище́ніє в жи́зні сей от враго́во ви́димих і неви́димих, от бід і скорбе́й, сохрани́ от іскуше́ній і гріхопаде́ній, і в бу́дущей жи́зні, на суді́ Си́на Твоєго́ і Бо́га на́шего, бу́ди Засту́пниця і Хода́тайця, ізбавля́ющи нас от ві́чнаго осужде́нія, да спасе́ннії Тобо́ю, с ли́ки а́нгельськими вопіє́м Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов ли́ци ликовству́юще слу́жать Тебе́, Влади́чице, і почита́юще Тя, на руку́ Твоє́ю носи́вшую Творця́ ви́димия і неви́димия тва́рі, іко́ну Твою́ с мі́ста на мі́сто прено́сять. Ми же, земноро́днії, див'я́щеся чу́дному явле́нію іко́ни Твоєя́, А́нгели носи́мия, вопіє́м Ті си́це:","Ра́дуйся, всіх Небе́сних Сил ви́сшая;","ра́дуйся, вся а́нгельськия чи́ни превосходя́щая.","Ра́дуйся, честні́йшая Херуви́м;","ра́дуйся, сла́внійшая без сравне́нія Серафи́м.","Ра́дуйся, ра́дованіє А́нгелов;","ра́дуйся, похвале́ніє лико́в небе́сних.","Ра́дуйся, от А́нгелов воспіва́ємая;","ра́дуйся, от Серафи́мов прославля́ємая.","Ра́дуйся, от Арха́нгел покланя́ємая;","ра́дуйся, от во́їнств небе́сних почита́ємая.","Ра́дуйся, в іко́ні Твоє́й от А́нгел чти́мая;","ра́дуйся, во ви́димом о́бразі Твоє́м от неви́димих сил носи́мая.","Ра́дуйся, Влади́чице, ми́лостивая о нас пред Бо́гом Засту́пнице."]},{"h":"Кондак 1","ps":["Взбра́нной Воєво́ді, Влади́чиці на́шей Богоро́диці благода́рственная пі́нія воспису́єм о явле́нії чу́дния Єя́ іко́ни, к не́йже притека́ющії при́сно ізбавля́ються от враг ви́димих і неви́димих. Ти же, Госпоже́ не́ба і землі́, я́ко милосе́рдая Ма́ти, прийми́ ни́ні ма́лоє сіє́ моле́ніє на́ше і неотсту́пну нікогда́же сотвори́ ми́лость Твою́ от нас і заступле́ніє, охраня́ющи от всіх бід і напа́стей нас, зову́щих Ті:","Ра́дуйся, Влади́чице, ми́лостивая о нас пред Бо́гом Засту́пнице."]},{"h":"Молитва перша","ps":["О Пресвята́я Ді́во, Ма́ти Го́спода ви́шніх сил, Небесе́ і землі́ Цари́це, гра́да і страни́ на́шея Всемо́щная Засту́пнице. Прийми́ хвалебноблагода́рственноє пі́ніє сіє́ от нас, недосто́йних раб Твої́х, і вознеси́ моли́тви на́ша ко престо́лу Бо́га Си́на Твоєго́, да ми́лостив бу́деть непра́вдам на́шим і проба́вить бла́гость Свою́ чту́щим всечестно́є і́м'я Твоє́ і с ві́рою і любо́вію покланя́ющимся чудотво́рному о́бразу Твоєму́. Ні́сми бо досто́йні от Него́ поми́ловані би́ти, а́ще не Ти уми́лостивиши Єго́ о нас, Влади́чице, я́ко вся Тебі́ от Него́ возмо́жна суть. Сего́ ра́ди к Тебі́ прибіга́єм, я́ко к несомні́нній і ско́рой Засту́пниці на́шей: усли́ши нас моля́щихся Тебі́, осіни́ нас вседержа́вним покро́вом Твої́м і іспроси́ у Бо́га Си́на Твоєго́ па́стирем на́шим ре́вность і бді́ніє о душа́х, градоправи́телем му́дрость і си́лу, судія́м пра́вду і нелицеприя́тіє, наста́вником ра́зум і смиренному́дріє, супру́гом любо́в і согла́сіє, ча́дом послуша́ніє, оби́димим терпі́ніє, оби́дящим страх Бо́жий, скорб'я́щим благоду́шіє, ра́дующимся воздержа́ніє, всім же нам дух ра́зума і благоче́стія, дух милосе́рдія і кро́тости, дух чистоти́ і пра́вди. Єй, Госпоже́ Пресвята́я, умилосе́рдися на немощни́я лю́ди Твоя́, разсі́янния собери́, заблу́ждшия на путь пра́вий наста́ви, ста́рость поддержи́, ю́ния уцілому́дри, младе́нці воспита́й, і при́зри на всіх нас призрі́нієм ми́лостиваго Твоєго́ заступле́нія, воздви́гни нас із глубини́ гріхо́вния і просвіти́ серде́чния о́чі на́ша к зрі́нію спасе́нія, ми́лостива нам бу́ди зді і та́мо, в страні́ земна́го прише́льствія і на Стра́шнім Суді́ Си́на Твоєго́; преста́вльшіяся же во ві́рі і покая́нії от житія́ сего́ отці́ і бра́тію на́шу во ві́чній жи́зні со а́нгели і со всі́ми святи́ми жи́ти сотвори́. Ти бо єси́, Госпоже́, сла́ва небе́сних і упова́ніє земни́х, Ти по Бо́зі на́ша Наде́жда і Засту́пниця всіх, притека́ющих к Тебі́ с ві́рою. Тебі́ у́бо мо́лимся, і Тебі́, я́ко Всемогу́щей Помо́щнице, са́мі себе́ і друг дру́га і весь живо́т наш предає́м, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["Благодари́м Тя, о Преблага́я і Пречи́стая, Преблагослове́нная Ді́во, Влади́чице, Ма́ти Христа́ Бо́га на́шего, о всіх благодія́ніях Твої́х, я́же показа́ла єси́ ро́ду челові́чеському, найпа́че же нам, христоімени́тим лю́дем Украї́нськаго наро́да, о ни́хже ніже́ са́мий а́нгельський язи́ко к похвале́нію дово́лен бу́деть, я́коже і ни́ні удиви́ла єси́ неізрече́нную Свою́ ми́лость на нас, недосто́йних рабі́х Твої́х, преєсте́ственним самоприше́ствієм пречи́стия Твоєя́ іко́ни, є́юже всю просвіти́ла єси́ Украї́нськую страну́. Ті́мже і ми, грі́шнії, со стра́хом і ра́достію покланя́ющеся, вопіє́м Ті: о Пресвята́я Ді́во, Цари́це і Богоро́дице, спаси́ і поми́луй Святі́йшаго Патріа́рха Моско́вськаго і всея́ Руси́, архієре́ї же і вся лю́ди, і пода́ждь страні́ побі́ди на вся враги́, і сохрани́ вся гра́ди і страни́ христия́нськия, і сей святи́й храм от вся́каго наві́та вра́жия ізба́ви, і всім вся на по́льзу да́руй, ни́ні прише́дшим с ві́рою і моля́щимся рабо́м Твої́м, і покланя́ющимся пресвято́му о́бразу Твоєму́, я́ко благослове́нна єси́ с ро́ждшимся от Тебе́ Си́ном і Бо́гом ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Днесь, я́ко со́лнце пресві́тлоє, / возсія́ нам на возду́сі всечестна́я іко́на Твоя́, Влади́чице, / луча́ми ми́лости мир просвіща́ющи, / ю́же вели́кая Украї́на, / я́ко ні́кий дар Боже́ственний сви́ше благогові́йні восприє́мши, / прославля́єть Тя, Богома́ти, всіх Влади́чицю, / і от Тебе́ ро́ждшагося Христа́ Бо́га на́шего велича́єть ра́достно. / Єму́же моли́ся, о Госпожі́ Цари́це Богоро́дице, / да сохрани́ть вся гра́ди і страни́ христия́нськия / невреди́ми от всіх наві́т вра́жиїх / і спасе́ть ві́рою поклоня́ющихся Єго́ Боже́ственному / і Твоєму́ пречи́стому о́бразу, // Ді́во Неіскусобра́чная."]},{"h":"Кондак, глас 8","ps":["Притеце́м, лю́діє, к Ді́вій Богоро́дице Цари́це, / благодаря́ще Христа́ Бо́га, / і, к Тоя́ чудотво́рній іко́ні уми́льно взира́ющи, припаде́м і возопіє́м Єй: / о Влади́чице Марі́є, / присети́вше страну́ сію́ Твоєго́ честна́го о́браза явле́нієм чуде́сно, / спаса́й в ми́рі і благовре́менстві оте́чество на́ше і вся христия́ни, / наслі́дники показу́ющи Небе́сния жи́зні, / Тебі́ бо ві́рно зове́м: // ра́дуйся, Ді́во, ми́ра спасе́ніє."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Богоізбра́нная Отрокови́це, і чтим о́браз Твой святи́й, і́мже то́чиши ісціле́нія всім с ві́рою притекающим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Казанська»","e":"Akathist to the Theotokos before her icon “Kazan”","secs":[{"h":"Кондак 1","ps":["Ізбра́нной от всіх родо́в Засту́пнице ро́да христия́нськаго, покро́вом Своєя́ бла́гости покрива́ющей страну́ на́шу правосла́вную, благода́рственная пі́нія прино́сим Ті, Богоро́дице, о явле́нії чу́дния Твоєя́ іко́ни. Ти же, я́ко Всеми́лостивая, всіх притека́ющих к Тебі́ Помо́щнице, заступа́й нас во всіх ско́рбіх і ну́ждах, біда́х і напа́стіх, да зове́м Ті:","Ра́дуйся, Засту́пнице усе́рдная ро́да христия́нськаго."]},{"h":"Ікос 1","ps":["А́нгел предста́тель по́слан бисть рещи́ Богоро́дице «Ра́дуйся», єгда́ Бог Сло́во воплоща́шеся во утро́бі Єя́: і ми, грі́шнії, прославля́юще явле́ніє чу́дния Єя́ іко́ни і Боже́ственнаго Младе́нця Спа́са Христа́, со умиле́нієм вопіє́м Благода́тній:","Ра́дуйся, Богоізбра́нная Отрокови́це;","Ра́дуйся, Ма́ти Бо́жия.","Ра́дуйся, Цари́це Небесе́ і землі́;","Ра́дуйся, сві́тлоє Це́ркве Небе́сния і земни́я украше́ніє.","Ра́дуйся, А́нгели чти́мая;","Ра́дуйся, піва́ємая от Серафи́м.","Ра́дуйся, сві́тлоє проро́чеськоє сбитіє́;","Ра́дуйся, апо́столов похвало́.","Ра́дуйся, му́ченичеськоє іспові́даніє;","Ра́дуйся, преподо́бних ві́нче.","Ра́дуйся, пра́ведних весе́ліє;","Ра́дуйся, грі́шних упова́ніє.","Ра́дуйся, Засту́пнице усе́рдная ро́да христия́нськаго."]},{"h":"Кондак 2","ps":["Ви́дящи, Всенепоро́чная, с висоти́ Небе́снаго жили́ща Своєго́, іді́же с Си́ном Твої́м в сла́ві пребива́єши, скорб рабо́в Твої́х в новопросвіще́ннім гра́де, я́ко гні́внаго ра́ди Бо́жия посіще́нія ві́ра Христо́ва поруга́єма бива́єть ага́рянським злові́рієм, благоволи́ла єси́ яви́ти іко́ну Свою́, чудеси́ ю прославля́ющи, да утвержда́ємії зна́меньми Твоєя́ благода́ті, христолюби́вії лю́діє ві́рно вопію́ть Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Разумі́ніє трикра́тнаго явле́нія Богома́тере му́драя отрокови́ця і́щущи, тече́ ко власте́м, пові́дающи їм ди́вноє явле́ніє і гро́зноє преще́ніє: ми же див'я́щеся сви́ше да́нному отрокови́це вразумле́нію, благогові́йно вопіє́м к Преблагослове́нній:","Ра́дуйся, устна́ми чи́стими хвалу́ Бо́гові соверша́ющая;","Ра́дуйся, та́йни благода́ті Бо́жия ві́рним открива́ющая.","Ра́дуйся, неві́рних сумни́тельноє сли́шаніє.","Ра́дуйся, ві́рних ізві́стная похвало́;","Ра́дуйся, мо́лніє, неві́рних устраша́ющая.","Ра́дуйся, сла́вою чуде́с Твої́х ві́рних ра́зум озаря́ющая;","Ра́дуйся, ага́рянськаго злові́рія обличе́ніє.","Ра́дуйся, горди́ні їх низложе́ніє;","Ра́дуйся, ві́ри христия́нськия утвержде́ніє.","Ра́дуйся, почита́нія святи́х іко́н освяще́ніє;","Ра́дуйся, скорб на́шу в ра́дость претворя́ющая.","Ра́дуйся, несумні́нною наде́ждою нас увеселя́ющая.","Ра́дуйся, Засту́пнице усе́рдная ро́да христия́нськаго."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго благода́тію Богома́тере умудри́ і укріпи́ отрокови́цю к іска́нію многоці́ннаго Бо́жия да́ра, і та, с ві́рою дерза́ющи о Го́споді, приступи́ к труду́ і, скри́тоє в землі́ обрі́тши сокро́вище святи́я іко́ни Богома́тері, ра́достно возопи́ к Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́ющи благоутро́бноє промишле́ніє о новопросвіще́нних лю́діх гра́да Каза́ни, от пречестни́я Твоєя́ іко́ни то́ки чуде́с істочи́ла єси́, Влади́чице, сліпи́м тіле́снима очи́ма зрі́ніє подава́ющи, омраче́нних же душе́вно сві́том богопозна́нія і благоче́стія озаря́ющи, де́вствующим под осіне́нієм Твоєя́ іко́ни приста́нище небу́рноє да́рующи. Сего́ ра́ди зове́м Ті:","Ра́дуйся, явле́нієм іко́ни Твоєя́ тьму лю́тих обстоя́ній отгоня́ющая;","Ра́дуйся, луча́ми чуде́с всіх просвіща́ющая.","Ра́дуйся, сліпи́х прозрі́ніє;","Ра́дуйся, омраче́нних сми́слом просвіще́ніє.","Ра́дуйся, сла́во Правосла́вія;","Ра́дуйся, ти́хоє приста́нище і́щущих спасе́нія.","Ра́дуйся, Ма́ти цілому́дрія;","Ра́дуйся, покро́ве і огражде́ніє ді́вства.","Ра́дуйся, Є́юже ликовству́єть все мно́жество ві́рних;","Ра́дуйся, Єя́же ра́ди рида́єть де́монськоє по́лчище.","Ра́дуйся, всіх христия́н вожделі́нная Помо́щнице;","Ра́дуйся, всіх скорб'я́щих Ра́досте.","Ра́дуйся, Засту́пнице усе́рдная ро́да христия́нськаго."]},{"h":"Кондак 4","ps":["Бу́рю см'яте́ній і крамо́ли врага́ми воздви́гнутую в страні́ на́шей утоли́ти тща́щся блаже́нний Ермоге́н, списа́тель чуде́с Твоєя́, Богома́ти, іко́ни, сле́зно пред не́ю моля́шеся і, ви́дів, я́ко во́їнству правосла́вному в щит і побі́дноє зна́меніє Твоя́ іко́на дарова́ся, ві́рою укріпля́ємий до конця́ живота́ своєго́, вопія́ше Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше правосла́внії во́їни открове́нную Преподо́бним Се́ргиєм святи́телю Арсе́нію та́йну, я́ко предста́тельством Богома́тере суд об Оте́честві на́шем преложе́н на ми́лость, іко́ну Богома́терню, я́ко зна́м'я побі́дноє, приі́мше, ісхити́ша ма́тер градо́в ру́ських із рук супоста́ть і возопи́ша Засту́пнице христия́н:","Ра́дуйся, Ма́ти Бо́га Ви́шняго;","Ра́дуйся, я́ко за всіх мо́лиши Си́на Твоєго́, Христа́ Бо́га на́шего.","Ра́дуйся, я́ко всім твори́ши спасти́ся в держа́вний Твой покро́в прибега́ющим;","Ра́дуйся, Засту́пнице всіх су́щих в ско́рбіх і болі́зніх.","Ра́дуйся, всім моля́щимся сокруше́нним се́рдцем пред пречи́стим Твої́м о́бразом поле́зная да́рующая;","Ра́дуйся, ізбавле́ніє зол всім, невозвра́тно наде́жду іму́щим на Тя.","Ра́дуйся, ти́хоє і до́броє приста́нище;","Ра́дуйся, ско́рая Помо́щнице.","Ра́дуйся, гото́вий і те́плий покро́ве спасе́нія;","Ра́дуйся, істоча́ющая нам неоску́дния ми́лості.","Ра́дуйся, предваря́ющая на по́мощ;","Ра́дуйся, ізбавля́ющая от всіх бід.","Ра́дуйся, Засту́пнице усе́рдная ро́да христия́нськаго."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́ яви́ся Твоя́, Богома́ти, іко́на, всю страну́ Украї́нськую обтека́ющая, луча́ми чуде́с Твої́х осіява́ющая всіх блужда́ющих по мо́рю стра́стнаго житія́, мрак печа́лей і мглу вся́ких неду́г і скорбе́й прогоня́ющая і наставля́ющая на путь спасе́нія с ві́рою к Тебі́ притека́ющих і вопію́щих к Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дів цар Петр, я́ко от святи́я іко́ни Богома́терни благода́тію Бо́жиєю содіва́ються мно́гія чудеса́, приє́млеть ю в путеводи́тельницю во́їнству своєму́ і в день бра́ні на све́єв в щит і покро́в, і побіди́в до конця́ врага́ с по́мощію Богома́тере, тім ка́мень соверше́нний во основа́ніє но́ваго ца́рствующего гра́да положи́, іко́ну же Твою́ чу́дную, я́ко освяще́ніє, я́ко щит і огражде́ніє, в се́рдці гра́да поста́ви. Сего́ ра́ди вопіє́м Пречи́стій:","Ра́дуйся, жили́ще і до́ме Христа́ Бо́га на́шего;","Ра́дуйся, вмісти́лище неізре́ченния Єго́ сла́ви.","Ра́дуйся, гра́де одушевле́нний, при́сно ца́рствующий;","Ра́дуйся, пала́то преукраше́нная.","Ра́дуйся, Ра́досте градо́в і ве́сей;","Ра́дуйся, непобіди́моє христия́н в біда́х храни́лище і предгра́діє.","Ра́дуйся, Це́ркве Правосла́вния похвало́;","Ра́дуйся, Ру́ськой землі́ утвержде́ніє.","Ра́дуйся, христолюби́ваго во́їнства Помо́щнице;","Ра́дуйся, враго́в одолі́ніє.","Ра́дуйся, от бід ізбавле́ніє;","Ра́дуйся, Ма́терніми Твої́ми щедро́тами всіх посіща́ющая.","Ра́дуйся, Засту́пнице усе́рдная ро́да христия́нськаго."]},{"h":"Кондак 6","ps":["Предстоя́ще пред пречи́стим Твої́м о́бразом архієре́єв сосло́вії і всі лю́діє, мона́си і мирсті́ї, пропові́дують, Госпоже́ Богороди́тельнице, вели́кия Твоя́ ми́лості, я́ко гра́ди огражда́єши, оби́телі покрива́єши, ві́си защища́єши, і, ві́дуще Тя воі́стину Помо́щницю си́льну і непобіди́му, со слеза́ми прино́сять Ті моли́тви, да простре́ши к Си́ну Твоєму́ Богоно́сния ру́ки за лю́ди Твоя́, во є́же ізба́вити нас от всіх бід і напа́стей, да благода́рні вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́вши просвіще́ніє і́стинноє і отгна́вши дре́вле лесть ага́рянськую во новопросвіще́нній страні́ Каза́нськой, ни́ні во всіх гра́діх украї́нських сві́тиши сві́том чуде́с і ми́лостей: притека́ющий бо с ві́рою ко Твоє́й іко́ні цільбоно́сній скорбе́й ізбавле́ніє, неду́гов ісціле́ніє і ра́дости вся́кия ісполне́нія приє́млють, вопію́ще Тебі́ усе́рдно:","Ра́дуйся, неістощи́мий істо́чниче святи́ні;","Ра́дуйся, многотеку́щая ріко́ Боже́ственная благода́ті.","Ра́дуйся, грі́шних с Бо́гом примире́ніє;","Ра́дуйся, гріхо́в на́ших очище́ніє.","Ра́дуйся, благоче́стія Наста́внице;","Ра́дуйся, в до́брих ді́ліх утвержде́ніє і по́моще.","Ра́дуйся, до́брия обі́ти приє́млющая;","Ра́дуйся, благи́м намі́ренієм спосо́бствующая.","Ра́дуйся, зли́я начина́нія разруша́ющая;","Ра́дуйся, вра́жия ко́зні расторга́ющая.","Ра́дуйся, ско́рая челові́ком Помо́щнице;","Ра́дуйся, ми́лость сугу́бо нам подаю́щая.","Ра́дуйся, Засту́пнице усе́рдная ро́да христия́нськаго."]},{"h":"Кондак 7","ps":["Хотя́щу наро́ду правосла́вному іспові́дати ми́лости Преблагослове́нния Цари́ці Не́ба і землі́ і по си́лі благода́рственная принести́ о ізбавле́нії єго́ от наше́ствія іноплеме́нних, ди́вному хра́му, созда́нному в честь пречу́дния іко́ни, побі́дная в дар принесе́, да всі па́м'ятующе ми́лость Богома́тере, спа́сшия град сей і страну́, ви́ну воспіва́ють Бо́гу благода́рними усти́: Аллилу́я."]},{"h":"Ікос 7","ps":["Сто́льному гра́ду Украї́ни свята́я іко́на Твоя́, Богома́ти, воі́стину яви́ся блага́я Одиги́трія, я́коже дре́вле Царегра́ду: к Тебі́ бо прибіга́ють лю́діє, по́мощі Твоєя́ на нача́ло путі́ і діл свої́х прося́ще і благода́рственная принося́ще моле́нія пред пречи́стою іко́ною Твоє́ю за ізбавле́ніє от скорбе́й і напа́стей, Тебе́ Помо́щницю і Засту́пницю крі́пкую ві́дають. Ті́мже благода́рственно вопіє́м Ті:","Ра́дуйся, Украї́нськия страни́ покро́ве;","Ра́дуйся, Правосла́вія в ней огражде́ніє і утвержде́ніє.","Ра́дуйся, несокруши́мий щі́те во́їнов на́ших;","Ра́дуйся, броне́ їх неуязви́мая.","Ра́дуйся, ко́зні враго́в облича́ющая;","Ра́дуйся, я́ко паучи́ну їх растерза́ющая.","Ра́дуйся, нече́стія обличе́ніє;","Ра́дуйся, крамо́ли разруше́ніє.","Ра́дуйся, ю́них от заблужде́ній ісправле́ніє;","Ра́дуйся, ста́рцев утіше́ніє.","Ра́дуйся, душевре́дних уче́ній низложе́ніє;","Ра́дуйся, душеполе́зних зна́ній дарова́ніє.","Ра́дуйся, Засту́пнице усе́рдная ро́да христия́нськаго."]},{"h":"Кондак 8","ps":["Стра́нно і сумни́тельно неве́рующим слу́шати, ка́ко от іко́ни Твоєя́ то́ки благода́ті істека́ють, воня́ живо́тная благоуха́єть: ми же, ві́рующе сло́ву, рече́нному Тобо́й, Влади́чице, к первонапи́санній іко́ні: «С тобо́й Моя́ благода́ть і си́ла», упова́єм, я́ко і с се́ю іко́ною благода́ть Твоя́ ви́ну: ті́мже благогові́йно предстоя́ще лобиза́єм ю, поклоня́ємся єй, я́ко Тебі́ Самі́й су́щей, честь бо іко́ни на первообра́зноє восхо́дить, і Твоя́ благода́ть се́ю іко́ною зна́менія і чудеса́ содіва́єть всім с ві́рою притека́ющим к Тебі́ і вопію́щим Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Вся би́вши горі́, к Небе́сним взя́та, і земни́х не оставля́єши, Богома́ти, свяще́нним Твої́м предста́тельством: і́маши бо ма́тернєє дерзнове́ніє ко Христу́ Бо́гу на́шему. Ті́мже утверди́ в ми́рі глубо́ці правосла́вних житіє́ і вся поле́зная всегда́ да́руй рабо́м Твої́м, да велича́юще воспіва́єм Ті:","Ра́дуйся, Невмісти́маго вмісти́лище;","Ра́дуйся, осіне́нная си́лою Ви́шняго.","Ра́дуйся, прозя́бшая Клас Небе́сний;","Ра́дуйся, мир весь душепа́губнаго гла́да ізба́вльшая.","Ра́дуйся, ви́ну хода́тайствующая за род наш;","Ра́дуйся, я́ко мно́го мо́жеть моли́тва Твоя́ пред Си́ном Твої́м і Бо́гом.","Ра́дуйся, всіх нас при Кресті́ Си́на Твоєго́ усинови́вшая;","Ра́дуйся, всегда́ Ма́тернюю любо́в к нам явля́ющая.","Ра́дуйся, Хода́тайце ві́чних благ;","Ра́дуйся, і во вре́менній жи́зні поле́зная нам подаю́щая.","Ра́дуйся, ізві́стноє прибі́жище на́ше во всіх ско́рбних обстоя́ніїх;","Ра́дуйся, несомні́нноє утіше́ніє в печа́ліх.","Ра́дуйся, Засту́пнице усе́рдная ро́да христия́нськаго."]},{"h":"Кондак 9","ps":["Вся́каго єстества́ а́нгельськаго преви́шшая яви́лася єси́, Пресвята́я Ді́во: Бо́га бо зачала́ єси́ пло́тію, Невмісти́маго всі́ми вмісти́ла єси́ во утро́бі Твоє́й, на рука́х носи́ла єси́ Нося́щаго весь мир дла́нію: ті́мже, я́ко Честні́йшую Херуви́м і Сла́внійшую без сравне́нія Серафи́м велича́юще Тя, вопіє́м о Тебі́ Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́я многовіща́нния, я́ко ри́би безгла́сния, ви́дим о Тебі́, Богоро́дице: недоумі́єть бо всяк язи́к благохвали́ти Тя по достоя́нію, ізуміва́єть ум пі́ти Тя, Богоро́дице; оба́че Блага́я су́щи, прийми́ і от нас арха́нгельський глас, Тебі́ вопію́щих:","Ра́дуйся, Благода́тная;","Ра́дуйся, я́ко Госпо́дь с Тобо́ю.","Ра́дуйся, Благослове́нная в жена́х;","Ра́дуйся, обрі́тшая благода́ть у Бо́га.","Ра́дуйся, роди́вшая Спаси́теля ми́ру;","Ра́дуйся, Ма́ти Си́на Бо́жия.","Ра́дуйся, Роди́тельнице Ві́чнаго Царя́;","Ра́дуйся, ізрасти́вшая нам плод живота́.","Ра́дуйся, освяще́нная Ду́хом Святи́м;","Ра́дуйся, осіне́нная си́лою Всеви́шняго.","Ра́дуйся, ві́рная Рабо́ Госпо́дня;","Ра́дуйся, я́ко Тя блажа́ть всі ро́ди.","Ра́дуйся, Засту́пнице усе́рдная ро́да христия́нськаго."]},{"h":"Кондак 10","ps":["Спасти́ хотя́щи мно́гія от находя́щих зол, скорбе́й і болі́зней, чу́дную іко́ну Твою́, Богома́ти, дарова́ла єси́, єя́же ра́ди сліпі́ї прозира́ють, хромі́ї хо́дять, разсла́бленнії возстаю́ть, бісну́ющіїся ісціля́ються, землі́ плодоно́сіє подає́ться, лю́діє от смертоно́сния я́зви ізбавля́ються, гра́ди і до́ми от огня́ спаса́ються: ті́мже прославля́юще Бо́га, даю́щаго нам такови́я ми́лости, вопіє́м Єму́ усе́рдно: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́, Богоро́дице, страні́ Украї́нській, гра́дом огражде́ніє і сла́ва, правосла́вному во́їнству на враги́ укріпле́ніє. Ті́мже, благодаря́ще Тя, вопіє́м:","Ра́дуйся, прославля́ющих Тя прославля́ющая;","Ра́дуйся, не чту́щих Тя посрамля́ющая.","Ра́дуйся, враго́в устраше́ніє;","Ра́дуйся, от наше́ствія іноплеме́нних ізбавле́ніє.","Ра́дуйся, во́їнов крі́посте;","Ра́дуйся, в дні бра́ні забра́ло і огражде́ніє.","Ра́дуйся, в дні ми́ра живоно́сний са́де, увеселя́ющий сердца́ ві́рних;","Ра́дуйся, ору́жіє, єго́же трепе́щуть де́мони.","Ра́дуйся, спаси́тельний єле́й, умаща́ющий гріхо́вния ра́ни ка́ющихся;","Ра́дуйся, те́плоє на́ше упова́ніє.","Ра́дуйся, несумні́нная на́ша Наде́ждо;","Ра́дуйся, ти́хоє і до́броє приста́нище.","Ра́дуйся, Засту́пнице усе́рдная ро́да христия́нськаго."]},{"h":"Кондак 11","ps":["Пі́ніє хвале́бноє і благода́рственноє прино́сять Тебе́, Влади́чице, припа́дающе ко іко́ні Твоє́й і любе́зно лобиза́юще ю, дів ли́ци, под держа́вним покро́вом Твої́м ти́хоє і ми́рноє і́ночеськоє житіє́ провожда́ющії, і возложи́вше на Тя все упова́ніє, ра́достно вопію́ть Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Я́ко світоприє́мную свіщу́, зрим Твою́ честну́ю іко́ну, Пресвята́я Влади́чице: та бо невеще́ственний огнь благода́ті Твоєя́ восприє́мши, і в подо́біїх єя́ но́ви возжига́єть світи́льники, прича́стни тоя́жде си́ли благода́тния, і озаря́єть чудеси́, наставля́ющи на путь спасе́нія всіх вопію́щих Ті си́це:","Ра́дуйся, Неві́сто Неневі́стная;","Ра́дуйся, Богоізбра́нная Отрокови́це, Ма́ти Ді́во.","Ра́дуйся, до́брая Наста́внице непоро́чнаго ді́вства;","Ра́дуйся, Храни́тельнице ревну́ющих о чистоті́.","Ра́дуйся, жен похвало́;","Ра́дуйся, дів велича́ніє.","Ра́дуйся, вдов заступле́ніє;","Ра́дуйся, сиро́т призрі́ніє.","Ра́дуйся, ни́щих Пита́тельнице;","Ра́дуйся, наги́х одія́ніє.","Ра́дуйся, печа́льних утіше́ніє;","Ра́дуйся, скорб'я́щих весе́ліє.","Ра́дуйся, Засту́пнице усе́рдная ро́да христия́нськаго."]},{"h":"Кондак 12","ps":["Благода́ть да́ти восхоті́вши почита́ющим Тя с любо́вію, Богороди́тельнице, прису́щую Ті си́лу благода́тную оста́вила єси́ во святи́х Твої́х іко́нах, і́бо Боже́ственная благода́ть, спребива́ющи тім (іко́нам), зна́менія і чудеса́ ви́ну содіва́єть і душе́вних і тіле́сних неду́г ісціле́ніє всім с ві́рою приходя́щим подає́ть Твої́ми Богома́терніми непреста́нними к Бо́гу моли́твами о вопію́щих Єму́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Твоя́ чудеса́, би́вшая в дре́вняя і настоя́щая времена́, хва́лим Тя, я́ко Живоно́сний Істо́чник благода́ті, я́ко неістощи́мую ре́ку чуде́с, я́ко бе́здну ми́лості і щедро́т, і все упова́ніє по Бо́зі возлага́юще на Тя і в сей і в бу́дущей жи́зні, прославля́юще Тя, вопіє́м:","Ра́дуйся, христия́н непости́дноє упова́ніє;","Ра́дуйся, ві́рних спаси́тельноє прибі́жище.","Ра́дуйся, ненаде́жних наді́яніє;","Ра́дуйся, отча́янних спасе́ніє.","Ра́дуйся, ба́не, омива́ющая со́вість;","Ра́дуйся, росо́, оживля́ющая ду́ші.","Ра́дуйся, болі́зней врачевство́ ско́роє і безме́здноє;","Ра́дуйся, от всіх бід би́строє ізбавле́ніє.","Ра́дуйся, Уті́шительнице во вся́кой ско́рби;","Ра́дуйся, із глубини́ поги́белі спаса́ющая.","Ра́дуйся, отра́до в день сме́рті;","Ра́дуйся, єди́ная Наде́ждо і по сме́рті.","Ра́дуйся, Засту́пнице усе́рдная ро́да христия́нськаго."]},{"h":"Кондак 13","ps":["О Всепі́тая Ма́ти, ро́ждшая всіх святи́х Святі́йшеє Сло́во, прийми́ ни́ні ма́лоє сіє́ моле́ніє і, вели́чія ра́ди бла́гости Твоєя́ і бе́здни щедро́т Твої́х, не пом'яни́ мно́жества гріхо́в на́ших, но іспо́лни во благи́х проше́нія на́ша, подава́ющи ті́лу здра́віє, душі́ спасе́ніє, ізбавля́ющи от вся́кия ну́жди і печа́лі і Ца́рствія Небе́снаго наслі́дники сотворя́ющи всіх ві́рно вопію́щих Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел предста́тель по́слан бисть рещи́ Богоро́дице «Ра́дуйся», єгда́ Бог Сло́во воплоща́шеся во утро́бі Єя́: і ми, грі́шнії, прославля́юще явле́ніє чу́дния Єя́ іко́ни і Боже́ственнаго Младе́нця Спа́са Христа́, со умиле́нієм вопіє́м Благода́тній:","Ра́дуйся, Богоізбра́нная Отрокови́це;","Ра́дуйся, Ма́ти Бо́жия.","Ра́дуйся, Цари́це Небесе́ і землі́;","Ра́дуйся, сві́тлоє Це́ркве Небе́сния і земни́я украше́ніє.","Ра́дуйся, А́нгели чти́мая;","Ра́дуйся, піва́ємая от Серафи́м.","Ра́дуйся, сві́тлоє проро́чеськоє сбитіє́;","Ра́дуйся, апо́столов похвало́.","Ра́дуйся, му́ченичеськоє іспові́даніє;","Ра́дуйся, преподо́бних ві́нче.","Ра́дуйся, пра́ведних весе́ліє;","Ра́дуйся, грі́шних упова́ніє.","Ра́дуйся, Засту́пнице усе́рдная ро́да христия́нськаго."]},{"h":"Кондак 1","ps":["Ізбра́нной от всіх родо́в Засту́пнице ро́да христия́нськаго, покро́вом Своєя́ бла́гости покрива́ющей страну́ на́шу правосла́вную, благода́рственная пі́нія прино́сим Ті, Богоро́дице, о явле́нії чу́дния Твоєя́ іко́ни. Ти же, я́ко Всеми́лостивая, всіх притека́ющих к Тебі́ Помо́щнице, заступа́й нас во всіх ско́рбіх і ну́ждах, біда́х і напа́стіх, да зове́м Ті:","Ра́дуйся, Засту́пнице усе́рдная ро́да христия́нськаго."]},{"h":"Молитва","ps":["О Пресвята́я Госпоже́ Влади́чице Богоро́дице! Со стра́хом, ві́рою і любо́вію припа́дающе пред честно́ю іко́ною Твоє́ю, мо́лим Тя: не отврати́ лиця́ Твоєго́ от прибіга́ющих к Тебі́, умоли́ милосе́рдая Ма́ти, Си́на Твоєго́ і Бо́га на́шего, Го́спода Ісу́са Христа́, да сохрани́ть ми́рну страну́ на́шу, Це́рков Свою́ Святу́ю да нези́блему соблюде́ть от неві́рія, єресе́й і раско́ла. Не і́мами бо іни́я по́мощі, не і́мами іни́я наде́жди, ра́зві Тебе́, Пречи́стая Ді́во: Ти єси́ Всеси́льная христия́н Помо́щниця і Засту́пниця. Ізба́ви всіх с ві́рою Тебі́ моля́щихся от паде́ній гріхо́вних, от наві́та злих челові́к, от вся́ких іскуше́ній, скорбе́й, бід і от напра́сния сме́рті: да́руй нам дух сокруше́нія, смире́ніє сердца́, чистоту́ помишле́ній, ісправле́ніє гріхо́вния жи́зні і оставле́ніє прегріше́ній, да всі благода́рні воспіва́юще вели́чія Твоя́, сподо́бимся Небе́снаго Ца́рствія і та́мо со всі́ми святи́ми просла́вим Пречестно́є і Великолі́поє І́м'я Отця́ і Си́на і Свята́го Ду́ха. Амі́нь."]},{"h":"Молитва","ps":["О, Пресвята́я Влади́чице Богоро́дице, Цари́це Небесі́ і землі́, ви́шшая а́нгел і арха́нгел і всея́ тва́рі честні́йшая, чи́стая Ді́во Марі́є, ми́ру блага́я Помо́щнице, і всім лю́дем утвержде́ніє, і во вся́ких ну́ждах ізбавле́ніє! При́зри і ни́ні, Госпоже́ Всеми́лостивая, на раби́ Твоя́, Тебі́ умиле́нною душе́ю і сокруше́нним се́рдцем моля́щіяся, со слеза́ми к Тебі́ припа́дающия і покланя́ющіяся пречи́стому і цільбоно́сному о́бразу Твоєму́, і по́мощі і заступле́нія Твоєго́ прося́щия. О, Всеми́лостивая і Премилосе́рдая Ді́во Богоро́дице Чи́стая! Воззри́, Госпоже́, на лю́ди Твоя́: ми бо грі́шнії не і́мами іни́я по́мощі, ра́зві Тебе́ і от Тебе́ ро́ждшагося Христа́ Бо́га на́шего. Ти єси́ засту́пниця і предста́тельниця на́ша. Ти єси́ оби́димих защи́щеніє, скорб'я́щим ра́дованіє, си́рим прибі́жище, вдо́вам храни́тельниця, ді́вам сла́ва, пла́чущим весе́ліє, больни́м посіще́ніє, немощни́м ісціле́ніє, грі́шним спасе́ніє, Сего́ ра́ди, о Богома́ти, к Тебі́ прибіга́єм, і на Твой Пречи́стий о́браз с Предві́чним на руку́ Твоє́ю держи́мим Младе́нцем, Го́сподем на́шим Ісу́сом Христо́м взира́юще, умиле́нноє пі́ніє Тебі́ прино́сим і вопіє́м: поми́луй нас, Ма́ти Бо́жия, і проше́ніє на́ше іспо́лни, вся бо суть возмо́жна хода́тайству Твоєму́: я́ко Тебі́ сла́ва подоба́єть ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Засту́пнице усе́рдная, / Ма́ти Го́спода Ви́шняго, / за всіх мо́лиши Си́на Твоєго́ Христа́ Бо́га на́шего, / і всім твори́ши спасти́ся, / в держа́вний Твой покро́в прибега́ющим. / Всіх нас заступи́, о Госпожі́ Цари́це і Влади́чице, / і́же в напа́стіх і в ско́рбіх, і в болі́зніх обремене́нних гріхи́ мно́гими, / предстоя́щих і моля́щихся Тебі́ умиле́нною душе́ю / і сокруше́нним се́рдцем, / пред пречи́стим Твої́м о́бразом со слеза́ми, / і невозвра́тно наде́жду іму́щих на Тя, / ізбавле́нія всіх зол, / всім поле́зная да́руй, / і вся спаси́, Богоро́дице Ді́во: // Ти бо єси́ Боже́ственний покро́в рабо́м Твої́м."]},{"h":"Кондак, глас 8","ps":["Притеце́м, лю́діє, к ти́хому сему́ і до́брому приста́нищу, / ско́рой Помо́щнице, гото́вому і те́плому спасе́нію, покро́ву Ді́ви, / ускори́м на моли́тву і потщі́мся на покая́ніє: / істоча́єть бо нам неоску́дния ми́лості Пречи́стая Богоро́диця, / предваря́єть на по́мощ, і ізбавля́єть от вели́ких бід і зол // благонра́вния і богобоя́щіяся раби́ Своя́."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Богоізбра́нная Отрокови́це, і чтим о́браз Твой святи́й, і́мже то́чиши ісціле́нія всім с ві́рою притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Почаївська»","e":"Akathist to the Theotokos before her icon “Pochaiv”","secs":[{"h":"Кондак 1","ps":["Взбра́нной Воєво́ді родо́в христия́нських і страни́ на́шея ізві́стній Ізба́вительнице хвале́бния пі́сні принесе́м, ві́рнії, на святі́й горі́ Єя́ собра́вшеся; Ти же, я́ко іму́щая милосе́рдіє неізрече́нноє, о Влади́чице Богоро́дице, моле́нія на́шего, пред чудотво́рним Твої́м о́бразом возноси́маго, не отве́ржи, да в умиле́нії серде́ць зове́м Ті:","Ра́дуйся, похвало́ Поча́євськая і всего́ ми́ра наде́ждо і утіше́ніє."]},{"h":"Ікос 1","ps":["Арха́нгел Гавриї́л пе́рвіє «Ра́дуйся!» тебі́ приноша́ше, Влади́чице, єгда́ зача́тіє Си́на Бо́жия благовіствова́ше, по пресла́внім же Успе́нії Твоє́м вся Небе́сния си́ли ту́южде хвалу́ на Небесі́ Тебі́ непреста́нно прино́сять; ка́ко у́бо ми, грі́шнії, своя́ гла́си с гла́си Безпло́тних совокупи́ти де́рзнем? Оба́че, милосе́рдіє Твоє́ ко всім ка́ющимся помина́юще, устні́ на́ша со стра́хом і любо́вію отверза́єм, глаго́люще си́це:","Ра́дуйся, ми́лости бе́здно;","ра́дуйся, любве́ неістощи́моє мо́ре.","Ра́дуйся, ро́да христия́нськаго блага́я Предста́тельнице;","ра́дуйся, оби́телі Поча́євския стіно́ неруши́мая.","Ра́дуйся, правосла́вния лю́ди на го́ру Поча́євськую у́зами любве́ привлека́ющая;","ра́дуйся, вся́кую печа́ль от душ їх отгоня́ющая.","Ра́дуйся, Єя́же чудотво́рний о́браз, я́ко звізда́, от гори́ Поча́євськия нас путево́дствуєть;","ра́дуйся, Є́йже возноси́мия моли́тви стра́стния прило́ги вско́рі отража́ють.","Ра́дуйся, явле́нієм Свої́м на горі́ сей лю́ди уте́шившая;","ра́дуйся, слід стопи́ Твоєя́ на ней нам оста́вившая.","Ра́дуйся, ві́рних при́сноє дерзнове́ніє;","ра́дуйся, сумня́щихся до́броє утвержде́ніє.","Ра́дуйся, похвало́ Поча́євськая і всего́ ми́ра наде́ждо і утіше́ніє."]},{"h":"Кондак 2","ps":["Ви́дівше пусти́нници поча́євстії і просте́ць Іоа́нн Боси́й Пресвяту́ю Богоро́дицю на скалі́ во о́гненном сто́лпе яви́вшуюся, слід стопи́ Єя́ облобиза́ху і водо́ю, зді от ка́мені істе́кшею, окропля́яся, вопія́ху Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум недоразуміва́ємий о явле́нії Твоє́м, Влади́чице, і́щуще, в сицево́м упова́нії утвержда́ється, я́ко пе́рвіє от ага́рян, по́сліжде от єретико́в опло́т Правосла́вія на горі́ Поча́євстій утверди́ти благоволи́ла єси́, сего́ ра́ди в Твой святи́й храм приходя́ще, те́плою ві́рою сердця́ на́ша ісполня́єм, глаго́лющи:","Ра́дуйся, і́стинния ві́ри утвержде́ніє;","ра́дуйся, злові́рія я́вноє обличе́ніє.","Ра́дуйся, дре́вле в неопали́мій купині́ сина́йстій ізвести́вшаяся;","ра́дуйся, христия́ном в столпі́ о́гненном зді яви́вшаяся.","Ра́дуйся, я́ко в пещі́ горя́щей, росо́ю спасе́ннії, Авраа́мстії о́троци Тя предвозвісти́ша;","ра́дуйся, я́ко водо́ю от слі́да стопи́ Твоєя́ ісціле́ннії благода́ть Твою́ пропові́даша.","Ра́дуйся, зе́млю на́шу, дре́вле от ага́рян разоре́нную, явле́нієм Твої́м тогда́ уте́шившая;","ра́дуйся, і ни́ні мно́гими зна́меньми моля́щіяся зді ободря́ющая.","Ра́дуйся, ка́ющихся ско́роє усли́шаніє;","ра́дуйся, подвиза́ющимся по́мощ і прибі́жище.","Ра́дуйся, і неві́дущих вразумле́ніє;","ра́дуйся, і малоду́шних укріпле́ніє.","Ра́дуйся, похвало́ Поча́євськая і всего́ ми́ра наде́ждо і утіше́ніє."]},{"h":"Кондак 3","ps":["Си́лу сугу́бия благода́ті яви́ла єси́, Влади́чице, на горі́ Поча́євстій, єгда́ мі́сто явле́нія Твоєго́ по тріє́х стах лі́тіх чудотво́рною іко́ною Своє́ю обогати́ла єси́, ю́же руко́ю святи́теля Неофи́та Е́ллина, із Москви́ гряду́щаго, пе́рвіє боя́рине А́нні дарова́ла єси́, пото́м же от нея́ во оби́тель Поча́євськую прия́ла єси́, ра́дующимся лю́дем і пою́щим Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи в дому́ своє́м іко́ну Твою́, Влади́чице, боя́риня А́нна і ісціле́ніє от нея́ слепорожде́нному бра́ту своєму́ Фили́ппу би́вшеє уві́дівши, а́біє ду́хом ре́вности о сла́ві Твоє́й возгорі́ся і оби́тель із ка́мене во і́м'я пречестна́го Успе́нія Твоєго́ пусти́нником поча́євським устроя́єть, в не́йже чудотво́рному о́бразу Твоєму́ покланя́ющеся взива́єть си́це:","Ра́дуйся, сокро́вище бога́тноє в Твоє́й святі́й іко́ні нам препода́вшая;","ра́дуйся, святи́теля руко́ю дарова́нним о́бразом Твої́м зе́млю на́шу освяти́вшая.","Ра́дуйся, ду́ші на́ша от земна́го бога́тства отвраща́ющая;","ра́дуйся, Сла́ву Бо́жию пі́ти нас науча́ющая.","Ра́дуйся, я́ко чудеса́ Твоя́ зря́ще, к Небесі́ сердці́ свої́ми восхища́ємся;","ра́дуйся, я́ко во оби́телі Твоє́й, а́ки в преддве́рії рая́ обріта́ємся.","Ра́дуйся, правосла́вния лю́ди іко́ною Твоє́ю уте́шившая;","ра́дуйся, от всіх стран моля́щіяся лю́ди во оби́тель Поча́євськую призива́ющая.","Ра́дуйся, Є́юже ві́ра умножа́ється;","ра́дуйся, Є́юже уни́ніє отго́ниться.","Ра́дуйся, і́ноков поча́євських при́сноє Ра́дованіє;","ра́дуйся, мирськи́х люде́й непости́дноє Упова́ніє.","Ра́дуйся, похвало́ Поча́євськая і всего́ ми́ра наде́ждо і утіше́ніє."]},{"h":"Кондак 4","ps":["Бу́ря єреті́чеськаго неі́стовства на святу́ю оби́тель Твою́ устреми́вшися, Влади́чице, святу́ю іко́ну Твою́ руко́ю злих іконобо́рцев пліни́вши і на злохуле́ніє тіх подви́гши, вско́рі гні́вом Бо́жиїм уде́ржана бисть, єгда́ неви́димая си́ла безсту́дне пи́ршествующия ху́льники, а́ки Артаксе́ркса і І́рода, сляче́ і в неду́г вве́рже, над святи́нею Твоє́ю руга́вшихся і не уві́дівших пі́ти: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаша і́ноці поча́євстії і всі правосла́внії лю́діє, я́ко свята́я іко́на Твоя́ по седьмина́десяти лі́тіх єреті́чеськаго пліне́нія во святу́ю оби́тель от посра́мленних хули́телей возвраща́ється, а́біє на срі́теніє єя́ ізидо́ша і плач свой на ра́дость прело́жше, вопія́ху Тебі́:","Ра́дуйся, христия́ном прибі́жище;","ра́дуйся, єретико́в обличе́ніє.","Ра́дуйся, оби́тель Поча́євськую іко́ни Твоєя́ до конця́ не лиши́вшая;","ра́дуйся, злохуле́ніє іконобо́рцев посрами́вшая.","Ра́дуйся, я́ко в біда́х не унива́ти і нас науча́єши;","ра́дуйся, я́ко правосу́дію Бо́жию ві́ровати нам повеліва́єши.","Ра́дуйся, Є́юже Правосла́віє во страні́ на́шей утверди́ся;","ра́дуйся, Є́юже і вся вселе́нная воплоще́нную І́стину прия́ти сподо́бися.","Ра́дуйся, долготерпі́нію Бо́жию подража́ющая;","ра́дуйся, в терпі́нії лю́ди Твоя́ утвержда́ющая.","Ра́дуйся, я́ко смире́ннії Тобо́ю утіше́ніє приє́млють;","ра́дуйся, я́ко гордели́вії Тобо́ю смиря́ються.","Ра́дуйся, похвало́ Поча́євськая і всего́ ми́ра наде́ждо і утіше́ніє."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́ і́щущим спасе́нія яви́лася єси́, Влади́чице, к Со́лнцю Пра́вди сих приводя́щая, я́коже бо в земні́м житії́ Твоє́м о лю́діх предста́тельниця к Си́ну Твоєму́ в Ка́ні Галиле́йстій показа́лася єси́, та́ко і по пресла́вном Твоє́м на Небеса́ отше́ствії моле́нія о ві́рних, от коне́ць землі́ приноси́мая, к Си́ну Твоєму́ возно́сиши і зді, на горі́ Поча́євстій, ісціле́нія многоразли́чная от Него́ лю́дем подає́ши, вопію́щим Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́діша лю́діє, на го́ру Поча́євськую, я́коже в дре́вняя, та́ко і в послі́дняя лі́та притека́ющії, мно́жества ісціле́ній, Тобо́ю подава́ємая, в жела́нії спасе́нія ду́ші своя́ утвержда́ху і о грісі́х свої́х покая́ніє те́плоє приноша́ху, вопію́ще Тебі́:","Ра́дуйся, сліпи́х прозрі́ніє і хроми́х ісціле́ніє;","ра́дуйся, бі́сних от де́монов ізбавле́ніє.","Ра́дуйся, пліне́ннаго і́нока во оби́тель Твою́ на возду́сі чуде́сне возврати́вшая;","ра́дуйся, младе́нця Симео́на предуме́рша по моли́тві ста́риці воскреси́вшая.","Ра́дуйся, я́ко в сих зна́меніїх си́ла дре́вніх чуде́с Твої́х лю́дем па́ки яви́ся;","ра́дуйся, я́ко ісціле́нія от святи́я іко́ни Твоєя́ і в послі́дняя дні не оскуді́ша.","Ра́дуйся, во всем ми́рі істо́чник ісціле́ній от святи́х іко́н Твої́х подаю́щая;","ра́дуйся, па́че сих духо́вними дарова́ньми моля́щіяся обогаща́ющая.","Ра́дуйся, Є́юже правосла́внії ро́ди хва́ляться;","ра́дуйся, к Єя́же по́мощі і малові́рнії притека́ють.","Ра́дуйся, земноро́дних упова́ніє;","ра́дуйся, Небе́сних чино́в ра́дованіє.","Ра́дуйся, похвало́ Поча́євськая і всего́ ми́ра наде́ждо і утіше́ніє."]},{"h":"Кондак 6","ps":["Пропові́дници сла́ви Пречи́стия Ді́ви яви́шася ага́ряне на оби́тель Поча́євськую наше́дшії і виді́нія Пречи́стия Богоро́диці с преподо́бним І́овом пе́рвіє не уразумі́вшії; єгда́ бо стрі́ли, от них пуща́ємия, па́ки на ня устреми́шася, а́біє си́лу Влади́чиці проразумі́вше і покая́ніє о безу́мії своє́м прине́сше, ві́рою возопи́ша: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ виді́ніє Твоє́, Влади́чице, на горі́ Поча́євстій, єгда́ бра́тія оби́телі, зіло́ от ага́рян осажда́єми, с ве́ліїм во́плем моле́ніє пред свято́ю Твоє́ю іко́ною і пред ра́кою преподо́бнаго І́ова возноша́ше, єгда́ же бра́тія ага́ряни, виді́нієм сим см'яте́нния і бежа́щия, ви́діша, а́біє с весе́лієм воспі́ша Тебі́ си́це:","Ра́дуйся, Ізба́вительнице на́ша і спасе́ніє;","ра́дуйся, ро́да христия́нськаго при́сноє вспоможе́ніє.","Ра́дуйся, нечести́вия враги́ от Твоєя́ святи́ні отгна́вшая;","ра́дуйся, в покая́ніє їх приводя́щая.","Ра́дуйся, Єя́же і неви́димії спасе́нія на́шего вразі́ трепе́щуть;","ра́дуйся, Є́йже Святі́ї А́нгели і преста́вльшіяся пра́ведници на Небесі́ покланя́ються.","Ра́дуйся, преподо́бнаго І́ова в моли́тву с Собо́ю приє́мшая;","ра́дуйся, ага́ряни ко Свято́му Креще́нію виді́нієм Свої́м приве́дшая.","Ра́дуйся, я́ко Тобо́ю ві́рнії страх сме́ртний в коне́ць отложи́ша;","ра́дуйся, я́ко Тебе́ ра́ди ні́циї от ага́рян богобоя́зненнії і́ноці зді яви́шася.","Ра́дуйся, і́стини при́сноє із'явле́ніє;","ра́дуйся, заблужда́ющимся до́броє вразумле́ніє.","Ра́дуйся, похвало́ Поча́євськая і всего́ ми́ра наде́ждо і утіше́ніє."]},{"h":"Кондак 7","ps":["Хотя́щи жела́ніє ві́чнаго живота́ возгре́ти в сердця́х христия́нських, Пресвята́я Богоро́диця боля́щия чудеси́ Свої́ми ісціля́єть, бі́си ізгоня́єть, пліне́нния свобожда́єть, ме́ртвия воскреша́єть, да ми всі, си́лу Бо́жию уразумі́вше, земна́я возненави́дим і о душа́х свої́х попече́ніє приложи́м, непреста́нно вопію́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вия і тягча́йшия біди́ претерпі́ оби́тель Поча́євськая, єгда́ вку́пі со все́ю страно́ю от Правосла́вія ле́стію отто́рженная во облада́ніє єретико́во вдаде́ся, оба́че проше́дшим стом і десяти́м лі́том па́ки правосла́вним христия́ном вдана́ бисть, в ню́же правосла́внії і́ноці, прише́дше і святи́я мо́щі преподо́бнаго І́ова із-под спу́да із'є́мше, к чудотво́рному о́бразу Влади́чиці припа́даху, глаго́люще:","Ра́дуйся, Правосла́вія защи́тнице;","ра́дуйся, єретико́в обличи́тельнице.","Ра́дуйся, оби́тель Твою́ до конця́ не оста́вившая;","ра́дуйся, стра́ху Бо́жию нас науча́ющая.","Ра́дуйся, я́ко предста́тельством Твої́м страна́ Воли́нськая па́ки ко Правосла́вію возврати́ся;","ра́дуйся, я́ко от літ дре́вніх мно́зі єретиці́ Твої́м вразумле́нієм іспра́вишася.","Ра́дуйся, во святу́ю Ла́вру Твою́ ві́рних на моли́тву па́ки призива́ющая;","ра́дуйся, і неві́рния зді поклоня́тися правосла́вній святи́не науча́ющая.","Ра́дуйся, Ю́же пра́ведници і пра́веднії непреста́нно воспіва́ють;","ра́дуйся, к Не́йже і па́дшії в покая́нії притека́ють.","Ра́дуйся, отсту́пников к ві́рі возвраще́ніє;","ра́дуйся, прельща́ємих к сві́ту і́стини возведе́ніє.","Ра́дуйся, похвало́ Поча́євськая і всего́ ми́ра наде́ждо і утіше́ніє."]},{"h":"Кондак 8","ps":["Стра́нноє чу́до зрим о Тебі́, Богома́ти, єли́ко бо тіле́снії неду́зі святи́я Твоєя́ іко́ни цілова́нієм і води́ поча́євськия кропле́нієм ісціля́ються, та́ко і душе́вния стра́сті ви́дінієм святи́ні Твоєя́ от'є́млються, ві́ра утвержда́ється і умиле́нія сердця́ на́ша ісполня́ються, пою́щих Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь аз недосто́йний гріха́ми іспо́лнихся, мирсько́му разсе́янію вда́вся і о душі́ своє́й вознераде́в, оба́че на святу́ю іко́ну Твою́, Влади́чице, взира́я, і просвіще́ніє от нея́ безчи́сленним лю́дем, зді приходя́щим, ви́дя, па́ки на путь спасе́нія устремля́юся і в ра́дості се́рдця воспіва́ю Ті си́це:","Ра́дуйся, чистоти́ сокро́вище;","ра́дуйся, ми́лостей бе́здно.","Ра́дуйся, к Си́ну Твоєму́ о ві́рних моле́нія ви́ну принося́щая;","ра́дуйся, моле́нія грі́шних не отверга́ющая.","Ра́дуйся, я́ко Тобо́ю мно́зі отча́янія гріхо́внаго ізбіго́ша;","ра́дуйся, я́ко призива́ющії і́м'я Твоє́ от паде́нія стра́ннаго возста́ша.","Ра́дуйся, Є́юже іконобо́рная є́ресь во вселе́нній посрами́ся;","ра́дуйся, Є́юже і́стинная ві́ра Воли́нськой страні́ возврати́ся.","Ра́дуйся, к по́двигу цілому́дрія ду́ші возводя́щая;","ра́дуйся, оби́дящим проща́ти науча́ющая.","Ра́дуйся серде́ць на́ших умиле́ніє;","ра́дуйся, душ на́ших упова́ніє.","Ра́дуйся, похвало́ Поча́євськая і всего́ ми́ра наде́ждо і утіше́ніє."]},{"h":"Кондак 9","ps":["Вся́кия отсту́пства і єрети́чеськая блужда́нія пока́явшемуся наро́ду землі́ Воли́нськия отпусти́ла єси́, Влади́чице, і па́ки істо́чник ісціле́ній от чудотво́рния Твоєя́ іко́ни, от слі́да стопи́ Твоєя́ на горі́ Поча́євстій в правосла́вной Ла́вре Твоє́й лю́дем откри́ла єси́, то́кмо а́ще покая́ніє о грісі́х свої́х принесу́ть Бо́гу і, о Твоє́й по́мощі не сумня́щеся, возопію́ть Єму́: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́я сла́ви Твоєя́ яви́шася, Влади́чице, сліпі́ї і хро́мії ісціле́ніє от Твоєя́ іко́ни, правосла́вним лю́дем возвраще́нния, прия́вшії, я́ко і єрети́чеськой жені́ ні́коєй боля́щей, Тя в по́мощ призва́ти і по ісціле́нії і́стинную ві́ру іспові́дати і облобиза́ти, нам же вопи́ти Тебі́ си́це:","Ра́дуйся, Царя́ Небе́снаго умоле́ніє;","ра́дуйся, земни́х при́сноє предста́тельство.","Ра́дуйся, от лю́терських заблужде́ній жену́ ні́кую неду́га ісціле́нієм отврати́вшая;","ра́дуйся, вся лю́ди во і́стині Правосла́вія уві́рившая.","Ра́дуйся, я́ко Тебе́ ра́ди правосла́внії лю́діє столькра́ти прельще́нія ага́рянськая побіди́ша;","ра́дуйся, я́ко Тебе́ ра́ди і совраще́ннії от лати́н па́ки правосла́вную ві́ру облобиза́ша.","Ра́дуйся, к Не́йже всі живу́щії моли́твенно о́чі воздвиза́ють;","ра́дуйся, Ю́же і моля́щіїся о упокоє́нії уме́рших в по́мощ призива́ють.","Ра́дуйся, і от жите́йських нужд притека́ющия к Тебі́ із'є́млющая;","ра́дуйся, па́че сих вся́кия ну́жди претерпева́ющим крі́пость да́рствующая.","Ра́дуйся, христолюби́вому во́їнству во бранеіх вспоможе́ніє;","ра́дуйся, на де́мони во́їнствующим благо́є наставле́ніє.","Ра́дуйся, похвало́ Поча́євськая і всего́ ми́ра наде́ждо і утіше́ніє."]},{"h":"Кондак 10","ps":["Спасти́ хотя́щи Пречи́стая Богоро́диця препро́стую ні́кую ста́рицю, во осліпле́нії лати́нстем би́вшую і вну́ку ма́лую іму́щую, Правосла́вієм у́бо просвіще́нную, но тіле́сними очеси́ слепотству́ющу, си́ма обі́ма благо́є жела́ніє влага́єть, є́же на горі́ Поча́євстій чудотво́рному Єя́ о́бразу поклони́тися, іді́же а́біє слепу́ю отрокови́цю чуде́сне ісціля́єть і ста́рицю правосла́вную ві́ру іспові́дати науча́єть, вопію́щую Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ неруши́мая і́стинния ві́ри яви́лася єси́, Влади́чице, зане́, я́коже нечести́вії єретиці́ от прославле́нія Тебі́, я́ко І́стинния Богоро́диці, с упо́рством отверго́шася, та́ко і правосла́внії во ві́рі Твоє́й тве́рди преби́ша і от моли́тв, непреста́нно Тебі́ приноси́мих, ніколи́же отврати́тися восхо́щуть, і сих ра́ди єрети́чеських глаго́л во ушеса́ своя́ прийма́ти не де́рзнуть, но се́рдцем благода́рним восхваля́ти Тя не преста́нуть, глаго́люще:","Ра́дуйся, христия́ном отра́до і утіше́ніє;","ра́дуйся, А́нгельським чино́м сла́во і поклоне́ніє.","Ра́дуйся, от льсти́вих глаго́л єрети́чеських нас отвраща́ющая;","ра́дуйся, па́м'ятованієм ми́лостей Твої́х уми́ на́ша к Бо́гу вознося́щая.","Ра́дуйся, святи́я Апо́столи ко Успе́нію Твоєму́ на о́блаціх возду́шних призва́вшая;","ра́дуйся, і грі́шния лю́ди в той день на го́ру Поча́євськую в ти́сящах і тьмах на вся́ко лі́то собира́ющая.","Ра́дуйся, Єя́же ра́ди христия́не тру́дность путі́, а́ки сла́дкоє упокоє́ніє, под'є́млють;","ра́дуйся, Єя́же ра́ди і ліни́вії подража́ти їм тща́ться.","Ра́дуйся, і́ноком сла́дость мирську́ю заби́ти благода́тію Твоє́ю посо́бствующая;","ра́дуйся, всп'ять озира́ющіяся сновиде́ньми гро́зними устраша́ющая.","Ра́дуйся, Це́ркве Христо́ви лу́чшая дияди́мо;","ра́дуйся, страни́ на́шея щі́те неодоли́мий.","Ра́дуйся, похвало́ Поча́євськая і всего́ ми́ра наде́ждо і утіше́ніє."]},{"h":"Кондак 11","ps":["Пі́ніє благода́рноє о Твої́х, Влади́чице, благодія́ніях во всем ми́рі от христия́н возноси́моє, а́ки фимія́м, к Небесі́ непреста́нно восходя́щий, помишля́юще, і на́ша убо́гая хвале́нія не отврати́ти Тебі́ про́сим, єще́ же і благода́ть покая́нія дарова́ти Тебі́ мо́лим, со упова́нієм пою́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світ живота́ вре́меннаго і ві́чния жи́зні упова́ніє яви́лася єси́, Влади́чице, челові́ку ні́коєму в Бессара́бії умре́ти іму́щему, но внеза́пу, по вкуше́нії води́ от святи́ні Поча́євськия, здра́ву би́вшему, є́же сро́дниці єго́ ви́дівше, со стра́хом і умиле́нієм Тебі́ воззва́ша:","Ра́дуйся, боля́щих ісціле́ніє;","ра́дуйся, скорб'я́щих сли́шаніє.","Ра́дуйся, Тобо́ю бо смерть прише́дшая отгна́ся;","ра́дуйся, Тобо́ю бо ві́ра несумні́нная нам дарова́ся.","Ра́дуйся, я́ко предвеща́ніє Гавриї́ла пред о́чію на́шею сбива́ється;","ра́дуйся, я́ко от всіх родо́в, по глаго́лу Твоєму́, ни́ні і при́сно ублажа́єшися.","Ра́дуйся, го́ру Поча́євськую, я́ко мі́сто пребива́нія Твоєго́ освяти́вшая;","ра́дуйся, а́ки втори́й Назаре́т ту́ю яви́вшая.","Ра́дуйся, Я́же нікого́же упова́нія отврати́вшая;","ра́дуйся, всіх моли́тви те́плі приє́млющая.","Ра́дуйся, здра́віє нам подава́ющая;","ра́дуйся, ко спасе́нію нас возводя́щая.","Ра́дуйся, похвало́ Поча́євськая і всего́ ми́ра наде́ждо і утіше́ніє."]},{"h":"Кондак 12","ps":["Благода́ть ісціле́ній і умиле́нія моли́твеннаго от Твоєя́, Влади́чице, іко́ни істоча́ємая, да не вотще́ душа́м на́шим бу́деть, а́ще бо гріх ра́ди во окамене́нноє безчу́вствіє впадо́хом, оба́че, я́ко іму́щая власть ме́ртвия воскреша́ти, і на́ше пробуди́ душе́вноє омертве́ніє і по́мислом лу́чшим сердця́ на́ша озари́, да, гріхо́вную пре́лесть возненави́дівше, воспоє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Твоя́ чудеса́ во оби́телі Поча́євстій явле́нная, мо́лим Тя, Влади́чице, лиця́ Твоєго́ от страни́ на́шея не отврати́, но і всім приходя́щим на святу́ю го́ру Твою́ і ми́лости от Тебе́ і́щущим во благо́є проше́ніє іспо́лни, да всі воспою́ть Ті си́це:","Ра́дуйся, всепра́веднаго Бо́га умилостивле́ніє;","ра́дуйся, христия́н ко Христу́ дерзнове́ніє.","Ра́дуйся, торжество́ ві́ри в Ла́врі Твоє́й явля́ющая;","ра́дуйся, сердца́ челові́ков любо́вію распаля́ющая.","Ра́дуйся, я́ко дре́внім чудесе́м подо́бноє зді ви́діти лю́діє сподо́бишася;","ра́дуйся, я́ко гора́ сія́, а́ки втори́й Сина́й, в страна́х христия́нських просла́вися.","Ра́дуйся, Бо́га, на землі́ я́вльшагося, во чре́ві Твоє́м поне́сшая;","ра́дуйся, челові́ки моли́твою Твоє́ю к Бо́гу вознося́щая.","Ра́дуйся, іко́ну Твою́, я́ко пропові́дницю спасе́нія во оби́телі Твоє́й оста́вившая;","ра́дуйся, слід стопи́ Твоєя́, целе́бною водо́ю ісполня́ємий, чудеси́ просла́вившая.","Ра́дуйся, с небе́сних висо́т на раби́ Твоя́ призира́ющая;","ра́дуйся, на благи́я дія́нія ві́рния наставля́ющая.","Ра́дуйся, похвало́ Поча́євськая і всего́ ми́ра наде́ждо і утіше́ніє."]},{"h":"Кондак 13","ps":["О Всепі́тая Ма́ти Христа́ Бо́га, вся ро́ди христия́нськия любо́вію Себі́ всинови́вшая, досто́йния похвали́ воспі́ти Тебі́ недоумі́єм ми, грі́шнії, оба́че, любо́вію Твоє́ю побежда́ємії і к Твоєму́ чудотво́рному о́бразу о́чі своя́ вознося́ще, мо́лим Тя: в боре́нії і ну́ждах на́ших не оста́ви чад Твої́х, заступле́нію Твоєму́ те́плі ві́рующих і Си́ну Твоєму́ вопію́щих: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Арха́нгел Гавриї́л пе́рвіє «Ра́дуйся!» тебі́ приноша́ше, Влади́чице, єгда́ зача́тіє Си́на Бо́жия благовіствова́ше, по пресла́внім же Успе́нії Твоє́м вся Небе́сния си́ли ту́южде хвалу́ на Небесі́ Тебі́ непреста́нно прино́сять; ка́ко у́бо ми, грі́шнії, своя́ гла́си с гла́си Безпло́тних совокупи́ти де́рзнем? Оба́че, милосе́рдіє Твоє́ ко всім ка́ющимся помина́юще, устні́ на́ша со стра́хом і любо́вію отверза́єм, глаго́люще си́це:","Ра́дуйся, ми́лости бе́здно;","ра́дуйся, любве́ неістощи́моє мо́ре.","Ра́дуйся, ро́да христия́нськаго блага́я Предста́тельнице;","ра́дуйся, оби́телі Поча́євския стіно́ неруши́мая.","Ра́дуйся, правосла́вния лю́ди на го́ру Поча́євськую у́зами любве́ привлека́ющая;","ра́дуйся, вся́кую печа́ль от душ їх отгоня́ющая.","Ра́дуйся, Єя́же чудотво́рний о́браз, я́ко звізда́, от гори́ Поча́євськия нас путево́дствуєть;","ра́дуйся, Є́йже возноси́мия моли́тви стра́стния прило́ги вско́рі отража́ють.","Ра́дуйся, явле́нієм Свої́м на горі́ сей лю́ди уте́шившая;","ра́дуйся, слід стопи́ Твоєя́ на ней нам оста́вившая.","Ра́дуйся, ві́рних при́сноє дерзнове́ніє;","ра́дуйся, сумня́щихся до́броє утвержде́ніє.","Ра́дуйся, похвало́ Поча́євськая і всего́ ми́ра наде́ждо і утіше́ніє."]},{"h":"Кондак 1","ps":["Взбра́нной Воєво́ді родо́в христия́нських і страни́ на́шея ізві́стній Ізба́вительнице хвале́бния пі́сні принесе́м, ві́рнії, на святі́й горі́ Єя́ собра́вшеся; Ти же, я́ко іму́щая милосе́рдіє неізрече́нноє, о Влади́чице Богоро́дице, моле́нія на́шего, пред чудотво́рним Твої́м о́бразом возноси́маго, не отве́ржи, да в умиле́нії серде́ць зове́м Ті:","Ра́дуйся, похвало́ Поча́євськая і всего́ ми́ра наде́ждо і утіше́ніє."]},{"h":"Молитва","ps":["К Тебі́, о Богома́ти, моли́твенно притека́єм ми, грі́шнії, чудеса́ Твоя́, во святі́й ла́вре Поча́євстій явле́нная, помина́юще і о свої́х сокруша́ющеся прегріше́ніїх. Ві́ми, Влади́чице, ві́ми, я́ко не подоба́ше нам, грі́шним, чесого́ проси́ти, то́кмо о є́же Пра́ведному Судії́ беззако́нія на́ша оста́вити нам. Вся бо на́ми в житії́ претерпі́нная, ско́рби же, і ну́жди, і болі́зні, я́ко плоди́ паде́ній на́ших прозябо́ша нам, Бо́гу сія́ на ісправле́ніє на́ше попуща́ющу. Ті́мже вся сія́ і́стиною і судо́м Свої́м наведе́ Госпо́дь на грі́шния раби́ Своя́, і́же в печа́ліх свої́х к заступле́нію Твоєму́, Пречи́стая, притеко́ша і во умиле́нії серде́ць к Тебі́ взива́ють си́це: гріхо́в і беззако́ній на́ших, Блага́я, не пом'яни́, но па́че всечестни́я ру́ці Твої́ воздви́гши, к Си́ну Твоєму́ і Бо́гу предста́ни, да лю́ті соді́янная на́ми отпу́стить нам, да за премно́гая неіспо́лненная обіща́нія на́ша лиця́ Своєго́ от рабо́в Свої́х не отврати́ть, да благода́ті Своєя́, спасе́нію на́шему посо́бствующия, от душ на́ших не оти́меть. Єй, Влади́чице, бу́ди спасе́нію на́шему Хода́тайця і, малоду́шія на́шего не возгнуша́вшися, при́зри на стена́нія на́ша, я́же в біда́х і ско́рбіх на́ших пред чудотво́рним Твої́м о́бразом возно́сим. Просвіти́ умиле́нними по́мисли уми́ на́ша, ві́ру на́шу укріпи́, наде́жду утверди́, любве́ сладча́йший дар сподо́би нас прия́ти. Си́ми у́бо, Пречи́стая, дарова́ньми, а не болі́зньми і скорбми́ живо́т наш ко спасе́нію да возво́диться, но, от уни́нія і отча́янія ду́ші на́ша огражда́ющи, ізба́ви нас, маломо́щних, от находя́щих на ни бід, і нужд, і клевети́ челові́чеськія, і болі́зней нестерпи́мих. Да́руй мир і благоустроє́ніє жи́тельству христия́нському предста́тельством Твої́м, Влади́чице, утверди́ Правосла́вную ві́ру в страні́ на́шей і во всем ми́рі. Це́рков Апо́стольськую і Собо́рную умале́нію не преда́ждь, уста́ви святи́х оте́ць на ві́ки непоколеби́ми сохрани́ і всіх к Тебі́ притека́ющих от ро́ва поги́бельнаго спаси́. Єще́ же і є́ресію прельще́нних бра́тій на́ших іли́ ві́ру спаси́тельную во гріхо́вних страстеіх погуби́вших па́ки ко і́стинній ві́рі і покая́нію приведи́, да вку́пі с на́ми, Твоєму́ чудотво́рному о́бразу покланя́ющеся, Твоє́ предста́тельство іспові́дять. Сподо́би у́бо нас, Пресвята́я Госпоже́ Богоро́дице, єще́ в животі́ сем побі́ду і́стини Твої́м заступле́нієм узрі́ти, сподо́би нас благода́тную ра́дость пре́жде кончи́ни на́шея восприя́ти, я́коже дре́вле насе́льники Поча́євськия Твої́м явле́нієм побіди́телі і просвіти́телі ага́рян показа́ла єси́, да всі ми благода́рним се́рдцем вку́пі со А́нгели, і проро́ки, і апо́столи, і со всі́ми святи́ми, Твоє́ милосе́рдіє прославля́юще, воздади́м сла́ву, честь і поклоне́ніє в Тро́йці піва́ємому Бо́гу Отцю́, і Си́ну, і Свято́му Ду́ху, во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["Цари́це на́ша Преблага́я, Влади́чице Преблагослове́нная, наде́ждо на́ша Богоро́дице! К Тебі́ умиле́нно ни́ні притека́єм, і сокруше́нною душе́ю і смире́нним се́рдцем мо́лим Тя, Всепі́тая, пред пречи́стим Твої́м о́бразом: пом'яни́ щедро́ти Твоя́ дре́внія, я́же от Тебе́ зді би́вшия, і я́коже іногда́ яви́лася єси́ на скалі́ Поча́євстій, в столпі́ о́гненнім, от ка́мене цільбоно́сную во́ду істоча́ющи, си́це і ни́ні предста́ни нам, Ма́ти Многомо́щная, і теплото́ю Богома́тернія любве́ Твоєя́ согрі́й сердця́ на́ша окамене́нная, сле́зи любве́ і покая́нія нераска́яннаго от оче́й на́ших історга́ющи. Ти бо єди́на єси́ засту́пниця на́ша богодарова́нная: Тя у́бо мо́лим, ізба́ви от всіх бід, от вся́кия напа́сти, болі́зні і ско́рби, раби́ Твоя́, предста́тельством вели́каго о нас хода́тая і моли́твенника Твоєго́, всеблаже́ннаго отця́ на́шего І́ова, уго́дника Твоєго́ Поча́євськаго, єго́же моли́тві я́ві внима́ла єси́ на возду́сі іногда́, єгда́ всесла́вним і стра́шним явле́нієм Твої́м ізба́вила єси́ оби́тель Твою́ от наше́ствія і обложе́нія ага́рянськаго. При́зри благосе́рдієм, Всепі́тая, призрі́нієм ми́лостиваго Твоєго́ заступле́нія на страну́ на́шу, і на вся лю́ди твоя́ ізле́й бога́тия Твоя́ ми́лості: разсі́янния собери́, неві́рния же і інові́рния, во страна́х на́ших, на путь і́стинний наста́ви, отпа́дшия от благочести́вия оте́чеськия ві́ри па́ки возврати́ і сопричти́ їх святі́й Твоє́й правосла́вній і кафоли́честій Це́ркві: в семе́йствах на́ших мир утверди́, ста́рость поддержи́, ю́ния наста́ви, младе́нці воспита́й, си́рия і вдови́ці заступи́, пліне́нния свободи́, боля́щия уврачу́й, на суди́щі і в темни́цях, і в заточе́ніїх, і в го́рких рабо́тах су́щих пом'яни́, огражда́ющи ни ви́ну, посіща́ющи і утеша́ющи то́ками чуде́с і зна́меній многоразли́чних, я́же при́сно ізлива́єши всім от святи́я іко́ни Твоєя́ цільбоно́сния. Да́руй, Всеблага́я, землі́ плодоро́діє, возду́ха благорастворе́ніє і вся, я́же на по́льзу на́шу да́ри благовре́менния і благопотре́бния, моли́твами ізбра́нних уго́дников Твої́х, благода́тний Твой лик на святі́й іко́ні Твоє́й окружа́ющих: Ілії́ богоглаго́ливаго, свята́го архідия́кона Стефа́на первострада́льнаго, преподо́бнаго Авраа́мія всеблаже́ннаго, і богому́жнаго Ми́ни му́ченика многоімени́таго, і с ни́ми ку́пно святи́х і пра́ведних жен: Параске́ви прехва́льния, Іри́ни преблаже́нния і святи́я Єкатери́ни великому́ченици многострада́льния, і всіх святи́х. Єгда́ же приспі́єть на́ше от житія́ сего́ отше́ствіє і к ві́чності преселе́ніє, си́це предста́ни нам, Преблагослове́нная, я́коже іногда́ благопоспеши́ла єси́ оби́телі Твоє́й во спасе́ніє во вре́м'я бра́ні збара́жськой, і Твої́м те́плим хода́тайством да́руй нам христия́нськую кончи́ну живота́ на́шего безболі́зненну, непости́дну, ми́рну і Святи́х Та́їн прича́стну: да я́коже в сей жи́зні, си́це і в бу́дущем ві́ці сподо́бимся всі, моли́твами Твої́ми, безконе́чния небе́сния жи́зні во Ца́рствії возлю́бленнаго Си́на Твоєго́, Го́спода Бо́га і Спа́са на́шего, Ісу́са Христа́, Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє, во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 5","ps":["Пред свято́ю Твоє́ю іко́ною, Влади́чице, / моля́щіїся ісціле́ній сподобля́ються, / ві́ри і́стинния позна́ніє приє́млють / і ага́рянськая наше́ствія отража́ють. / Ті́мже і нам, к Тебі́ припа́дающим, / гріхо́в оставле́ніє іспроси́, / по́мисли благоче́стія сердця́ на́ша просвіти́, / і к Си́ну Твоєму́ моли́тву вознеси́ // о спасе́нії душ на́ших."]},{"h":"Інший тропар, глас 4","ps":["К Богоро́диці прилі́жно ни́ні притеце́м грі́шнії і смире́ннії, і припаде́м к ди́вному о́бразу Єя́, і́же на горі́ Поча́євстій: к нему́же уми́льно взира́юще і моля́щеся Цари́це Влади́чице із глубини́ душе́вния вопіє́м: О Пречу́дная Ді́во, Ма́ти Го́спода Ви́шняго, от літ дре́вніх ізбра́вшая оби́тель Поча́євськую в мі́сто селе́нія Своєго́! Зе́млю оте́чественную на́шу в правосла́вії і ми́ре утверди́, і спаси́ всіх предстоя́щих і моля́щихся Тебі́ умиле́нною душе́ю і сокруше́нним се́рдцем, пред Пречи́стим Твої́м о́бразом со слеза́ми. Не отврати́ раби́ Твоя́ тщи: Тя бо єди́ну Наде́жду і́мами."]},{"h":"Кондак, глас 1","ps":["Істо́чник ісціле́ній і ві́ри Правосла́вния утвержде́ніє / Поча́євськая Твоя́ іко́на, Богоро́дице, яви́ся, / ті́мже і нас, к ней притека́ющих, / от бід і іскуше́ній свободи́, / ла́вру Твою́ невріди́му сохрани́, / Правосла́віє во о́крест стоя́щих страна́х утверди́, / і гріхи́ разріши́ моли́твенник Твої́х: // єли́ка бо хо́щещі, мо́жеши."]},{"h":"Величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / і почита́єм честну́ю іко́ну Твою́, / ю́же от літ дре́вніх // на горі́ Поча́євстій просла́вила єси́."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Одигітрія» Смоленська","e":"Akathist to the Theotokos before her icon “Hodegetria” of Smolensk","secs":[{"h":"Кондак 1","ps":["Ізбра́нній от всіх родо́в, небесі́ і землі́ Цари́це, Пресвяті́й Богоро́дице Одиги́трії, я́ко ізба́вльшеся от ві́чния сме́рти благода́тію от Тебе́ ро́ждшагося Христа́ Бо́га на́шего і Твої́м Ма́тернім пред Ним хода́тайством, благода́рственноє пі́ніє прино́сим Ті, раби́ Твої́. Ти же, Всеми́лостивая на́ша Засту́пнице, от вся́ких нас бід і ско́рбних обстоя́ній свобожда́й і к ца́рствію го́рнему путево́дствуй, да зове́м Ті:","Ра́дуйся, Богоро́дице Одиги́тріє, христия́н упова́ніє."]},{"h":"Ікос 1","ps":["Арха́нгельський глас вопіє́м Ті, Чи́стая: ра́дуйся, Благода́тная Одиги́тріє Марі́є, і ра́дости духо́вния іспо́лни нас, да благогові́йною душе́ю і чи́стим се́рдцем принесе́м Ті, ро́ждшей ми́ру Спаси́теля Христа́ Бо́га на́шего, глаго́ли сія́:","Ра́дуйся, Бо́га Отця́ благоволе́нієм осіне́нная;","ра́дуйся, Бо́га Си́на Ма́ти неіскусобра́чная.","Ра́дуйся, Бо́га Ду́ха Свята́го оби́тель свяще́нная;","ра́дуйся, Тро́їчеськия та́йни проявле́ніє.","Ра́дуйся, а́нгельських умо́в удивле́ніє;","ра́дуйся, челові́чеськаго ро́да украше́ніє.","Ра́дуйся, го́рняя с до́льними совокупи́вшая;","ра́дуйся, врата́ ра́йськия земноро́дним отве́рзшая.","Ра́дуйся, лі́ствице небе́сная;","ра́дуйся, ста́мно Богоприї́мная.","Ра́дуйся, купино́ неопали́мая;","ра́дуйся, трапе́зо пресвята́я.","Ра́дуйся, Богоро́дице Одиги́тріє, христия́н упова́ніє."]},{"h":"Кондак 2","ps":["Ви́дів іко́ну Пресвята́го Твоєго́ ли́ка, Богоро́дице Ді́во, ю́же всехва́льний євангели́ст Лука́ написа́, рекла́ єси́ о ней пречи́стими усти́ Твої́ми: «С се́ю іко́ною благода́ть Моя́ і си́ла». Таково́є обітова́ніє Твоє́ уві́дівше, благогові́йно почита́єм пресвяти́й о́браз Твой, Влади́чице, і воспіва́єм Си́ну Твоєму́ і Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Уразумі́в благоволе́ніє Твоє́, Богоро́дице, к сей іко́ні Твоє́й, сла́вний апо́стол Лука́ дарова́ ю в благослове́ніє і освяще́ніє Христо́вой Це́ркві Антіохи́йстей, в ней же Путеводи́тельницей она́ найменова́ся і чудеси́ боже́ственними просла́вися. О сем благодаря́ще Тя, Госпоже́ Всеблага́я, я́ко подо́біє пречи́стаго ли́ка Твоєго́ во утіше́ніє нам оста́вила єси́, усе́рдно Тебі́ вопіє́м:","Ра́дуйся, Цари́це го́рних і до́льних;","ра́дуйся, Влади́чице а́нгелов і челові́ков.","Ра́дуйся, ми́ра умире́ніє;","ра́дуйся, дре́внія вражди́ разруше́ніє.","Ра́дуйся, ді́вства сто́лпе;","ра́дуйся, смире́нія глубино́.","Ра́дуйся, облаче́нная в со́лнце;","ра́дуйся, сія́ющая Боже́ственною сла́вою.","Ра́дуйся, Ма́ти Сві́та Невече́рняго;","ра́дуйся, раю́ сла́дости небе́сния.","Ра́дуйся, вертогра́ді Христо́в благоуха́нний;","ра́дуйся, о́дре Царя́ Вели́каго.","Ра́дуйся, Богоро́дице Одиги́тріє, христия́н упова́ніє."]},{"h":"Кондак 3","ps":["Си́лою Бо́жиєю чудеса́ преди́вния соверша́хуся от іко́ни Твоєя́, Богома́ти Влади́чице, єгда́ принесе́на бисть в Царгра́д і в пресла́внім Влахе́рнстем хра́мі поста́влена; сліпи́я просвіща́ше, всяк неду́г в лю́діх врачева́ше благода́тію Твоє́ю, Богоро́дице, да всі зове́м просла́вльшему Тя Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́яше Тя Царгра́д Засту́пницю держа́вную, Богоро́дице Ді́во, і во дні нападе́нія на него́ враго́в си́льних і бранеїску́сних, по́мощ Твою́ многочу́дную от святи́я іко́ни Твоєя́ Одиги́трії получа́ше. Ті́мже мо́лимся Тебі́, Всеблага́я, я́коже дре́вле град о́ний мно́гажди от поги́белі спасла́ єси́, та́ко і нас смире́нних спаси́ от поги́белі ві́чния Ма́терним предста́тельством Твої́м ко Христу́ Бо́гу, да благода́рно зове́м Ті:","Ра́дуйся, Царгра́да крі́пкоє огражде́ніє;","ра́дуйся, Влахе́рнськаго хра́ма благода́тноє сокро́вище.","Ра́дуйся, нечести́вих ра́тей одолі́ніє;","ра́дуйся, враго́в Правосла́вія посрамле́ніє.","Ра́дуйся, чад Христо́вих Предводи́тельнице к побі́дам;","ра́дуйся, Помо́щнице ско́рая в біда́х к Тебі́ притека́ющих.","Ра́дуйся, Засту́пнице усе́рдная моли́твенно Тя призива́ющих;","ра́дуйся, богому́дрих святи́телей споспі́шнице во благові́стії Христо́вом.","Ра́дуйся, похвало́ жен і дів сла́во;","ра́дуйся, сто́лпе о́гненний, зной страсте́й умеря́ющий.","Ра́дуйся, сто́лпе о́блачний, мрак гріхо́в разгоня́ющий;","ра́дуйся, Марі́є, Ма́ти Христа́ Бо́га на́шего.","Ра́дуйся, Богоро́дице Одиги́тріє, христия́н упова́ніє."]},{"h":"Кондак 4","ps":["Бу́рею морсько́ю корабли́ прего́рдаго Кага́на, град Твой пліни́ти восхоті́вшаго, сокруши́ла єси́, Влади́чице, і побі́ду над ним лю́дем христоімени́тим дарова́ла єси́ от святи́я іко́ни Твоєя́ Одиги́трії, лучи́ сві́та небе́снаго іспуська́я і во́ї правосла́вния і́ми просвіща́я, да всі уві́дять, я́ко Ти єси́ воі́стину Воєво́да держа́вная Царгра́да і просла́в'ять ми́лості Твоя́ і чудеса́, воспіва́я Спаси́телю Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше о чудесі́х Твої́х пресла́вних, Богоро́дице Ді́во, я́же от іко́ни Твоєя́ яви́ла єси́ в Царгра́ді, недоумі́єм, ка́ко іко́на та, носи́мая по сто́гнам гра́да, си́лою Боже́ственною носи́вшими ю управля́ше і стопи́ їх по во́лі Твоє́й направля́ше; напра́ви у́бо, Влади́чице, і на́ша стопи́ на путь ісполне́нія за́повідей Христо́вих, і научи́ нас ві́рно ісполня́ти святу́ю во́лю Си́на Твоєго́ і Бо́га, да Тебі́ вопіє́м си́це:","Ра́дуйся, свіще́ неугаси́мая;","ра́дуйся, звіздо́ незаходи́мая.","Ра́дуйся, сія́ющая сві́том Боже́ственним;","ра́дуйся, просвіща́ющая благода́тію ду́ші ві́рних.","Ра́дуйся, ми́ра Христо́ва благоуха́ніє;","ра́дуйся, землі́ освяще́ніє.","Ра́дуйся, ча́ше, че́рплющая ра́дость всему́ ми́ру;","ра́дуйся, істо́чниче, ізлива́ющий ві́чную сла́дость.","Ра́дуйся, черто́же благоукраше́нний Царя́ Царе́й;","ра́дуйся, рая́ красні́йшая.","Ра́дуйся, у́тра світлі́йшая;","ра́дуйся, ру́чко всезлата́я.","Ра́дуйся, Богоро́дице Одиги́тріє, христия́н упова́ніє."]},{"h":"Кондак 5","ps":["Я́ко Боготе́чная звізда́, іко́на Твоя́, Богома́ти Влади́чице, благоволе́нієм Твої́м от Царгра́да в страну́ Украї́нськую принесе́ся, і гра́ду Смоле́нську в наслі́діє благода́тноє дарова́ся, ті́мже благодари́м Тя, о Госпоже́ Всеми́лостивая, я́ко такови́й дар святи́й Оте́честву на́шему дарова́ла єси́, і поє́м в Тро́йці сла́вимому Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше пресла́вноє заступле́ніє Твоє́ гра́да Смоле́нська, Пречи́стая Влади́чице, прославля́єм вели́кую Твою́ ми́лость, є́юже град сей от разоре́нія Бати́єва чуде́сно спасла́ єси́, гла́сом Боже́ственним от іко́ни Твоєя́ ісше́дшим, уго́дника Христо́ва Мерку́рія на єдинобо́рство с предводи́телем ра́ти Бати́євой посла́в; єго́же он мече́м свої́м порази́ і град Твой от запале́нія о́гненнаго ізба́ви. Самаго́ же єго́ вінце́м му́ченичеським увінча́ла єси́, того́ моли́твами небе́сними сподо́би нас на землі́ неосужде́нно взива́ти к Тебі́:","Ра́дуйся, му́ченика Христо́ва Мерку́рія на по́двиг ра́тний укріпи́вшая;","ра́дуйся, гла́сом от іко́ни Твоєя́ святи́я єго́ воодушеви́вшая.","Ра́дуйся, я́ко Дави́да на Голія́фа побі́дою єго́ увенча́вшая;","ра́дуйся, гра́да Смоле́нська крі́пкоє защище́ніє.","Ра́дуйся, град Твой от разоре́нія ізба́вившая;","ра́дуйся, Ізба́вительнице от плі́на і пораже́нія.","Ра́дуйся, страни́ Украї́нськия благода́тноє утіше́ніє;","ра́дуйся, Це́ркві Христо́вой Боголі́пноє украше́ніє.","Ра́дуйся, лю́б'ящих Тя при́сноє ра́дованіє;","ра́дуйся, Утоли́тельнице печа́лей.","Ра́дуйся, боля́щих ісціле́ніє;","ра́дуйся, унива́ющих в ско́рбіх ободре́ніє.","Ра́дуйся, Богоро́дице Одиги́тріє, христия́н упова́ніє."]},{"h":"Кондак 6","ps":["Пропові́дуєть страна́ Украї́нськая ми́лості і чудеса́ Твоя́, Пречи́стая Ді́во Богоро́дице, і град Смоле́нск сві́тло красу́ється, імі́я чудотво́рную іко́ну Твою́, вся́кия болі́зні ісціля́ющую і неду́жним здра́віє подаю́щую. Сего́ ра́ди со благогові́нієм почита́єм многоціле́бний о́браз Твой, Госпоже́ Всеблага́я, і поклоня́ющеся єму́, я́ко зало́гу Твоєго́ к нам благоволе́нія, вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ла єси́ в страні́ Украї́нській луча́ми Боже́ственних чуде́с от святи́я іко́ни Твоєя́ ісходя́щими, Пречи́стая Влади́чице, к не́йже от літ дре́вніх отці́ на́ші прихожда́ше в ско́рбіх і болі́зніх і нетще́тни отхожда́ше. І́мже вслід і ми к Тебі́ приходя́ще і с любо́вію благогові́йно лобиза́я о́браз Твой чудотво́рний, мо́лимся Тебі́: утоли́ печа́лі на́ша, уврачу́й неду́ги на́ша, да зове́м Ті:","Ра́дуйся, же́зле ста́рости;","ра́дуйся, вдови́ць заступле́ніє.","Ра́дуйся, сиро́т призрі́ніє;","ра́дуйся, младе́нцев воспита́ніє.","Ра́дуйся, ни́щих снабді́ніє;","ра́дуйся, плі́нних свобожде́ніє.","Ра́дуйся, скорб'я́щих утіше́ніє;","ра́дуйся, сто́лпе і утвержде́ніє ді́вства.","Ра́дуйся, і́ноков Покрови́тельнице;","ра́дуйся, і́нокинь Наста́внице.","Ра́дуйся, по́стников укріпле́ніє;","ра́дуйся, в по́двигі ді́вства подвиза́ющихся вспоможе́ніє.","Ра́дуйся, Богоро́дице Одиги́тріє, христия́н упова́ніє."]},{"h":"Кондак 7","ps":["Хотя́ дарова́ти гра́ду Москві́ прича́стіє благода́ті от святи́я іко́ни Твоєя́, Влади́чице Всеми́лостивая, благоволи́ла єси́ принести́ іко́ну Твою́ от Смоле́нська в Москву́, да та́мо пребива́я, чудеси́ мно́гими просла́виться. Єгда́ же по умоле́нію жи́телей Смоле́нська, возвраща́шеся о́браз Твой святи́й в град їх, на мі́сті прохожде́нія іко́ни Твоєя́ Одиги́трії оби́тель дів во і́м'я Твоє́ сооруже́на бисть; в не́йже под осіне́нієм чудотво́рния іко́ни Твоєя́ с ві́рою і любо́вію воспіва́єм немо́лчную піснь Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Новосозда́нная оби́тель і́нокинь во гра́ді Москві́ благогові́йно честву́єть свято́є подо́біє чудотво́рния іко́ни Твоєя́ Одиги́трії, ми́лости неізрече́нния істоча́ющей ві́рним, єя́же осіне́нієм лю́ди правосла́вния благода́тно утіша́єши і в по́двигах поста́ і моли́тви утвержда́єши, подвиза́я їх немо́лчно воспіва́ти Ма́тернія Твоя́ щедро́ти і благода́рно взива́ти Тебі́:","Ра́дуйся, Бо́гом возлю́бленная Цари́це;","ра́дуйся, Бо́га возлюби́вшая па́че всего́ Влади́чице.","Ра́дуйся, єди́на благослове́нная в жена́х;","ра́дуйся, небе́сних ра́дованіє.","Ра́дуйся, земни́х заступле́ніє;","ра́дуйся, де́монов посрамле́ніє.","Ра́дуйся, а́да попра́ніє;","ра́дуйся, укрепле́нная си́лою Го́спода Сил.","Ра́дуйся, облече́нная вла́стію Цари́ці не́ба і землі́;","ра́дуйся, во́їнствующих на плоть цілому́дрієм блага́я Помо́щнице.","Ра́дуйся, подвиза́ющихся в пості́ і безмо́лвії ми́лостивая Уті́шительнице;","ра́дуйся, ізбавля́ющая скорбе́й вся́чеських.","Ра́дуйся, Богоро́дице Одиги́тріє, христия́н упова́ніє."]},{"h":"Кондак 8","ps":["Стра́нствіє земно́є многоско́рбноє і многом'яте́жноє услажда́єши нам Ма́терним Твої́м о нас попече́нієм, Богоро́дице, і во дні ско́рбних обстоя́ній по́мощ святу́ю явля́єши нам во спасе́ніє. Па́м'ятуєм і іспові́дуєм, Влади́чице, Твоє́ заступле́ніє, єгда́ га́лли страну́ Украї́нськую разори́ша і град Москву́ пліни́ша, Ти іко́ну Свою́ святу́ю Одиги́трію от Смоле́нська в полці́ во́їнства Украї́нськаго благоволи́ла єси́ принести́ і тім во́ї правосла́вния воодушеви́ла єси́, сла́вную побі́ду їм дарова́ла єси́, предста́тельством Твої́м к Си́ну Твоєму́ і Бо́гу. Єму́же поє́м: Аллилу́я."]},{"h":"Ікос 8","ps":["Вся ми́лості і щедро́т преіспо́лненная, Всеблага́я Ма́ти Бо́жия, во́їнству правосла́вному по́мощ і одолі́ніє на враги́ пресла́вно дарова́ла єси́. І єгда́ не бі нам уже́ спасе́нія наде́жди, я́ко і наш град пліне́н і разоре́н бисть, га́лли с безче́стієм от Оте́чества на́шего отгна́ла єси́ і побі́дою ди́вною нас увінча́ла єси́. Всегда́ па́м'ятуя таково́є Твоє́ заступле́ніє, хвале́бно Тебі́ вопіє́м:","Ра́дуйся, страну́ на́шу Украї́нськую от наше́ствія іноплеме́нних преди́вно ізба́вившая;","ра́дуйся, го́рдих си́лою Своє́ю со стидо́м всп'ять возврати́вшая.","Ра́дуйся, інові́рних ра́тей Всеси́льная Побіди́тельнице;","ра́дуйся, правосла́внаго во́їнства держа́вная посо́бнице.","Ра́дуйся, іко́ною Твоє́ю свято́ю с во́їнами Украї́нськими ми́лостивно пребива́ющая;","ра́дуйся, чудотво́рним о́бразом Твої́м полки́ їх освяща́ющая.","Ра́дуйся, ізнемога́ющих си́лою сви́ше укріпля́ющая;","ра́дуйся, безпомо́щним по́мощ Твою́ святу́ю подаю́щая.","Ра́дуйся, оби́димих правосу́дная Засту́пнице;","ра́дуйся, ненаде́жних наде́ждо.","Ра́дуйся, печа́льних отра́до.","Ра́дуйся, Богоро́дице Одиги́тріє, христия́н упова́ніє."]},{"h":"Кондак 9","ps":["Всі ві́рнії с ра́достію і утіше́нієм ви́дять о́браз Твой святи́й, на не́мже умиле́нно взира́єши на Богомладе́нця Христа́, сего́ ра́ди мо́лим Тя, Всеблага́я, я́ко Ма́тер вся содержа́щаго в десни́ці Своє́й Влади́ки: воззри́ і на нас ми́лостивно, і умоли́ Го́спода, да поми́луєть нас недосто́йних. Научи́ нас, Влади́чице, моли́тися Єму́ благоприя́тно, і неосужде́нно пі́ти Єму́ нескве́рними усти́ і чи́стим се́рдцем а́нгельськую піснь: Аллилу́я."]},{"h":"Ікос 9","ps":["Вети́йство на́ше пі́сненноє не довлі́єть к прославле́нію мно́гих Твої́х чуде́с, Богоро́дице Одиги́тріє, ї́хже от святи́я іко́ни Твоєя́ яви́ла єси́ і при́сно явля́єши ві́рним: оба́че Ти, я́ко воі́стину Блага́я Ма́ти, ві́ру і усе́рдіє на́ше прийми́; ві́си бо і любо́в к Тебі́ на́шу, є́юже сердця́ на́ша пламені́ють, і ми́лостивно усли́ши сії́ в простоті́ соста́вленния похвали́:","Ра́дуйся, обра́дованная Присноді́во;","ра́дуйся, Неві́сто Неневі́стная.","Ра́дуйся, селе́ніє Бо́га Сло́ва;","ра́дуйся, оби́тель Святі́йшаго святи́х.","Ра́дуйся, с Си́ном Царе́м небе́с ві́чно ца́рствующая;","ра́дуйся, Ма́тернєє дерзнове́ніє к Нему́ іму́щая.","Ра́дуйся, моли́твам ві́рних ми́лостивно вне́млющая;","ра́дуйся, лю́б'ящим Тя любо́вію Твоє́ю Боже́ственною воздаю́щая.","Ра́дуйся, Сіо́на го́рняго украше́ніє;","ра́дуйся, ми́ра до́льняго защище́ніє.","Ра́дуйся, гра́де спасе́нія на́шего;","ра́дуйся, горо́ свята́я, соше́ствієм Бо́жиїм просла́вленная.","Ра́дуйся, Богоро́дице Одиги́тріє, христия́н упова́ніє."]},{"h":"Кондак 10","ps":["Спаси́ нас, Влади́чице, от поги́белі ві́чния Ма́терним предста́тельством Твої́м ко Христу́ Бо́гу, і сподо́би нас узрі́ти Тя в час кончи́ни на́шея, от руки́ лю́таго миродержи́теля ду́шу на́шу соблюда́ющую; да по́мощію Твоє́ю свято́ю ізбі́гнем єго́ сіте́й і сподо́бимся Ца́рствіє Небе́сноє получи́ти і в ра́дості ві́чній воспіва́ти Человіколю́бцю Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ ді́вам, Богоро́дице Ді́во, і всім ревни́телем ді́вства і чистоти́ усе́рдная Помо́щнице. Мо́лим Тя, Пречи́стая, очи́сти на́ша сердця́ от вся́кия скве́рни гріхо́вния, і украси́ ду́ші на́ша цілому́дрієм і чистото́ю, да невреди́ми пребу́дем от всіх іскуше́ній ми́ра, пло́ті і дия́вола находя́щих, і сподо́бимся досто́йно возглаша́ти Тебі́ пі́сні такова́я:","Ра́дуйся, до́брая Младопита́тельнице ді́вам;","ра́дуйся, благосе́рдая Попечи́тельнице сиро́т.","Ра́дуйся, ти́хоє прибі́жище обурева́ємих страстя́ми;","ра́дуйся, наде́жноє приста́нище смуща́ємих іскуше́ніями.","Ра́дуйся, Мздовоздая́тельнице подви́жников цілому́дрія;","ра́дуйся, Спобо́рнице борю́щихся со враги́ неви́димими.","Ра́дуйся, ми́лостивая Посіти́тельнице непови́нно осужде́нних;","ра́дуйся, блага́я Уті́шительнице напра́сно оклевета́нних.","Ра́дуйся, Боже́ственная Свободи́тельнице су́щих в пліну́ і ізгна́нії;","ра́дуйся, всемо́щная Покрови́тельнице тружда́ющихся і обремене́нних.","Ра́дуйся, Судії́ Пра́веднаго умоле́ніє;","ра́дуйся, грі́шних с Бо́гом примире́ніє.","Ра́дуйся, Богоро́дице Одиги́тріє, христия́н упова́ніє."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє сли́шаще от ві́рних рабо́в Твої́х возноси́моє Ти, Пречи́стая Ма́ти Ді́во, я́ко іму́щая милосе́рдіє неізрече́нноє, наси́ти нас пи́щею нетлі́нною Сло́ва Бо́жия і научи́ нас всегда́ ісполня́ти животво́рния за́повіді Го́спода на́шего; Єго́же умоли́, Предста́тельнице на́ша Всеблага́я, да ниспо́слеть ми́лость Свою́ нам недосто́йним і сподо́бит нас унаслі́довати Єго́ всесві́тлоє і всеблаже́нноє Ца́рствіє, іді́же от всіх святи́х поє́ться Єму́ хвале́бная піснь: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́тлими луча́ми чуде́с Твої́х, Богоро́дице Ді́во, просвіща́єши нас благода́тно, і от святи́я іко́ни Твоєя́ Одиги́трії утіше́ніє духо́вноє низпосила́єши уго́дником Бо́жиїм. Нам же, грі́шним, да́ри ціле́бния подає́ши от Нея́ неоску́дно, да зове́м Ті благода́рственно і хвале́бно:","Ра́дуйся, А́гнця і Па́стиря Нетлі́ннаго ро́ждшая;","ра́дуйся, ді́вство і рождество́ в Себі́ сочета́вшая.","Ра́дуйся, кри́не ді́вства, к чи́стому і ді́вственному житію́ приводя́щая;","ра́дуйся, ізбра́нником Бо́жиїм любо́в Твою́ святу́ю явля́ющая.","Ра́дуйся, уго́дником Госпо́днім велі́нія небе́сния открива́ющая;","ра́дуйся, преподо́бнаго Се́ргия Ра́донежськаго посіще́нієм Твої́м сподо́бившая.","Ра́дуйся, преподо́бнаго Кири́лла Білоєзе́рськаго гла́сом от іко́ни Твоєя́ на Белоє́зеро напра́вившая;","ра́дуйся, преподо́бнаго Савва́тія Солове́цькаго в по́двигах пусти́нних укріпи́вшая.","Ра́дуйся, святи́теля Митрофа́на Воро́нежськаго іко́ною Твоє́ю облагода́тствовавшая.","Ра́дуйся, оби́телей Христо́вих покро́в і снабді́ніє;","ра́дуйся, рабо́в Бо́жиїх среди́ ми́ра та́йноє вразумле́ніє.","Ра́дуйся, Богоро́дице Одиги́тріє, христия́н упова́ніє."]},{"h":"Кондак 12","ps":["Благода́ть Бо́жия ді́йствуєть в чудесі́х, пресла́вно явля́ємих от свята́го о́браза Твоєго́, Преблагослове́нная Богоро́дице Ді́во, є́юже і на́ші ду́ші просвіти́, мрак гріхо́вний разгоня́я сія́нієм Со́лнця Пра́вди Христа́, да во сві́ті повелі́ній Єго́ богоуго́дно житіє́ сіє́ вре́менноє поживе́м во вся́ком благоче́стії і чистоті́ і сподо́бимся блаже́нство ві́чноє получи́ти і со ізбра́нними пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Твоя́ чудеса́, Богоро́дице, пропові́дуєм ми́лості Твоя́, прославля́єм щедро́ти Твоя́ неісче́тния і, припа́дая к чудотво́рній іко́ні Твоє́й, мо́лимтися с ві́рою і любо́вію: бу́ди нам Путеводи́тельниця Блага́я к сві́тлому гра́ду Ієрусали́му Небе́сному, да у́зрим Тя с висоти́ сла́ви Твоєя́ Боже́ственния на нас ми́лостивно взира́ющую і вку́пі со святи́ми воспоє́м Ті си́це:","Ра́дуйся, ра́досте на́ша пресвята́я;","ра́дуйся, Цари́це на́ша преблага́я.","Ра́дуйся, усинови́вшая нас при кресті́ Си́на Твоєго́ і Бо́га;","ра́дуйся, Ма́тернюю любо́в к нам явля́ющая.","Ра́дуйся, во благи́х жела́нія на́ша ди́вно ісполня́ющая;","ра́дуйся, скоропослу́шливая к смире́нним моли́твам.","Ра́дуйся, покро́вом Твої́м святи́м нас покрива́ющая;","ра́дуйся, ри́зою Твоє́ю честно́ю благонаде́жно нас защища́ющая.","Ра́дуйся, в час кончи́ни на́шея всеси́льная нам Помо́щнице;","ра́дуйся, в мита́рствах возду́шних держа́вная нам Засту́пнице.","Ра́дуйся, тіле́с на́ших безвозме́здноє врачева́ніє;","ра́дуйся, душ на́ших спасе́ніє.","Ра́дуйся, Богоро́дице Одиги́тріє, христия́н упова́ніє."]},{"h":"Кондак 13","ps":["О, Всепі́тая Ма́ти, Цари́це Всеми́лостивая Ді́во Богоро́дице Одиги́тріє! Прийми́ ма́лоє сіє́ моле́ніє на́ше і принеси́ є Си́ну Твоєму́ і Бо́гу на́шему, Ма́терне умоля́я Єго́ бла́гость, да поми́луєть нас грі́шних і недосто́йних, і Твоєго́ ра́ди всеси́льнаго хода́тайства ізба́вить нас муче́нія ві́чнаго, сподо́бит Ца́рствіє Небе́сноє получи́ти і та́мо со а́нгели воспіва́ти Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Арха́нгельський глас вопіє́м Ті, Чи́стая: ра́дуйся, Благода́тная Одиги́тріє Марі́є, і ра́дости духо́вния іспо́лни нас, да благогові́йною душе́ю і чи́стим се́рдцем принесе́м Ті, ро́ждшей ми́ру Спаси́теля Христа́ Бо́га на́шего, глаго́ли сія́:","Ра́дуйся, Бо́га Отця́ благоволе́нієм осіне́нная;","ра́дуйся, Бо́га Си́на Ма́ти неіскусобра́чная.","Ра́дуйся, Бо́га Ду́ха Свята́го оби́тель свяще́нная;","ра́дуйся, Тро́їчеськия та́йни проявле́ніє.","Ра́дуйся, а́нгельських умо́в удивле́ніє;","ра́дуйся, челові́чеськаго ро́да украше́ніє.","Ра́дуйся, го́рняя с до́льними совокупи́вшая;","ра́дуйся, врата́ ра́йськия земноро́дним отве́рзшая.","Ра́дуйся, лі́ствице небе́сная;","ра́дуйся, ста́мно Богоприї́мная.","Ра́дуйся, купино́ неопали́мая;","ра́дуйся, трапе́зо пресвята́я.","Ра́дуйся, Богоро́дице Одиги́тріє, христия́н упова́ніє."]},{"h":"Кондак 1","ps":["Ізбра́нній от всіх родо́в, небесі́ і землі́ Цари́це, Пресвяті́й Богоро́дице Одиги́трії, я́ко ізба́вльшеся от ві́чния сме́рти благода́тію от Тебе́ ро́ждшагося Христа́ Бо́га на́шего і Твої́м Ма́тернім пред Ним хода́тайством, благода́рственноє пі́ніє прино́сим Ті, раби́ Твої́. Ти же, Всеми́лостивая на́ша Засту́пнице, от вся́ких нас бід і ско́рбних обстоя́ній свобожда́й і к ца́рствію го́рнему путево́дствуй, да зове́м Ті:","Ра́дуйся, Богоро́дице Одиги́тріє, христия́н упова́ніє."]},{"h":"Молитва","ps":["О, Пречу́дная і Преви́шшая всіх тва́рей Цари́це Богоро́дице, Небе́снаго Царя́ Христа́ Бо́га на́шего Ма́ти, Пресвята́я Одиги́тріє Марі́є! Усли́ши нас грі́шних і недосто́йних, в час сей моля́щихся і к Тебі́ со воздиха́нієм і слеза́ми пред пречи́стим Твої́м о́бразом припа́дающих і си́це уми́льно глаго́лющих: ізведи́ нас от ро́ва страсте́й, Одиги́тріє блага́я, ізба́ви нас от вся́кия ско́рби і печа́лі, огради́ от вся́кия напа́сти і зли́я клевети́, і от непра́веднаго наві́та вра́жия. Мо́жеши бо, о Благода́тная Ма́ти на́ша, от вся́каго зла сохрани́ти лю́ди Твоя́, і вся́ким благодія́нієм снабди́ти і спасти́, ра́зві бо Тебе́ іни́я Предста́тельниці в біда́х і обстоя́ніїх і те́плия Хода́тайці о нас грі́шних к Си́ну Твоєму́, Христу́ Бо́гу на́шему, не і́мами. Єго́же умоли́, Влади́чице, спасти́ нас і Ца́рствія Небе́снаго сподо́бити, да спасе́ннії Тобо́ю сла́вим Тя і в бу́дущем ві́ці, я́ко же спасе́нія на́шего Вино́вницю, і превозно́сим всесвято́є і великолі́поє і́м'я Отця́ і Си́на і Свята́го Ду́ха, в Тро́йці сла́вимаго і поклоня́ємаго Бо́га во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["Ко кому́ возопію́, Влади́чице? Ко кому́ прибі́гну в го́ресті моє́й, а́ще не к Тебі́, Госпоже́ Влади́чице Богоро́дице, Цари́це Небе́сная? Кто плач мой і воздиха́ніє моє́ при́йметь, а́ще не Ти, о Пренепоро́чная, наде́ждо христия́н і прибі́жище грі́шним? Приклони́, о Пречи́стая Влади́чице, ушеса́ Твоя́ к моле́нію моєму́. Ма́ти Бо́га моєго́, не пре́зри м'я, тре́бующа Твоєя́ по́мощі, усли́ши стена́ніє моє́ і вопль се́рдця моєго́ внуши́, о Госпоже́ Богоро́дице Цари́це. І пода́ждь мі ра́дость душе́вную, подкріпи́ м'я нетерпіли́ваго, уни́лаго і неради́ваго к Твоєму́ хвале́нію. Вразуми́ і научи́ м'я, ка́ко Тебі́ моли́тися подоба́єть, і не отступи́ от мене́, Ма́ти Бо́га моєго́, за ропта́ніє і нетерпі́ніє моє́, но бу́ди мі покро́в і заступле́ніє в жи́зні моє́й і приведи́ м'я к ти́хому приста́нищу блаже́ннаго о́наго поко́я, і сопричти́ м'я к ли́ку ізбра́ннаго Твоєго́ ста́да і та́мо удосто́й м'я воспіва́ти і сла́вити Тя во ві́ки. Амі́нь."]},{"h":"Тропар, глас 4","ps":["К Богоро́диці прилі́жно ни́ні притеце́м, / грі́шнії і смире́ннії, і припаде́м, / в покая́нії зову́ще із глубини́ душі́: / Влади́чице, помози́, на ни милосе́рдовавши, / потщи́ся, погиба́єм от мно́жества прегріше́ній, / не отврати́ Твоя́ раби́ тщи, // Тя бо і єди́ну наде́жду і́мами."]},{"h":"Кондак, глас 6","ps":["Предста́тельство христия́н непости́дноє, / хода́тайство ко Творцю́ непрело́жноє, / не пре́зри грі́шних моле́ній гла́си, / но предвари́, я́ко Блага́я, на по́мощ нас, / ві́рно зову́щих Ті: / ускори́ на моли́тву і потщи́ся на умоле́ніє, // предста́тельствующи при́сно, Богоро́дице, чту́щих Тя."]},{"h":"Інший кондак, глас 6","ps":["Не і́мами іни́я по́мощі, / не і́мами іни́я наде́жди, / ра́зві Тебе́, Влади́чице, / Ти нам помози́, / на Тебі́ наді́ємся / і Тобо́ю хва́лимся, / Твої́ бо єсьми́ раби́, // да не постиді́мся."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Богоізбра́нная Отрокови́це, і чтем о́браз Твой святи́й, і́мже то́чиши ісціле́нія всім с ві́рою притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Всіх скорботних Радість»","e":"Akathist to the Theotokos before her icon “Joy of All Who Sorrow”","secs":[{"h":"Кондак 1","ps":["Взбра́нней Воєво́ді побіди́тельная, я́ко ізба́вльшеся от ві́чния сме́рти благода́тію от Тебе́ ро́ждшагося Христа́ Бо́га на́шего і Твої́м ма́тернім пред Ним хода́тайством, благода́рственная воспису́єм Ті, раби́ Твої́: я́ко іму́щая держа́ву непобіди́мую, от вся́ких нас бід і ско́рбних обстоя́ній свободи́, зову́щих:","Ра́дуйся, Благода́тная Богоро́дице Ді́во, всіх скорб'я́щих Ра́досте."]},{"h":"Ікос 1","ps":["А́нгел предста́тель по́слан бисть с Небесе́ рещи́ Богоро́дице: ра́дуйся, возвіща́я Боже́ственним воплоще́нієм Христо́вим хотя́щую роди́тися от Нея́ Ра́дость всему́ ми́ру, в ско́рбі погиба́ющу. Ті́мже і ми, гріхми́ обремене́ннії, наде́жду спасе́нія в Тебі́ улучи́вше, уми́льно взива́єм Ті:","Ра́дуйся, Бо́жиє ко грі́шним благоволе́ніє;","ра́дуйся, ка́ющихся пред Го́сподом Бо́гом крі́пкоє заступле́ніє.","Ра́дуйся, па́дшаго Ада́ма воззва́ніє;","ра́дуйся, слез Є́виних ізбавле́ніє.","Ра́дуйся, гріхо́вную от'є́млющая скве́рну;","ра́дуйся, ба́не, омива́ющая со́вість.","Ра́дуйся, ро́ждшая Ізба́вителя, беззако́нія на́ша ту́не очища́ющаго;","ра́дуйся, всечу́дноє всіх к Бо́гу примире́ніє.","Ра́дуйся, мо́сте, воі́стину преводя́й нас от сме́рти к животу́;","ра́дуйся, мир от пото́па гріхо́внаго спа́сшая.","Ра́дуйся, лі́ствице небе́сная, Є́юже Госпо́дь к нам сни́де;","ра́дуйся, вина́ всіх обоже́нія.","Ра́дуйся, Благода́тная Богоро́дице Ді́во, всіх скорб'я́щих Ра́досте."]},{"h":"Кондак 2","ps":["Ви́дяще то́ки чуде́с, ізлива́ємия от святи́я Твоєя́ іко́ни, блага́я Богороди́тельнице, я́ко Ти єси́ моля́щихся блага́я помо́щниця, оби́димих засту́пниця, ненаді́ющихся наде́жда, печа́льних утіше́ніє, а́лчущих корми́тельниця, наги́х одія́ніє, ді́вственних целому́дріє, стра́нних наста́вниця, тружда́ющихся по́мощ, сліпи́х прозрі́ніє, глухи́х благосли́шаніє, больни́х ісціле́ніє, благода́рственні вопіє́м о Тебі́ Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум недоразумі́нний находя́щих на ни лю́тих скорбе́й разумі́ти і́щуще, к Тебі́ прибіга́єм, о Ма́ти і Ді́во, утіше́нія тре́бующе. Ти же, Я́ко блага́я, научи́ ни разумі́ти в них блага́го Си́на Твоєго́ милосе́рдоє промишле́ніє во спасе́ніє душ на́ших і очище́ніє мно́гих согріше́ній, да взива́єм Ті ра́достно:","Ра́дуйся, обурева́ємих ти́хоє приста́нище;","ра́дуйся, сумня́щихся ізві́стноє утвержде́ніє.","Ра́дуйся, єди́на Ма́ти милосе́рдія;","ра́дуйся, ско́рая помо́щнице су́щим в біда́х і напа́стіх.","Ра́дуйся, скорбми́ гріхи́ на́ша очища́ющая;","ра́дуйся, печа́лію на́ша не́мощі душе́вния врачу́ющая.","Ра́дуйся, су́єтния ра́дости ми́ра сего́ презира́ти нас науча́ющая;","ра́дуйся, от ми́ра к преми́рним ум наш возводя́щая.","Ра́дуйся, от любве́ земни́я к небе́сній Бо́жієй любві́ нас привлека́ющая;","ра́дуйся, в са́мих страда́ніях на́ших утіше́ніє і благода́тную жизнь нам подаю́щая.","Ра́дуйся, обітова́ніє благ ві́чних;","ра́дуйся, Хода́тайце ві́чния ра́дости.","Ра́дуйся, Благода́тная Богоро́дице Ді́во, всіх скорб'я́щих Ра́досте."]},{"h":"Кондак 3","ps":["Си́лою сви́ше укріпи́ м'я, блага́я Влади́чице, неду́гующа ті́лом і душе́ю, і посіще́нія Твоєго́ сподо́би і промишле́нія, мрак уни́нія і ско́рби, облежа́щий м'я, отгоня́юще, да спаса́ємий Тобо́ю, непреста́нно вопію́ Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи бога́тство милосе́рдія неізрече́нноє, всім скорб'я́щим ру́ку по́мощі простира́єши, неду́ги врачу́ющи, стра́сті ісціля́ющи. Не пре́зри і мене́, блага́я Влади́чице, на одрі́ не́мощі моєя́ низлежа́ща і вопію́ща Ті:","Ра́дуйся, ми́лости сокро́вище многоці́нноє;","ра́дуйся, отча́янних єди́на наде́ждо.","Ра́дуйся, ті́ла моєго́ врачева́ніє;","ра́дуйся, душі́ моєя́ спасе́ніє.","Ра́дуйся, тве́рдая крі́посте немощни́х;","ра́дуйся, ізнемога́ющих засту́пнице і укріпле́ніє.","Ра́дуйся, гнів Бо́жий Твої́м моле́нієм ско́ро утоля́ющая;","ра́дуйся, стра́сті на́ша си́лою моли́тв Твої́х укроща́ющая.","Ра́дуйся, сліпи́х зрі́ніє, глухи́х сли́шаніє;","ра́дуйся, хроми́х хожде́ніє, німи́х глаго́ланіє.","Ра́дуйся, боля́щих благонаде́жноє посіще́ніє;","ра́дуйся, Я́ко Тобо́ю по мі́рі ві́ри подаю́ться благода́тная ісціле́нія всім немощству́ющим.","Ра́дуйся, Благода́тная Богоро́дице Ді́во, всіх скорб'я́щих Ра́досте."]},{"h":"Кондак 4","ps":["Бу́ря мно́гих бід і напа́стей обдержи́ть м'я, і волне́нія не ктому́ терплю́: Ти же, Я́ко ми́лостивая Ма́ти Спа́са моєго́ і Бо́га, воздви́гни ру́ці к Си́ну Твоєму́, моля́щи Єго́, да при́зрить на лю́тую скорб се́рдця моєго́ і воздви́гнеть м'я із пучи́ни отча́янія, вопію́щаго Єму́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шащи, Пресвята́я Ді́во і Ма́ти, Симео́на пра́веднаго прорече́ніє: Тебі́ же Само́й ду́шу про́йдеть ору́жіє, слага́ла єси́ в се́рдці Твоє́м вся глаго́ли сія́, разуміва́ющи, я́ко ра́дость ма́терняго се́рдця о ча́діх мно́гих печа́лей в ми́рі сем бива́єть прича́стна. Ті́мже, я́ко іскуше́нней по вся́чеським і спострада́ти ма́терней ско́рби могу́щей, взива́єм Ті:","Ра́дуйся, ра́дость ми́ру Христа́ Спаси́теля ро́ждшая;","ра́дуйся, мир от скорбе́й ізбавля́ющая.","Ра́дуйся, хуле́нія і клевети́ на Си́на Твоєго́ терпе́вшая;","ра́дуйся, страда́нієм Єго́ спострада́вшая.","Ра́дуйся, ско́рбних ма́терей утіше́ніє;","ра́дуйся, чад їх благода́тноє охране́ніє.","Ра́дуйся, в біда́х ско́роє нам заступле́ніє;","ра́дуйся, заблу́ждших ісправле́ніє.","Ра́дуйся, младе́нцев пита́ніє;","ра́дуйся, ю́них наставле́ніє.","Ра́дуйся, Ма́ти сиротству́ющих;","ра́дуйся, вдов заступле́ніє.","Ра́дуйся, Благода́тная Богоро́дице Ді́во, всіх скорб'я́щих Ра́досте."]},{"h":"Кондак 5","ps":["Богото́чную Кров Си́на Твоєго́, на Кресті́ за спасе́ніє на́ше ізлива́ємую, зря́щи, я́ко Раба́ Госпо́дня, смире́нно во́лі Отця́, І́же на небесі́х, повину́ющаяся, нам о́браз злострада́нія і терпі́нія яви́ла єси́, да і ми, в пещі́ іскуше́ній і бід су́щії, вопіє́м смире́нно Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дя Тя Син Твой і Бог при Кресті́ стоя́щую с возлю́бленним ученико́м і се́рдцем Єму́ сраспина́ющуюся, глаго́лаше: Же́но, се син Твой, і ученику́: се, Ма́ти твоя́, всиновля́я Тебі́ вся ве́рующия в Него́. Ми же, я́ко о́бщници ско́рби і страда́ній Си́на Твоєго́, імі́юще в Тебі́ благу́ю Ма́тер, на Тя все упова́ніє в ско́рбі возлага́юще, вопіє́м Ті:","Ра́дуйся, Ма́ти ро́да христия́нськаго;","ра́дуйся, усинови́вшая нас при Кресті́ Си́на Твоєго́.","Ра́дуйся, Бо́га с челові́ки соєдини́вшая;","ра́дуйся, ві́рних Го́сподеві сочета́вшая.","Ра́дуйся, А́гнице, ро́ждшая А́гнця, взе́мшаго гріхи́ ми́ра;","ра́дуйся, ча́ше, че́рплющая нам ра́дость от Істо́чника безсме́ртія.","Ра́дуйся, спору́чнице спасе́нія грі́шних;","ра́дуйся, взиска́ніє поги́бших.","Ра́дуйся, неча́янная грі́шних ра́досте;","ра́дуйся, па́дших воста́ніє.","Ра́дуйся, ціли́тельнице всіх не́мощей;","ра́дуйся, утоле́ніє вся́кия печа́лі.","Ра́дуйся, Благода́тная Богоро́дице Ді́во, всіх скорб'я́щих Ра́досте."]},{"h":"Кондак 6","ps":["Пропові́дують ми́лості Твоя́, Богома́ти, всі конці́ вселе́нния, і́бо честни́м покро́вом Твої́м покрива́єши весь род христия́нський, о не́мже непреста́нно мо́лишися Христу́ Спаси́телю на́шему і ізбавля́єши от всіх бід благонра́вния і богобоя́щіяся раби́, ві́рно вопію́щия Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ благода́ть світоза́рная от пречу́дния іко́ни Твоєя́, Богома́ти, пред не́юже со слеза́ми припа́дающе, мо́лим Ті ся: отжени́ о́блак наше́дших на ни іскуше́ній, да вопіє́м Ті ра́достно:","Ра́дуйся, принося́щая к Си́ну Твоєму́ і Бо́гу моле́нія ві́рних;","ра́дуйся, і Сама́ у Престо́ла Си́на Твоєго́ непреста́нно моля́щаяся о нас.","Ра́дуйся, предста́тельнице к Бо́гу, мир от бід спаса́ющая;","ра́дуйся, засту́пнице ро́да христия́нськаго, от Бо́га нам дарова́нная.","Ра́дуйся, дре́во благосінноли́ственноє, і́мже покрива́ються мно́зі;","ра́дуйся, дре́во світлоплодови́тоє, і́мже пита́ються ві́рнії.","Ра́дуйся, покро́ве ми́ру, ши́рший о́блака;","ра́дуйся, земле́ обітова́нія, із нея́же тече́ть мед і млеко́.","Ра́дуйся, сві́тлий о́блаче, ві́рния непреста́нно освеща́ющий;","ра́дуйся, сто́лпе о́гненний, наставля́яй ізбра́нния к небе́сному наслі́дію.","Ра́дуйся, ни́во, растя́щая оби́ліє щедро́т;","ра́дуйся, пода́тельнице вся́кия бла́гости.","Ра́дуйся, Благода́тная Богоро́дице Ді́во, всіх скорб'я́щих Ра́досте."]},{"h":"Кондак 7","ps":["Хотя́щи яви́ти то́ки чуде́с от Своєя́ іко́ни, Всіх скорб'я́щих Ра́дости, повелі́ла єси́, Влади́чице, боля́щей Євфи́мії моле́бная пі́нія пред то́ю соверша́ти, і получи́вши ісціле́ніє, всім пропові́дати ми́лости, ра́ди тоя́ іко́ни явле́нния, да не сокри́т бу́деть істо́чник благода́тних ізцеле́ній всім тре́бующим. Ті́мже і ми не таї́м Твої́х благодія́ній, но благода́рственні прославля́юще Бо́га, вопіє́м Єму́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вая купі́ль Силоа́мськая па́че о́ния дре́внія яви́ся, Пречи́стая Влади́чице, храм Твой, в не́мже покланя́ємся чудотво́рній іко́ні Твоє́й: І́бо не єди́ною в лі́то і то́кмо пе́рвіє входя́щим здра́віє ті́ла подає́ши, но всегда́ вся́кий неду́г і вся́кую я́зву душе́вную і тіле́сную врачу́єши с ві́рою і любо́вію к Тебі́ прибіга́ющих. Сего́ ра́ди вопіє́м Ті:","Ра́дуйся, купі́ль, в не́йже вся ско́рбі на́ша погружа́ються;","ра́дуйся, ча́ше, Є́юже ра́дость і спасе́ніє восприє́млем.","Ра́дуйся, ка́меню, напої́вший жа́ждущия жи́зні;","ра́дуйся, дре́во, услажда́ющеє сла́ния води́ жите́йськаго мо́ря.","Ра́дуйся, животво́рния води́ неістощи́мий істо́чниче;","ра́дуйся, ба́не, омива́ющая гріхо́вную скве́рну.","Ра́дуйся, скорбе́й на́ших услажде́ніє;","ра́дуйся, печа́лей на́ших утоле́ніє.","Ра́дуйся, болі́зней на́ших врачева́ніє;","ра́дуйся, бід ізбавле́ніє.","Ра́дуйся, де́монов попра́ніє;","ра́дуйся, враго́в посрамле́ніє.","Ра́дуйся, Благода́тная Богоро́дице Ді́во, всіх скорб'я́щих Ра́досте."]},{"h":"Кондак 8","ps":["Стра́нници і прише́льці всі єсьми́ на землі́ сей, по глаго́лу апо́столову: біди́ от враго́в, біди́ от сро́дник, біди́ от лжебра́тії терп'я́ще в лише́ніїх мно́гих і ско́рбіх. Ти же, Влади́чице, Я́ко Блага́я Одиги́тріє, наста́ви нас к ти́хому приста́нищу, і моли́ Си́на Твоєго́ проще́нію прегріше́ній нам пре́жде конця́ дарова́тися, да непреста́нно вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Все житіє́ на́ше на землі́ болі́зненно і печа́лі іспо́лнено от клевети́, досажде́нія, укоре́нія і іни́х многови́дних бід і напа́стей: немощству́єть бо ті́ло, ізнемога́єть і дух наш. К Тебі́ у́бо прибіга́єм, Богома́ти, пред пречи́стою іко́ною Твоє́ю припа́дающе, іспо́лни ра́дости і весе́лія ско́рбная сердця́ на́ша, да вопіє́м Ті:","Ра́дуйся, путеводи́тельнице, к небе́сному оте́честву нас руководя́щая;","ра́дуйся, Цари́це не́ба і землі́, врата́ ра́йськая нам отверза́ющая.","Ра́дуйся, ми́лостивая, нас ми́лующая;","ра́дуйся, домострої́тельнице, житіє́ на́ше до́брі устроя́ющая.","Ра́дуйся, руно́ ороше́нноє, є́же Гедео́н предви́ді;","ра́дуйся, блаже́нноє чре́во, невмісти́маго всі́ми Бо́га вмісти́вшеє.","Ра́дуйся, неопали́мая купино́;","ра́дуйся, неруши́мая стіно́.","Ра́дуйся, живоно́сний істо́чниче;","ра́дуйся, цві́те неув'яда́ємий.","Ра́дуйся, ум'ягче́ніє серде́ць злих;","ра́дуйся умиле́ніє благи́х.","Ра́дуйся, Благода́тная Богоро́дице Ді́во, всіх скорб'я́щих Ра́досте."]},{"h":"Кондак 9","ps":["Вся́кая жите́йськая в ми́рі сем сла́дость печа́лі бива́єть прича́стна: сла́ва не стої́ть, бога́тство мимотече́ть, лі́пота і здра́віє ув'яда́ють, дру́зі і і́скреннії сме́ртію от'є́млються. Услади́ у́бо на́ша ско́рби, благи́х вино́вная, Твою́ нетлі́нную даю́щи ра́дость нам, вопію́щим Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії многовіща́ннії недоумі́ють, ки́їми словеси́ скорб'я́щия утіша́ти, но Сама́, Влади́чице, возглаго́ли сердця́м на́шим утіше́ніє, благода́ті Твоєя́ луча́ми о́блак ско́рби на́шея і мрак уни́нія разгоня́ющи, да взива́єм Ті:","Ра́дуйся, обра́довавшая наді́янієм на Тя всіх христия́н;","ра́дуйся, ра́досте і умире́ніє ми́ру.","Ра́дуйся, пода́тельнице Боже́ственния бла́гости;","ра́дуйся, наде́ждо благ ві́чних.","Ра́дуйся, кораблю́ хотя́щих спасти́ся;","ра́дуйся, приста́нище жите́йських пла́ваній.","Ра́дуйся, ві́рная храни́тельнице упова́ющих на Тя по Бо́зі;","ра́дуйся, оде́ждо наги́х дерзнове́нія.","Ра́дуйся, храни́тельнице всіх і утвержде́ніє;","ра́дуйся, всіх ві́рних огражде́ніє і свяще́нноє прибі́жище.","Ра́дуйся, по́моще ві́рно моля́щихся Тебі́;","ра́дуйся, сві́тлоє благода́ті позна́ніє.","Ра́дуйся, Благода́тная Богоро́дице Ді́во, всіх скорб'я́щих Ра́досте."]},{"h":"Кондак 10","ps":["Спасти́ хотя́й род челові́чеський от ві́чния му́ки і непрестаю́щия ско́рби, Человіколю́бець Госпо́дь в присноді́вственную утро́бу Твою́ всели́ся і Тебі́, Ма́тер Свою́, дарова́ погиба́ющим в по́мощ, покро́в і защище́ніє, да бу́деши печа́льним утіше́ніє, скорб'я́щим ра́дованіє, отча́янним наде́жда, ві́чния му́ки Свої́м хода́тайством ізбавля́ющая і к небе́сному весе́лію приводя́щая всіх, ві́рно вопію́щих Си́ну Твоєму́ і Бо́гу на́шему: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ ді́вам, Богоро́дице Ді́во, і всім к Твоєму́ покро́ву прибега́ющим. Ті́мже мо́лим Тя: заступи́, покри́й і соблюди́ всіх си́рих і безпомо́щних от іскуше́ній, озлобле́ній і бід, Тебі́ с любо́вію взива́ющих:","Ра́дуйся, сто́лпе ді́вства;","ра́дуйся, чистоти́ і цілому́дрія сосу́де ізбра́нний.","Ра́дуйся, во́їнствующим на плоть цілому́дрієм ізря́дноє вінча́ніє;","ра́дуйся, во і́ночестві благоскорб'я́щим пода́тельнице ві́чнаго ра́дованія.","Ра́дуйся, пла́мень страсте́й ізміня́ющая;","ра́дуйся, мрак іскуше́ній прогоня́ющая.","Ра́дуйся, наста́внице цілому́дрія;","ра́дуйся, чистоти́ огражде́ніє.","Ра́дуйся, челові́ков ісправле́ніє;","ра́дуйся, Є́юже от паде́нія воста́хом.","Ра́дуйся, тве́рдоє ві́ри утвержде́ніє;","ра́дуйся, прия́тноє моли́тви кади́ло.","Ра́дуйся, Благода́тная Богоро́дице Ді́во, всіх скорб'я́щих Ра́досте."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє прино́сим Ті, раби́ Твої́, Богоро́дице, я́ко всеси́льній засту́пнице ро́да на́шего: утоли́ болі́зні многовоздиха́ющих душ на́ших, укроти́ гнів Бо́жий, пра́ведно на ни дви́жимий гріх ра́ди на́ших, ізба́ви нас от вся́кия лю́тия ско́рби і болі́зні, вопію́щих о Тебі́ Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоприє́мная свіща́, у́глем благода́ті Бо́жия возжже́нная, яви́ся нам пречестна́я іко́на Твоя́, Влади́чице, на освяще́ніє на́ше і утіше́ніє. Ми же, любо́вію чту́ще ю і с ві́рою припа́дающе к ней, вопіє́м Ті:","Ра́дуйся, си́льним Твої́м заступле́нієм от всіх бід нас ізбавля́ющая;","ра́дуйся, от тру́са і пото́па нас защища́ющая.","Ра́дуйся, от гла́да душе́внаго і тіле́снаго нас снабдіва́ющая;","ра́дуйся, огнь росо́ю моли́тв Твої́х угаша́ющая.","Ра́дуйся, от сме́ртнаго губи́тельства нас спаса́ющая;","ра́дуйся, в бра́ніх крі́пкая помо́щнице.","Ра́дуйся, от наше́ствія іноплеме́нних нас огражда́ющая;","ра́дуйся, от междоусо́бния бра́ні охраня́ющая.","Ра́дуйся, пла́вающих ле́гкоє по вода́м прехожде́ніє;","ра́дуйся, путеше́ствующих до́брая води́тельнице.","Ра́дуйся, плі́нних свобожде́ніє;","ра́дуйся, от належа́щаго пра́веднаго преще́нія Бо́жия ско́роє ізбавле́ніє.","Ра́дуйся, Благода́тная Богоро́дице Ді́во, всіх скорб'я́щих Ра́досте."]},{"h":"Кондак 12","ps":["Благода́ті зало́г восхоті́вши да́ти ро́ду на́шему, цільбоно́сную іко́ну Твою́ яви́ла єси́ нам, Богома́ти, от нея́же то́ки чуде́с с ві́рою приходя́щим істоча́ються, неду́зі врачу́ються і ско́рби утоля́ються. Сего́ ра́ди ра́достно о Тебі́ вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Твоя́ ми́лості і чудеса́, Богороди́тельнице, хва́лим Тя всі, я́ко тве́рдую предста́тельницю на́шу, і со умиле́нієм покланя́ємся Тебі́, моля́щейся о нас, і про́сим: воздви́гни ру́ці к Си́ну Твоєму́, да всегда́ в сей жи́зні і по сме́рті на́шей милосе́рдіє Єго́ неотсту́пно бу́деть от нас, взива́ющих Ті:","Ра́дуйся, непости́дноє на́ше упова́ніє в животі́ і по преставле́нії на́шем;","ра́дуйся, упова́ющим на Тя ми́рен коне́ць житія́ сего́ подаю́щая.","Ра́дуйся, в день су́дний на́ша наде́ждо і защище́ніє;","ра́дуйся, Судії́ пра́веднаго умоле́ніє.","Ра́дуйся, геє́нни ві́чния ізбавле́ніє;","ра́дуйся, наде́ждо ві́чнаго спасе́нія.","Ра́дуйся, ключу́ Ца́рствія Христо́ва;","ра́дуйся, две́ре ра́йськая.","Ра́дуйся, мо́сте, к небесе́м приводя́й;","ра́дуйся, всіх ка́ющихся грі́шников прибі́жище і блага́я засту́пнице.","Ра́дуйся, А́нгелов ра́досте;","ра́дуйся, всіх пра́ведних сла́во і утіше́ніє.","Ра́дуйся, Благода́тная Богоро́дице Ді́во, всіх скорб'я́щих Ра́досте."]},{"h":"Кондак 13","ps":["О Всепі́тая Богообра́дованная Ма́ти, ро́ждшая на ра́дость не́бу і землі́ Царя́ Христа́, Бо́га на́шего! Усли́ши глас скорб'я́щих раб Твої́х, і приє́мши сіє́ ма́лоє моле́ніє на́ше, ізба́ви нас от вся́ких бід, скорбе́й і напа́стей; неду́ги на́ша ісціли́, напра́сния клевети́ потреби́, вся́ку зло́бу і вражду́ отжени́ от нас і бу́дущия ізми́ му́ки о Тебі́ вопію́щих: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел предста́тель по́слан бисть с Небесе́ рещи́ Богоро́дице: ра́дуйся, возвіща́я Боже́ственним воплоще́нієм Христо́вим хотя́щую роди́тися от Нея́ Ра́дость всему́ ми́ру, в ско́рбі погиба́ющу. Ті́мже і ми, гріхми́ обремене́ннії, наде́жду спасе́нія в Тебі́ улучи́вше, уми́льно взива́єм Ті:","Ра́дуйся, Бо́жиє ко грі́шним благоволе́ніє;","ра́дуйся, ка́ющихся пред Го́сподом Бо́гом крі́пкоє заступле́ніє.","Ра́дуйся, па́дшаго Ада́ма воззва́ніє;","ра́дуйся, слез Є́виних ізбавле́ніє.","Ра́дуйся, гріхо́вную от'є́млющая скве́рну;","ра́дуйся, ба́не, омива́ющая со́вість.","Ра́дуйся, ро́ждшая Ізба́вителя, беззако́нія на́ша ту́не очища́ющаго;","ра́дуйся, всечу́дноє всіх к Бо́гу примире́ніє.","Ра́дуйся, мо́сте, воі́стину преводя́й нас от сме́рти к животу́;","ра́дуйся, мир от пото́па гріхо́внаго спа́сшая.","Ра́дуйся, лі́ствице небе́сная, Є́юже Госпо́дь к нам сни́де;","ра́дуйся, вина́ всіх обоже́нія.","Ра́дуйся, Благода́тная Богоро́дице Ді́во, всіх скорб'я́щих Ра́досте."]},{"h":"Кондак 1","ps":["Взбра́нней Воєво́ді побіди́тельная, я́ко ізба́вльшеся от ві́чния сме́рти благода́тію от Тебе́ ро́ждшагося Христа́ Бо́га на́шего і Твої́м ма́тернім пред Ним хода́тайством, благода́рственная воспису́єм Ті, раби́ Твої́: я́ко іму́щая держа́ву непобіди́мую, от вся́ких нас бід і ско́рбних обстоя́ній свободи́, зову́щих:","Ра́дуйся, Благода́тная Богоро́дице Ді́во, всіх скорб'я́щих Ра́досте."]},{"h":"Молитва","ps":["О Пресвята́я Влади́чице Богоро́дице, ви́шшая Херуви́м і честні́йшая Серафи́м, Богоізбра́нная Отрокови́це, всіх скорб'я́щих Ра́досте! Пода́ждь утіше́ніє і нам, в ско́рбі су́щим: ра́зві бо Тебе́ іно́го прибі́жища і по́мощі не і́мами. Ти єди́на єси́ ра́дости на́шея хода́тайця, і Я́ко Ма́тер Бо́жия і Ма́ти милосе́рдія, предстоя́щи у Престо́ла Пресвяти́я Тро́йці, мо́жеши нам помощі́: нікто́же бо притека́яй к Тебі́ посра́млен отхо́дить. Усли́ши у́бо і нас, ни́ні в день ско́рби пред Твоє́ю іко́ною припа́дающих і со слеза́ми Тебі́ моля́щихся: отжени́ от нас належа́щия на нас ско́рби і печа́лі в сей вре́менній жи́зні, не лише́ни же ни сотвори́ Твої́м всеси́льним хода́тайством і ві́чния несконча́ємия ра́дости в Ца́рствії Си́на Твоєго́ і Бо́га на́шего. Амі́нь."]},{"h":"Стихира, що співається замість тропаря, глас 2","ps":["Всіх скорб'я́щих Ра́досте, / і оби́димих Засту́пнице, / і а́лчущих Пита́тельнице, / стра́нних Утіше́ніє, / обурева́ємих Приста́нище, / больни́х посіще́ніє, / не́мощних покро́в і засту́пнице, / Жезл ста́рости, / Ма́ти Бо́га Ви́шняго Ти єси́, Пречи́стая: // потщи́ся, мо́лимся, спасти́ся рабо́м Твої́м."]},{"h":"Тропар, глас 8","ps":["Ко істо́чнику приснотеку́щему милосе́рдія, Пречи́стій Ді́ві Богоро́диці, / притеце́м, лю́діє всі, свяще́нници же і і́ноці, / му́жіє, і же́ни, і ча́да, здра́вії і боля́щії, / в покая́нії вопію́ще і уми́льно глаго́люще: / Влади́чице, помози́ грі́шним рабо́м Твої́м, / яви́ я́ко Блага́я сла́ву Твою́, / при́сно потщи́ся умилосе́рдитися на ни, / іспроси́ти очище́ніє душ і тіле́с на́ших / от Істо́чника жи́зні на́шея, Бо́га, // Єго́же родила́ єси́, єди́на Благослове́нная."]},{"h":"Кондак, глас 6","ps":["Не і́мами іни́я по́мощі, / не і́мами іни́я наде́жди, / ра́зві Тебе́, Влади́чице. / Ти нам помози́: / на Тебі́ наді́ємся і Тобо́ю хва́лимся, / Твої́ бо єсьми́ раби́, // да не постиді́мся."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Богоізбра́нная Отрокови́це, і чтем о́браз Твой святи́й, і́мже то́чиши ісціле́нія всім с ві́рою притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Знамення» Новгородська","e":"Akathist to the Theotokos before her icon “The Sign” of Novgorod","secs":[{"h":"Кондак 1","ps":["Взбра́нней Воєво́ді, Влади́чиці на́шей Богоро́диці, зна́менієм іко́ни Єя́ святи́я ди́вную побі́ду лю́дем Нова́града дарова́вшей, благода́рственноє возглаша́єм пі́ніє: Ти же Всеблага́я Засту́пнице на́ша, я́ко іму́щая держа́ву непобіди́мую, от вся́ких нас бід свободи́ і от враг ви́димих і неви́димих защити́, да зове́м Ті:","Ра́дуйся, Влади́чице, зна́меніє ми́лости Твоєя́ нам явля́ющая."]},{"h":"Ікос 1","ps":["А́нгелов Цари́це і всея́ тва́рі Влади́чице, Пречи́стая Ді́во Богоро́дице, пресла́вним зна́менієм іко́ни Твоєя́ святи́я всю страну́ Украї́нськую благода́тно озари́ла єси́ і струї́ чуде́с от нея́ істочи́ла єси́ ві́рним. Ті́мже, со усе́рдієм і любо́вію припа́дающе ко пречестно́му Твоєму́ о́бразу, со умиле́нієм прино́сим Ті благохвале́нія сицева́я:","Ра́дуйся, освяще́нноє селе́ніє Бо́га Сло́ва;","ра́дуйся, благода́тію Бо́жиєю і нас освяща́ющая.","Ра́дуйся, спасе́нію па́дшаго ро́да челові́чеськаго непоро́чно послужи́вшая;","ра́дуйся, всіх Творця́ і Го́спода, Чи́стая, Ду́хом Боже́ственним в ложесна́х заче́нши, без істлі́нія роди́вшая.","Ра́дуйся, ма́терним Твої́м попече́нієм всіх нас об'є́млющая;","ра́дуйся, в біда́х і напа́стіх ско́рая нам Помо́щнице.","Ра́дуйся, зли́я стра́сті на́ша неви́димо укроща́ющая;","ра́дуйся, в христия́нських доброді́теліх преуспіва́ти нам помога́ющая.","Ра́дуйся, неду́ги на́ша безме́здно врачу́ющая;","ра́дуйся, на стезі́ покая́нія нас прему́дро наставля́ющая.","Ра́дуйся, Ді́во, христия́н похвало́;","ра́дуйся, я́ко блажа́ть Тя всі ро́ди.","Ра́дуйся, Влади́чице, зна́меніє ми́лости Твоєя́ нам явля́ющая."]},{"h":"Кондак 2","ps":["Ви́дів озлобле́ніє Нова́града, крі́пці вою́ємаго от во́єв су́ждальських, святи́тель Христо́в Іоа́нн сле́зно моля́шеся о ізбавле́нії і спасе́нії гра́да і усли́ша глас сви́ше, да і́деть во храм Преображе́нія Госпо́дня і, взем та́мо іко́ну Пресвяти́я Богоро́диці, да ізнесе́ть ю на забра́ла гра́да проти́ву по́лчищ, єго́ вою́ющих. Таково́є велі́ніє Бо́жиє усли́шав, святи́тель благода́рственно возопи́ Спа́су Христу́: Аллилу́я."]},{"h":"Ікос 2","ps":["Разумі́во во́лю Бо́жию во гла́сі небе́снім, святи́тель Христо́в Іоа́нн при́йде ко хра́му Преображе́нія Госпо́дня взя́ти іко́ну Богома́тере і, єгда́ моля́шеся пред не́ю, подви́жеся іко́на от мі́ста своєго́ на ру́ці єго́ честни́я, і той с пі́нієм моле́бним ізнесе́ ю на забра́ла гра́да, глаго́ля наро́ду: дерза́йте, Ма́ти бо Бо́га на́шего с на́ми єсть. Сего́ ра́ди, ви́дівше Твоє́ к ним благоволе́ніє, в прише́ствії чуде́снім іко́ни Твоєя́ явле́нноє, в пі́сніх возглаша́єм благохвале́нія сицева́я:","Ра́дуйся, Наде́ждо христия́н ненаде́жних;","ра́дуйся, скорб'я́щих Ра́досте і Заступле́ніє.","Ра́дуйся, безпомо́щним ско́рую по́мощ Твою́ явля́ющая;","ра́дуйся, утесня́ємим осла́бу і свобо́ду да́рующая.","Ра́дуйся, правосла́вним во́єм Предводи́тельнице к побі́дам;","ра́дуйся, ра́тей неприя́тельських всекре́пкоє низложе́ніє.","Ра́дуйся, Вели́кий Но́вград благоволе́нієм Твої́м осіни́вшая;","ра́дуйся, на забра́ла єго́, я́ко Взбра́нная Воєво́да, во іко́ні Твоє́й прише́дшая.","Ра́дуйся, ненака́занних ми́лостивая Наказа́тельнице;","ра́дуйся, неразу́мних прему́драя Вразуми́тельнице.","Ра́дуйся, оби́дящих всегро́зная Устраши́тельнице;","ра́дуйся, оби́димих Всеблага́я Засту́пнице.","Ра́дуйся, Влади́чице, зна́меніє ми́лости Твоєя́ нам явля́ющая."]},{"h":"Кондак 3","ps":["Си́лою Бо́жиєю укріпле́н, святи́тель Христо́в Іоа́нн вознесе́ святу́ю іко́ну Твою́, Влади́чице Богоро́дице, посреді́ са́мия бра́ні, іді́же стрі́ли от сопроти́вних, я́ко дождь, па́даху, і єди́на от них честни́й лик Твой на іко́ні устріли́: а́біє же іко́на Твоя́ лик свой от полко́во вражде́бних отврати́ і сле́зи от оче́с істочи́, ї́хже собира́я во фело́нь свою́, святи́тель Христо́в Іоа́нн наро́дом дерза́ти повелі́, они́ же, я́ко крі́пка ні́коєго храни́теля іму́ще, на сопроти́вния устреми́шася і до конця́ побіди́ша тіх, зову́ще Го́споду Сил: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́яше Тя воі́стину Вели́кий Но́вград Воі́тельницю держа́вную, Богороди́тельнице Всеблага́я, єгда́ па́че наді́янія, зна́менієм іко́ни Твоєя́ святи́я побіди́ти си́льния полки́ сопроти́вних лю́дем Нова́града помогла́ єси́. Ті́мже пі́ніє побі́дноє Тебі́ принося́ще, взива́єм си́це:","Ра́дуйся, умире́ніє ми́ру святи́м Рождество́м Твої́м прине́сшая;","ра́дуйся, средості́ніє вражди́ дре́внія разруши́вшая.","Ра́дуйся, непра́ведно вражду́ющия наказу́ющая;","ра́дуйся, зна́меньми і чудеси́ Твої́ми христолюби́вия лю́ди утіша́ющая.","Ра́дуйся, от стріли́ вра́жія я́зву на лиці́ іко́ни Твоєя́ приє́мшая;","ра́дуйся, сле́зи благода́тния от нея́ ди́вно істочи́вшая.","Ра́дуйся, во́ї сопроти́вних сліпото́ю і бі́гством порази́вшая;","ра́дуйся, полки́ крі́пкия безси́льни соді́лавшая.","Ра́дуйся, во бра́ніх крі́пкая Помо́щнице;","ра́дуйся, враго́в посрамле́ніє.","Ра́дуйся, лю́ди Твоя́ ди́вною побі́дою увенча́вшая;","ра́дуйся, Непобіди́мая Воєво́до вожде́й і во́їнств христия́нських.","Ра́дуйся, Влади́чице, зна́меніє ми́лости Твоєя́ нам явля́ющая."]},{"h":"Кондак 4","ps":["Бу́ря недоумі́нія смуща́єть мі ум: ка́ко возмогу́ недосто́йними усти́ воспі́ти чудеса́ Твоя́, Богома́ти Влади́чице, я́же свято́ю іко́ною зна́менія Твоєго́ в Нові́граді яви́ла єси́, дарова́в ю в по́мощ і заступле́ніє всім правосла́вним лю́дем от враг ви́димих і неви́димих? Ті́мже, велича́юще неісче́тния ми́лості Твоя́ к нам, смиренному́дренні воспіва́єм просла́вльшему Тя Си́ну Твоєму́ і Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше о ди́внім чудеси́ святи́я іко́ни Зна́менія Твоєго́ в Нові́граді, Пречи́стая Ді́во, ка́ко лю́діє новогра́дстії, іму́ще сію́, си́лою Твоє́ю і посо́бієм Боже́ственнаго зра́ка Твоєго́ пресла́вноє одолі́ніє на сопроти́вния показа́ша, со благогові́нієм і ра́достію покланя́ємся сему́ чу́дному о́бразу Твоєму́ і хвале́бне зове́м Ті:","Ра́дуйся, Неві́сто Отця́ Безнача́льнаго;","ра́дуйся, неіскусобра́чная Роди́тельнице Преві́чнаго Сло́ва.","Ра́дуйся, селе́ніє прекра́сноє Ду́ха Свята́го;","ра́дуйся, Живонача́льния і Єдиносу́щния Тро́йці благода́тію осіне́нная.","Ра́дуйся, дре́вле проро́ки многообра́зні предрече́нная;","ра́дуйся, а́нгельськия собо́ри чистото́ю Твоє́ю превозше́дшая.","Ра́дуйся, челові́чеськаго ро́да возвише́ніє;","ра́дуйся, па́дших сино́в Ада́млих благода́тноє возста́ніє.","Ра́дуйся, я́ко із Тебе́ в плоть облече́ся Одіва́яй не́бо о́блаки;","ра́дуйся, я́ко млеко́м Твої́м пита́ла єси́ Пита́теля вселе́нния.","Ра́дуйся, Всеблагослове́нная Богоро́дице, Чи́стая Присноді́во;","ра́дуйся, Ра́досте на́ша і спасе́ніє душ на́ших.","Ра́дуйся, Засту́пнице на́ша, от Бо́га нам дарова́нная;","ра́дуйся, всіх ві́рних огражде́ніє і свяще́нноє прибі́жище.","Ра́дуйся, Влади́чице, зна́меніє ми́лости Твоєя́ нам явля́ющая."]},{"h":"Кондак 5","ps":["Богосві́тлая звізда́, іко́на Зна́менія Твоєго́, Богоро́дице Ді́во, Вели́кий Но́вград сія́нієм мно́гих чуде́с духо́вно просвіти́, неоску́дно істоча́ющи благода́тния ісціле́нія всім ві́рним, со усе́рдієм к ней притека́ющим. Не лиши́ і нас благода́тнаго Твоєго́ озаре́нія і милосе́рдих щедро́т Твої́х, боголі́пним поклоне́нієм честву́ющих чудотво́рную іко́ну Твою́, да благода́рственно воспіва́єм Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше чудеса́ пресла́вная, от іко́ни зна́менія Твоєго́ би́вшая, Влади́чице Преблага́я, лю́діє Нова́града со усе́рдієм к ней притека́ху і в неду́зіх свої́х ісціле́нія благода́тная от нея́ приє́мляху. К не́йже ни́ні приходя́ще, покланя́ємся, і честву́єм, і от жела́нія се́рдця цілу́єм, ісціле́ній благода́ть почерпа́юще, і неду́г тіле́сних, і душе́вних страсте́й свобожда́ємся, зову́ще Ті і глаго́люще:","Ра́дуйся, скорб'я́щих Ра́досте і оби́димих Засту́пнице;","ра́дуйся, печа́льних Утіше́ніє і бі́дствующих Помо́щнице.","Ра́дуйся, боля́щих немздоприї́мная Ціли́тельнице;","ра́дуйся, ни́щих і убо́гих некра́домоє бога́тство.","Ра́дуйся, терпіли́вих страда́льцев дара́ми благода́тними ущедря́ющая;","ра́дуйся, отча́янних і безнаде́жних от ро́ва поги́белі ізбавля́ющая.","Ра́дуйся, вдови́ць і си́рих благосе́рдая Попечи́тельнице;","ра́дуйся, цілому́дрія і воздержа́нія ю́них Наста́внице.","Ра́дуйся, ста́рцев благогові́йних сла́дкоє Успокоє́ніє;","ра́дуйся, ста́риць боголюби́вих ти́хоє Прибі́жище.","Ра́дуйся, ка́ющихся грі́шников ві́рная Спору́чнице;","ра́дуйся, даро́в духо́вних ще́драя Пода́тельнице.","Ра́дуйся, Влади́чице, зна́меніє ми́лости Твоєя́ нам явля́ющая."]},{"h":"Кондак 6","ps":["Пропові́дуєть Новгра́д пресла́вноє заступле́ніє Твоє́, Пречи́стая Влади́чице, ка́ко во дні наше́ствія враго́в си́льних і вооруже́нних от святи́я іко́ни Зна́менія Твоєго́ по́мощ Твою́ благода́тную лю́дем Твої́м дарова́ла єси́, вражде́бния полки́ со студо́м всп'ять обрати́ла єси́, град же Твой ціл і невреди́м от них сохра́нши, да всі пою́ть Спаси́телю Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ла єси́ луча́ми вели́ких чуде́с в Нові́граді, Богоро́дице Ді́во, і іко́ну Зна́менія Твоєго́ благода́тним істоче́нієм слез ди́вно просла́вила єси́, неісче́тния ми́лости от нея́ ще́дро подава́ющи всім скорб'я́щим і обремене́нним. Посіти́ у́бо і ду́ші на́ша, неду́гующия страстьми́ гріхо́вними, Госпоже́ Всеблага́я, і бу́ди нам Помо́щниця во спасе́ніє, да благода́рственно Тебі́ зове́м:","Ра́дуйся, Моли́твеннице благоприя́тная за нас к Бо́гу;","ра́дуйся, Предста́тельнице всемо́щная, гнів Бо́жий на ми́лость прелага́ющая.","Ра́дуйся, ру́ці Твої́ богоно́сне на умоле́ніє ко Творцю́ ви́ну простира́ющая;","ра́дуйся, я́ко Ма́ти Си́на, Судію́ Пра́веднаго, о всем ми́рі умоля́ющая.","Ра́дуйся, покро́вом ма́терняго Твоєго́ заступле́нія всіх нас покрива́ющая;","ра́дуйся, су́щих в біда́х і ско́рбіх благода́тію смире́нія і терпі́нія снабдіва́ющая.","Ра́дуйся, стра́ждущия і безпомо́щния неви́димо укріпля́ющая;","ра́дуйся, боля́щия і безнаде́жния от одра́ болі́зні возставля́ющая.","Ра́дуйся, ві́рою моля́щимся Тебе́ вели́кия ми́лости явля́ющая;","ра́дуйся, во благи́х проше́нія на́ша ди́вно ісполня́ющая.","Ра́дуйся, струї́ благода́тних ісціле́ній оби́льно нам істоча́ющая;","ра́дуйся, всім вся поле́зная да́рующая.","Ра́дуйся, Влади́чице, зна́меніє ми́лости Твоєя́ нам явля́ющая."]},{"h":"Кондак 7","ps":["Хотя́щи яви́ти, Влади́чице, не то́кмо Вели́кому Нову́граду, но і всему́ правосла́вному украї́нському жи́тельству пресла́вная чудеса́ Твоя́ от іко́ни Зна́менія Твоєго́, сію́ во мно́гих граді́х, оби́теліх і ве́сіх от літ дре́вніх до дній на́ших ди́вними чудеси́ просла́вила єси́, сліпи́м прозрі́ніє, разсла́бленним укріпле́ніє і мно́гим боля́щим ісціле́ніє ми́лостивно от нея́ да́рующи і сим подвиза́ющи лю́ди велича́ти Тя, возвели́чившую род наш, і пі́ти Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вград і всю зе́млю Украї́нськую ди́вная іко́на Зна́менія Твоєго́, Богоро́дице Ді́во, чудеси́ благода́тними осія́, ми́лості Твоя́ бога́тия ві́рним прояви́вши. Сію́ у́бо боголі́пним поклоне́нієм честву́юще, хвале́бно Тебе́, Влади́чице, взива́єм:","Ра́дуйся, скоропредста́тельная Помо́щнице усе́рдно к Тебі́ притека́ющих;","ра́дуйся, благосе́рдая Усли́шательнице моле́ній на́ших.","Ра́дуйся, Вели́кий Но́вград благослове́нієм Твої́м осіни́вшая;","ра́дуйся, в преді́ліх єго́ іко́ну Зна́менія Твоєго́ чудеси́ просла́вльшая.","Ра́дуйся, дів ликостоя́нія прославле́нієм іко́ни Твоєя́ духо́вно возвесели́вшая;","ра́дуйся, всеси́льними Твої́ми к Бо́гу моли́твами і нас ко блаже́нству ра́йському возводя́щая.","Ра́дуйся, вся страни́ правосла́вния покро́вом ми́лости Твоєя́ осіня́ющая;","ра́дуйся, мно́гих міст і оби́телей сокро́вище ісціле́ній неоску́дноє.","Ра́дуйся, і́ноков і і́нокинь благоподвиза́ющихся всемо́щная Покрови́тельнице;","ра́дуйся, і в ми́рі благоче́стно живу́щих усе́рдная Засту́пнице.","Ра́дуйся, веду́щим брань проти́ву ми́ра, пло́ті і дия́вола до́брая Споспі́шнице;","ра́дуйся, за всіх нас ми́лостивая к Си́ну Твоєму́ і Бо́гу Хода́тайце.","Ра́дуйся, Влади́чице, зна́меніє ми́лости Твоєя́ нам явля́ющая."]},{"h":"Кондак 8","ps":["Стра́нствующе в юдо́лі сей земно́й, многоско́рбней і многом'яте́жній, го́рняго гра́да, Ієрусали́ма Небе́снаго, взиску́єм і Тебі́, Влади́чице, мо́лим: путево́дствуй нам по стезі́ за́повідей Христо́вих і сохрани́ нас от паде́ній гріхо́вних, удиви́ на нас ми́лость Твою́ і осіни́ нас Твої́м заступле́нієм, да, Твоє́ю по́мощію спаса́ємі, сподо́бимся ку́пно со всі́ми святи́ми воспіва́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Всіх скорб'я́щих Уті́шительнице і бі́дствующих Помо́щнице, Всеблага́я Богороди́тельнице, не пре́зри нас, припа́дающих к Тебі́ пред пречи́стим о́бразом Твої́м, но посіти́ нас ми́лостивно щедро́тами Твої́ми: і, я́коже дре́вле отце́м на́шим по́мощ Твою́ держа́вную яви́ла єси́, та́ко і нас, смире́нних, не лиши́ Твоєго́ заступле́нія во вре́м'я благопотре́бно, да не постиди́мся во упова́нії на́шем, є́же по Бо́зі крі́пко на Тя возлага́єм, і зове́м Ті:","Ра́дуйся, богосві́тлая свіще́, сві́том Христо́вим озаря́ющая ві́рния ду́ші;","ра́дуйся, многоці́нний алава́стр, ми́ром Бо́жия благода́ті умаща́яй боголюби́вия сердца́.","Ра́дуйся, у́мнаго Со́лнця Ма́ти, ві́рния просвіща́ющаго, неві́рния же помрача́ющаго;","ра́дуйся, сла́во небе́сних і упова́ніє земни́х.","Ра́дуйся, Наде́ждо на́ша і Засту́пнице всіх притека́ющих к Тебі́ с ві́рою;","ра́дуйся, лю́б'ящия і чту́щия Тя от вся́ких бід ізбавля́ющая.","Ра́дуйся, обітова́нії благи́ми ду́ші ві́рних благода́тно веселя́щая;","ра́дуйся, ді́вственних лико́в сла́во і похвало́.","Ра́дуйся, подви́жников благоче́стія ко го́рнему Сіо́ну путево́дствующая;","ра́дуйся, ві́рних к Небе́сному Ієрусали́му приводя́щая.","Ра́дуйся, омраче́нния сердца́ сві́том і́стиннаго богові́дінія просвіща́ющая;","ра́дуйся, і всіх нас благода́тними луча́ми вели́кия Своєя́ ми́лості покрива́ющая.","Ра́дуйся, Влади́чице, зна́меніє ми́лости Твоєя́ нам явля́ющая."]},{"h":"Кондак 9","ps":["Вся а́нгельськия во́їнства благогові́йно Тебі́ слу́жать, небесе́ і землі́ Цари́це, челові́чеський же род немо́лчния хвали́ Тебі́ прино́сить, го́рних і до́льних Влади́чице, і Твою́ святу́ю іко́ну поклоне́нієм досточе́стним почита́єть. Сію́ бо во отра́ду і утіше́ніє нам дарова́ла єси́, Всеблага́я, і зна́менія ма́тернія любве́ Твоєя́ о́ною нам при́сно явля́єши, да поє́м Тобо́ю благоді́ющему нам Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́ї суєму́дреннії челові́честії не мо́гуть пости́гнути Боже́ственную та́йну присноді́вства Твоєго́, Марі́є Богоро́дице, ка́ко в рождестві́ і по рождестві́ ключи́ ді́вства Твоєго́ ці́ли сохрани́ла єси́, а́нгелов і челові́ков удиви́вши. Ті́мже Тя благоче́стно Ма́тер і Ді́ву іспові́дующе, при́сно Тя ублажа́єм і хвале́бно Тебі́ воспіва́єм:","Ра́дуйся, возвели́чившая род челові́чеський непоро́чною Твоє́ю чистото́ю;","ра́дуйся, освяти́вшая зе́млю всесвяти́м Твої́м рождество́м.","Ра́дуйся, ді́вство і рождество́ в Себі́ ди́вно сочета́вшая;","ра́дуйся, во обою́ непоро́чно Себі́ сохра́ньшая.","Ра́дуйся, ве́ліє вселе́нния чу́до;","ра́дуйся, непостижи́мая челові́чеськими уми́ та́йно.","Ра́дуйся, а́нгельських лико́в удивле́ніє;","ра́дуйся, святи́х Бо́жиїх уго́дников при́сноє ра́дованіє.","Ра́дуйся, ми́ра го́рняго пе́рвійшеє украше́ніє;","ра́дуйся, ми́ра до́льняго благонаде́жноє заступле́ніє.","Ра́дуйся, де́монов низложе́ніє;","ра́дуйся, а́да попра́ніє.","Ра́дуйся, Влади́чице, зна́меніє ми́лости Твоєя́ нам явля́ющая."]},{"h":"Кондак 10","ps":["Спаси́теля па́дшему челові́честву родила́ єси́, Пречи́стая Ді́во, і Сего́ я́ко Младе́нця во об'я́тіїх Твої́х носи́ла єси́, Єго́же Боже́ственноє ізображе́ніє і на іко́ні Зна́менія Твоєго́ нам явля́єши і мно́гія ми́лості і щедро́ти Твоя́ нам да́руєши. Сего́ ра́ди со благогові́нієм і ві́рою честву́єм о́браз чудотво́рний Твой, Влади́чице, і мо́лимся Тебі́ прилі́жно: бу́ди нам Покро́в і защи́та в день Су́дний, да Твої́м ма́тернім предста́тельством поми́луєть нас Судія́ Пра́ведний, Син Твой і Бог, і сподо́бит нас десна́го стоя́нія і пі́нія Єму́ со ізбра́нними: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ необори́мая і істо́чник чуде́с іко́на Твоя́ свята́я яви́ся, Богоро́дице Ді́во, не то́кмо Вели́кому Нову́граду, но і всей страні́ Украї́нській. Сію́, я́ко зна́меніє побі́дноє, іму́ще, во́їнства правосла́вния враго́в побіжда́ють, ца́ріє і святи́теліє є́ю благоукраша́ються, і всяк во́зраст ві́рних утіше́ніє благода́тноє от нея́ приє́млеть. Уті́ши і нас Твої́м, Всеми́лостивая Влади́чице, благоволе́нієм і ми́лостію, да хвале́бно взива́єм к Тебі́:","Ра́дуйся, крі́пкоє на́ше Упова́ніє;","ра́дуйся, несумні́нная на́ша Наде́ждо.","Ра́дуйся, Вели́каго Нова́града многопі́тая сла́во;","ра́дуйся, страни́ на́шея благода́тноє огражде́ніє.","Ра́дуйся, во дні бра́ні побіди́тельная на враги́ Помо́щнице;","ра́дуйся, во дні ми́ра ко благоче́стію до́брая Наста́внице.","Ра́дуйся, і́ночеських оби́телей покро́в і снабді́ніє;","ра́дуйся, благочести́вих домо́в і супру́жеств благослове́ніє.","Ра́дуйся, ді́вства і чистоти́ Побо́рнице;","ра́дуйся, оби́димих і гони́мих Предста́тельнице.","Ра́дуйся, наги́х одія́ніє;","ра́дуйся, боля́щих ісціле́ніє.","Ра́дуйся, Влади́чице, зна́меніє ми́лости Твоєя́ нам явля́ющая."]},{"h":"Кондак 11","ps":["Пі́ніє на́ше смире́нноє не пре́зри, Всеми́лостивая Цари́це, і утро́бу щедро́т Твої́х не затвори́ нам, Всеще́драя Влади́чице: се бо, обнища́вше в до́брих ді́ліх, к сокро́вищнице ми́лости Твоєя́, чудотво́рній іко́ні Твоє́й, со усе́рдієм притека́єм, Всеблага́я, і, припа́дающе, мо́лимся: озари́ нас сві́том Боже́ственния благода́ті Твоєя́ і научи́ нас ві́рно ісполня́ти за́повіді Си́на Твоєго́ і Бо́га, да досто́йно возмо́жем пі́ти Єму́: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́та невече́рняго прия́телище, сві́тлими луча́ми чуде́с Твої́х просвіща́єши нас, помраче́нних гріхо́вною мгло́ю, Богороди́тельнице Пречи́стая, і приво́диши к немо́лчному славосло́вію Твоєго́ пресвята́го і́мене. Зна́менієм іко́ни Твоєя́ святи́я воі́стину яви́ла єси́ воєво́дство Твоє́ держа́вноє, Госпоже́ Всеблага́я, єго́же сві́тло пра́зднующе, ра́достно зове́м Ті:","Ра́дуйся, возвели́ченная Бо́гом па́че земни́х і небе́сних;","ра́дуйся, єди́на Чи́стая і Благослове́нная в жена́х.","Ра́дуйся, Цари́це і Влади́чице небесе́ і землі́;","ра́дуйся, порфи́ро Царя́ царе́й.","Ра́дуйся, черто́же безсі́меннаго уневі́щенія;","ра́дуйся, глави́зно спасе́нія челові́чеськаго.","Ра́дуйся, упова́ющия на Тя не срамля́ющая;","ра́дуйся, прося́щих Твоєя́ святи́я по́мощі от бід ізбавля́ющая.","Ра́дуйся, сто́лпе і утвержде́ніє ді́вства;","ра́дуйся, щі́те і огражде́ніє ві́ри правосла́вния.","Ра́дуйся, боголі́пноє украше́ніє святи́я Христо́ви Це́ркве;","ра́дуйся, покрива́ющая всіх нас ма́терним Твої́м покро́вом.","Ра́дуйся, Влади́чице, зна́меніє ми́лости Твоєя́ нам явля́ющая."]},{"h":"Кондак 12","ps":["Благода́ть і ми́лость сви́ше пода́ждь нам, Влади́чице, от іко́ни Твоєя́ святи́я, ю́же в зна́меніє заступле́нія Твоєго́ нам дарова́ла єси́, чудеси́ от нея́ бива́ющими, правосла́вную ві́ру в нас утвержда́ющи, неві́ріє же посрамля́ющи. Ті́мже покланя́ємся Тебі́ і мо́лимся: в Правосла́вії соблюди́ нас, Всеблага́я, і сподо́би до коне́чнаго диха́нія на́шего ві́рно пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще чудеса́ Твоя́ от іко́ни Зна́менія Твоєго́ явле́нная, Богоро́дице Ді́во, хва́лим, сла́вим і велича́єм Тя, честні́йшую воі́стину Херуви́м і сла́внійшую без сравне́нія Серафи́м. Ти же, Всеблага́я Засту́пнице на́ша, покри́й нас держа́вним Твої́м покро́вом і ізба́ви нас от вся́ких бід і іскуше́ній вра́жиїх, да воспіва́єм Тебі́ непреста́нно гла́сом хвале́нія:","Ра́дуйся, богообра́дованная і непоро́чная Присноді́во;","ра́дуйся, нетлі́нная і неіскусобра́чная А́гнця і Па́стиря Ма́ти.","Ра́дуйся, увінча́нная дияди́мою ца́рською от Трієди́наго Бо́га;","ра́дуйся, святоле́пная і світоно́сная пала́то святи́х Святі́йшаго Сло́ва.","Ра́дуйся, одесну́ю стоя́щая Си́на Твоєго́ і Го́спода;","ра́дуйся, всегда́ моля́щаяся Єму́ за род христия́нський.","Ра́дуйся, Вино́внице благода́тнаго челові́ков обновле́нія;","ра́дуйся, ка́ющихся грі́шних к Бо́гу примире́ніє.","Ра́дуйся, стра́ждущих от бід Ізбавле́ніє;","ра́дуйся, Взиска́ніє поги́бших.","Ра́дуйся, тіле́с на́ших врачева́ніє;","ра́дуйся, душ на́ших спасе́ніє.","Ра́дуйся, Влади́чице, зна́меніє ми́лости Твоєя́ нам явля́ющая."]},{"h":"Кондак 13","ps":["О Всепі́тая Ма́ти Сладча́йшаго Спаси́теля на́шего, Го́спода Ісу́са Христа́! Ни́нішнєє на́ше приє́мши приноше́ніє, от вся́кия ізба́ви нас напа́сти і ско́рби і ві́чния ізми́ му́ки всіх пред свято́ю іко́ною Твоє́ю с ві́рою і любо́вію покланя́ющихся і о Тебі́ благода́рно зову́щих Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов Цари́це і всея́ тва́рі Влади́чице, Пречи́стая Ді́во Богоро́дице, пресла́вним зна́менієм іко́ни Твоєя́ святи́я всю страну́ Украї́нськую благода́тно озари́ла єси́ і струї́ чуде́с от нея́ істочи́ла єси́ ві́рним. Ті́мже, со усе́рдієм і любо́вію припа́дающе ко пречестно́му Твоєму́ о́бразу, со умиле́нієм прино́сим Ті благохвале́нія сицева́я:","Ра́дуйся, освяще́нноє селе́ніє Бо́га Сло́ва;","ра́дуйся, благода́тію Бо́жиєю і нас освяща́ющая.","Ра́дуйся, спасе́нію па́дшаго ро́да челові́чеськаго непоро́чно послужи́вшая;","ра́дуйся, всіх Творця́ і Го́спода, Чи́стая, Ду́хом Боже́ственним в ложесна́х заче́нши, без істлі́нія роди́вшая.","Ра́дуйся, ма́терним Твої́м попече́нієм всіх нас об'є́млющая;","ра́дуйся, в біда́х і напа́стіх ско́рая нам Помо́щнице.","Ра́дуйся, зли́я стра́сті на́ша неви́димо укроща́ющая;","ра́дуйся, в христия́нських доброді́теліх преуспіва́ти нам помога́ющая.","Ра́дуйся, неду́ги на́ша безме́здно врачу́ющая;","ра́дуйся, на стезі́ покая́нія нас прему́дро наставля́ющая.","Ра́дуйся, Ді́во, христия́н похвало́;","ра́дуйся, я́ко блажа́ть Тя всі ро́ди.","Ра́дуйся, Влади́чице, зна́меніє ми́лости Твоєя́ нам явля́ющая."]},{"h":"Кондак 1","ps":["Взбра́нней Воєво́ді, Влади́чиці на́шей Богоро́диці, зна́менієм іко́ни Єя́ святи́я ди́вную побі́ду лю́дем Нова́града дарова́вшей, благода́рственноє возглаша́єм пі́ніє: Ти же Всеблага́я Засту́пнице на́ша, я́ко іму́щая держа́ву непобіди́мую, от вся́ких нас бід свободи́ і от враг ви́димих і неви́димих защити́, да зове́м Ті:","Ра́дуйся, Влади́чице, зна́меніє ми́лости Твоєя́ нам явля́ющая."]},{"h":"Молитва","ps":["О Пресвята́я і Преблагослове́нная Ма́ти Сладча́йшаго Го́спода на́шего Ісу́са Христа́! Припа́даєм і покланя́ємся Тебі́ пред свято́ю чудотво́рною іко́ною Твоє́ю, воспомина́юще ди́вноє зна́меніє Твоєго́ заступле́нія, Вели́кому Нову́граду от нея́ явле́нноє во дні ра́тнаго на сей град наше́ствія. Смире́нно мо́лим Тя, всеси́льная ро́да на́шего Засту́пнице: я́коже дре́вле отце́м на́шим на по́мощ ускори́ла єси́, та́ко і ни́ні нас, немощни́х і грі́шних, сподо́би Твоєго́ ма́терняго заступле́нія і благопопече́нія. Спаси́ і сохрани́, Влади́чице, под кро́вом ми́лости Твоєя́ Це́рков святу́ю, град Твой (оби́тель Твою́), всю страну́ на́шу правосла́вную і всіх нас, припа́дающих к Тебі́ с ві́рою і любо́вію умиле́нно прося́щих со слеза́ми Твоєго́ заступле́нія. Єй, Госпоже́ Всеми́лостивая! Умилосе́рдися на ни, обурева́ємия гріхи́ мно́гими, простри́ ко Христу́ Го́споду богоприї́мнії ру́ці Твої́ і предста́тельствуй за нас пред бла́гостію Єго́, прося́щи нам проще́нія прегріше́ній на́ших, благоче́стнаго ми́рнаго житія́, благи́я христия́нськия кончи́ни і до́браго отві́та на Стра́шнім суді́ Єго́, да, спаса́ємі всеси́льними Твої́ми к Нему́ моли́твами, блаже́нство ра́йськоє унаслі́дуєм і со всі́ми святи́ми воспоє́м пречестно́є і великолі́поє і́м'я достопокланя́ємия Тро́йці, Отця́ і Си́на і Свята́го Ду́ха, і Твоє́ ве́ліє к нам милосе́рдіє, во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Я́ко необори́мую сті́ну і істо́чник чуде́с / стяжа́вше Тя раби́ Твої́, / Богоро́дице пречи́стая, / сопроти́вних ополче́нія низлага́єм. / Ті́мже мо́лим Тя: / мир гра́ду Твоєму́ да́руй // і душа́м на́шим ве́лію ми́лость."]},{"h":"Кондак, глас 4","ps":["Честна́го о́браза Твоєго́ зна́меніє / пра́зднующе лю́діє Твої́, Богороди́тельнице, / і́мже ди́вную побі́ду на сопроти́вния гра́ду Твоєму́ дарова́ла єси́. / Ті́мже Тебе́ ві́рою взива́єм: // ра́дуйся, Ді́во, христия́н похвало́."]},{"h":"Величання","ps":["Досто́йно єсть блажи́ти Тя, / Богоро́дице Ді́во, / честні́йшую Херуви́м // і сла́внійшую без сравне́нія Серафи́м.","§Або:","Піснь вся́ку духо́вную принесе́м Богоро́дице."]},{"h":"Інше величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / Богоізбра́нная Отрокови́це, / і чтим о́браз Твой святи́й, / і́мже ди́вную побі́ду на сопрати́вния // гра́ду Твоєму́ дарова́ла єси́."]},{"h":"Інше величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / і чтим о́браз Твой честни́й, / і́мже показа́ла єси́ // пресла́вноє зна́меніє."]},{"h":"Інше величання, що у Великому Новгороді","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / і чтим о́браз Твой честни́й, / і́мже побі́ду на враги́ дарова́ // гра́ду на́шему."]}],"notes":[]}];
export default D;
